/* generated by tools/build-content.js from content-source/quiz-json - do not edit by hand */
window.CONTENT = {"ch01":{"title":"Chapter 1 - Basic Principles of Insurance","flashcards":[{"front":"Define insurance.","back":"Transfer of risk through a legal contract, or pooling of funds, spreading one person's risk across a larger group.","topic":"Definition","memory":"","source":"Cornell LII Wex, Insurance https://www.law.cornell.edu/wex/insurance"},{"front":"Who owns a mutual company?","back":"Its policyholders (NAIC: a privately held insurer owned by its policyholders).","topic":"Stock vs mutual","memory":"MUTUAL = MEMBERS","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"front":"Risk retention group (RRG)?","back":"Group-owned insurer covering liability risks. Licensed in one state, operates in all states.","topic":"Company types","memory":"","source":"15 U.S.C. 3901-3902 https://www.law.cornell.edu/uscode/text/15/3902"},{"front":"Ceding company vs reinsurer?","back":"The ceding company transfers risk by purchasing reinsurance. The reinsurer agrees to cover all or part of the ceder's losses.","topic":"Reinsurance","memory":"CEDE = GIVE AWAY","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"front":"Domestic, foreign, alien insurer?","back":"Domestic: formed under the laws of this state. Foreign: formed under the laws of another U.S. state or territory or D.C. Alien: formed under the laws of a country other than the U.S.","topic":"Classification","memory":"Alien = Alien country","source":"La. R.S. 22:46 https://www.legis.la.gov/Legis/LawPrint.aspx?d=506206"},{"front":"Admitted vs non-admitted insurer?","back":"Admitted (authorized) insurer holds a certificate of authority or license from the state. Non-admitted does not.","topic":"Classification","memory":"","source":"La. R.S. 22:46 and NAIC Glossary https://www.legis.la.gov/Legis/LawPrint.aspx?d=506206"},{"front":"Lloyd's of London is what?","back":"A specialist insurance market, not a single insurer. Syndicates of underwriters price and underwrite risk there; the Lloyd's Corporation is itself not an insurer.","topic":"Other entities","memory":"","source":"Lloyd's (lloyds.com) https://www.lloyds.com/about-lloyds/what-is-lloyds"},{"front":"Agent vs broker: whom does each represent?","back":"Agent represents the insurer. Broker represents the client/insured. A public adjuster represents the insured.","topic":"Key people","memory":"AGENT = ATTACHED to insurer; BROKER = BUYER's side","source":"NAIC consumer article; also La. R.S. 22:1704(E) legis.la.gov https://content.naic.org/article/consumer-insight-how-choose-insurance-agent"},{"front":"Three types of agent authority?","back":"Express (stated), implied (needed to do the job), apparent (looks real to the public due to principal's conduct).","topic":"Agent authority","memory":"Said / Needed / Looks real","source":"Cornell LII Wex (express, implied, apparent authority) https://www.law.cornell.edu/wex/apparent_authority"},{"front":"Captive agent vs independent agent?","back":"Captive (career) agent works for one insurer. Independent agent represents multiple insurers.","topic":"Selling","memory":"","source":"NAIC consumer article https://content.naic.org/article/consumer-insight-how-choose-insurance-agent"},{"front":"McCarran-Ferguson Act (1945) main point?","back":"States keep regulating insurance. No Act of Congress overrides a state insurance law unless the Act specifically relates to the business of insurance (15 U.S.C. 1012).","topic":"Federal timeline","memory":"","source":"15 U.S.C. 1012 (Cornell LII) https://www.law.cornell.edu/uscode/text/15/1012"},{"front":"Can a producer cite guaranty association protection in a sale?","back":"No. Producers cannot use guaranty association protection in sales presentations.","topic":"Guaranty associations","memory":"","source":"La. R.S. 22:2098 https://www.legis.la.gov/Legis/LawPrint.aspx?d=509256"}],"questions":[{"q":"Insurance is best defined as:","choices":["Transfer of risk through a legal contract or pooling of funds","Elimination of all risk","A savings plan managed by the state","A guarantee against all loss"],"answer":0,"explain":"Source: Cornell LII Wex, \"Insurance\": an arrangement in which one party agrees to indemnify another against a predefined category of risks for a premium. Premiums are pooled to pay losses. Source: Cornell LII Wex, Insurance.","topic":"Definition","source":"Cornell LII Wex, Insurance https://www.law.cornell.edu/wex/insurance"},{"q":"Who owns a mutual insurance company?","choices":["Stockholders","The state","Its policyholders","Its agents"],"answer":2,"explain":"Source: NAIC Glossary of Insurance Terms. A mutual insurance company is a privately held insurer owned by its policyholders.","topic":"Stock vs mutual","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"An insurer whose principal office is in Germany and sells in the U.S. is:","choices":["Domestic","Foreign","Alien","Non-admitted by definition"],"answer":2,"explain":"Source: La. R.S. 22:46(1) and (11). \"Alien\" means formed under the laws of a country other than the U.S. \"Foreign\" means formed under the laws of another U.S. state or D.C.","topic":"Classification","source":"La. R.S. 22:46 https://www.legis.la.gov/Legis/LawPrint.aspx?d=506206"},{"q":"The ceding company in a reinsurance arrangement is the one that:","choices":["Accepts the risk","Passes part of the risk away","Regulates the reinsurer","Sells only one line"],"answer":1,"explain":"Source: NAIC Glossary of Insurance Terms. A ceding company transfers risk by purchasing reinsurance; the reinsurer agrees to cover all or part of the losses.","topic":"Reinsurance","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"Which type of agent authority is created when the principal's conduct makes a third party reasonably believe an agent is authorized?","choices":["Express","Implied","Apparent","Fiduciary"],"answer":2,"explain":"Source: Cornell LII Wex, Apparent authority. It arises when a third party reasonably concludes from the principal's behavior that the agent has the power, even though it was not expressly or impliedly granted.","topic":"Agent authority","source":"Cornell LII Wex, Apparent authority https://www.law.cornell.edu/wex/apparent_authority"},{"q":"A risk retention group is chartered in how many states and may operate in how many?","choices":["One chartered, may operate in all","All chartered, operates in one","Two chartered, operates in two","One chartered, operates in one"],"answer":0,"explain":"Source: 15 U.S.C. 3901-3902. A risk retention group is chartered or licensed in one state, which regulates its formation and operation; other states may not otherwise regulate it, so it can operate in all states.","topic":"Company types","source":"15 U.S.C. 3901-3902 (Liability Risk Retention Act) https://www.law.cornell.edu/uscode/text/15/3902"},{"q":"Which cost index period is typically used for the net payment cost index?","choices":["1 or 2 years","5 years only","10 or 20 years","30 years only"],"answer":2,"explain":"Net payment and surrender cost indexes compare cost over a set period, usually 10 or 20 years. Source: NAIC model Life Insurance Buyer's Guide (as adopted, 760 IAC 1-24-9).","topic":"Disclosures","source":"NAIC model Life Insurance Buyer's Guide (as adopted, 760 IAC 1-24-9) https://www.law.cornell.edu/regulations/indiana/760-IAC-1-24-9"},{"q":"Under 18 U.S.C. 1033(e)(1)(A), a person convicted of a felony involving dishonesty or breach of trust who willfully engages in the business of insurance is subject to imprisonment of up to:","choices":["1 year","5 years","15 years","Life"],"answer":1,"explain":"Source: 18 U.S.C. 1033(e)(1)(A). Penalty is a fine or imprisonment not more than 5 years, or both. The 10- and 15-year maximums are in 1033(a)(2), (b)(2), (c)(2). Under (e)(2) such a person may work in insurance with written consent of the insurance regulator.","topic":"Federal timeline","source":"18 U.S.C. 1033 https://www.law.cornell.edu/uscode/text/18/1033"},{"q":"Which is NOT true of Lloyd's of London?","choices":["It is a marketplace for unusual risks","It is itself a single insurer","Individuals and companies underwrite there","It is a typical stock insurance company owned by shareholders"],"answer":1,"explain":"Lloyd's is not an insurer at all; it is a marketplace where members underwrite unusual risks. Source: Lloyd's (lloyds.com).","topic":"Other entities","source":"Lloyd's (lloyds.com) https://www.lloyds.com/en-us/lloyds-around-the-world/us/policyholders"},{"q":"Which is NOT a correct statement about the 1999 Gramm-Leach-Bliley Act?","choices":["It requires a privacy notice and opt-out before sharing nonpublic personal information with nonaffiliated third parties","It lets banks, insurers and securities firms combine","It requires affirmative consent before sharing any information with any third party","It allows a customer to opt out of certain sharing with nonaffiliated third parties"],"answer":2,"explain":"Source: 15 U.S.C. 6802. GLBA is a notice-and-opt-out law: the institution must give notice and an opportunity to opt out before disclosing nonpublic personal information to nonaffiliated third parties. It does not require affirmative consent.","topic":"Federal timeline","source":"15 U.S.C. 6802 (GLBA) https://www.law.cornell.edu/uscode/text/15/6802"},{"q":"Which statement about the broker is correct?","choices":["The broker represents the insurer in disputes","The broker represents the client/insured","The broker is always a captive agent","The broker works only for one insurer"],"answer":1,"explain":"Source: NAIC Glossary of Insurance Terms. Brokers work on behalf of the customer and are not restricted to selling for a specific company.","topic":"Key people","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"}],"scenarios":[{"situation":"Carl sells only for one insurance company and is paid by that company. His client Maria also visited another office and received quotes from several insurers.","q":"How should Carl and the quote-shopping office be described?","choices":["Carl is independent; the other office is captive","Carl is a captive agent; the other office is an independent agent or broker","Both are captive agents","Carl is a broker; the other office is a public adjuster"],"answer":1,"explain":"Source: IRMI Glossary. Captive agents work only for one insurer; independent agents sell for one or more insurers, and brokers represent the buyer.","topic":"Selling","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/captive-agents"},{"situation":"Ray's insurer denies his claim. Ray hires someone, paid by Ray, to fight the denial and settle the claim.","q":"Whom does this person work for?","choices":["The insurer","The insured","The state insurance department","The reinsurer"],"answer":1,"explain":"Source: IRMI Glossary. A public adjuster represents the insured and negotiates with the insurer's claim representative.","topic":"Key people","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/public-adjuster"},{"situation":"A company says it is authorized to do business in Florida, but its headquarters is in Canada.","q":"How is it classified in Florida?","choices":["Domestic","Foreign","Alien","Mutualized"],"answer":2,"explain":"Source: IRMI Glossary. An alien insurer is domiciled outside the United States but authorized to operate in it. Foreign would mean another U.S. state.","topic":"Classification","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/alien-insurer"}],"pairs":[{"term":"Domestic insurer","match":"Formed under Louisiana law","source":"La. R.S. 22:46 https://legis.la.gov/Legis/Law.aspx?d=506206"},{"term":"Alien insurer","match":"Formed under the laws of a country other than the U.S.","source":"La. R.S. 22:46 https://legis.la.gov/Legis/Law.aspx?d=506206"},{"term":"Ceding company","match":"Insurer that cedes all or part of its risk to a reinsurer","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/ceding-company"},{"term":"Public adjuster","match":"Represents the insured in settling claims","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/public-adjuster"},{"term":"Apparent authority","match":"Authority a reasonable person would believe the agent has (estoppel doctrine)","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/apparent-agency"},{"term":"Demutualization","match":"Mutual company becomes a stock company","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/demutualization"}]},"ch02":{"title":"Chapter 2 - Nature of Insurance, Risk, Perils, and Hazards","flashcards":[{"front":"Peril vs hazard?","back":"Peril: the cause of loss. Hazard: a circumstance that tends to increase the probability or severity of a loss (NAIC Consumer Glossary).","topic":"Peril/hazard/loss","memory":"Peril = the Pow; Hazard = the Hint","source":"NAIC Consumer Glossary https://content.naic.org/consumer_glossary"},{"front":"Law of large numbers?","back":"As more similar risks are grouped, total losses become more predictable. Insurers predict group losses, not one person's loss.","topic":"Foundations","memory":"BIG GROUP = BIG PREDICTION","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/law-of-large-numbers"},{"front":"Principle of indemnity?","back":"Put the insured back in the same financial position as before the loss, with no profit from the loss.","topic":"Indemnity","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/consumer_glossary"},{"front":"Is life insurance a contract of indemnity?","back":"No. It is a valued contract that pays a fixed amount regardless of actual financial loss.","topic":"Indemnity","memory":"","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/valued-policy"},{"front":"Which health coverage is indemnity vs valued?","back":"Expense-reimbursement medical pays the actual covered expense (indemnity). Fixed-amount products such as hospital indemnity and critical illness pay a set amount regardless of the bill, like a valued contract.","topic":"Indemnity","memory":"Pays the bills = indemnity; pays a set amount = valued","source":"Maryland Insurance Administration https://insurance.maryland.gov/Consumer/Pages/Hospital-Fixed-Indemnity.aspx"},{"front":"Adverse selection?","back":"People with a higher than average chance of loss seek more insurance coverage than lower-risk people, which works against the insurer.","topic":"Adverse selection","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/consumer_glossary"},{"front":"Speculative vs pure risk?","back":"Speculative risk can produce loss or gain and is not insurable. Pure risk can only produce loss and is insurable.","topic":"Risk types","memory":"Pure = Possible Only Loss","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/speculative-risk"},{"front":"Elements of an insurable risk?","back":"Many exposure units; losses accidental or random; losses determinable and measurable; not catastrophic to the pool; probability and consequences calculable; premium economically affordable.","topic":"Insurable risk","memory":"","source":"NAIC Journal of Insurance Regulation (Kunreuther and Schupp, 2021) https://content.naic.org/sites/default/files/JIR-ZA-40-10-EL.pdf"},{"front":"Standard, substandard, preferred risk?","back":"Standard: average loss potential. Substandard: undesirable due to medical condition or hazardous occupation, handled with a waiver, special policy form or higher premium. Preferred: likelihood of loss lower than the standard applicant.","topic":"Risk classes","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/consumer_glossary"},{"front":"Named perils vs open perils?","back":"Named: only listed perils covered. Open: everything covered except specific exclusions.","topic":"Perils","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/consumer_glossary"},{"front":"Direct vs indirect loss?","back":"Direct: caused immediately by the peril. Indirect (consequential): a secondary result of the direct loss.","topic":"Loss","memory":"","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/indirect-damage-loss"},{"front":"Accident vs occurrence?","back":"Accident: an unexpected event without deliberate intent. Occurrence: an accident, including continuous or repeated exposure to the same harmful conditions. Every accident is an occurrence.","topic":"Loss","memory":"","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/occurrence"},{"front":"Physical hazard?","back":"A tangible, observable condition such as icy walkways, poor lighting or high blood pressure.","topic":"Hazards","memory":"Physical = you can SEE it","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/physical-hazard"},{"front":"Moral vs morale hazard?","back":"Moral: a loss-increasing hazard arising from the character or circumstances of the insured (such as dishonesty). Morale: indifference or carelessness toward loss because insurance exists.","topic":"Hazards","memory":"Moral = character; Morale = attitude","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/morale-hazard"},{"front":"Steps of risk management?","back":"Identify risks, measure them, choose a treatment method, implement the plan, and monitor and adjust over time.","topic":"Risk management","memory":"","source":"IRMI Personal Risk Management overview https://www.irmi.com/articles/expert-commentary/personal-risk-management-an-overview"}],"questions":[{"q":"The direct, specific cause of a loss is called a:","choices":["Hazard","Peril","Risk","Exposure"],"answer":1,"explain":"A peril is the cause (fire, theft). A hazard is a condition that makes a peril more likely. Source: NAIC Consumer Glossary.","topic":"Peril/hazard/loss","source":"NAIC Consumer Glossary https://content.naic.org/consumer_glossary"},{"q":"Personality characteristics of the insured that increase the probability of loss are called a:","choices":["Physical hazard","Morale hazard","Moral hazard","Peril"],"answer":2,"explain":"Source: NAIC Consumer Glossary, \"Moral Hazard\": personality characteristics that increase probability of losses. \"Morale Hazard\" is negligence or disregard by the insured.","topic":"Hazards","source":"NAIC Consumer Glossary https://content.naic.org/consumer_glossary"},{"q":"Under a named-peril policy, a loss from a peril that is not listed is:","choices":["Covered","Not covered","Covered at half value","Covered only if sudden"],"answer":1,"explain":"Source: NAIC Consumer Glossary, \"Named Peril Coverage\": insurance for losses explicitly defined in the policy contract. An all-risk (open peril) policy covers risks not explicitly excluded.","topic":"Perils","source":"NAIC Consumer Glossary https://content.naic.org/consumer_glossary"},{"q":"Which describes a substandard risk?","choices":["Lower likelihood of loss than the standard applicant","A normal risk insurable at standard rates","A risk deemed undesirable (e.g., medical condition or hazardous occupation) needing a waiver, special form, or higher premium","No loss potential"],"answer":2,"explain":"Source: NAIC Consumer Glossary, \"Substandard Risk\" (impaired risk): undesirable due to medical condition or hazardous occupation, requiring a waiver, special policy form, or higher premium. \"Preferred Risk\" is lower than standard.","topic":"Risk classes","source":"NAIC Consumer Glossary https://content.naic.org/consumer_glossary"}],"scenarios":[{"situation":"Jim has a history of heart disease and applies for life insurance. He plans to leave out his doctor visits on the application.","q":"Which concern best describes Jim's planned omission?","choices":["Morale hazard","Moral hazard (intentional dishonesty)","Physical hazard","Speculative risk"],"answer":1,"explain":"Source: IRMI Glossary. Moral hazard comes from the insured's character, such as dishonesty. Morale hazard is indifference, not dishonesty.","topic":"Hazards","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/moral-hazard"},{"situation":"Ann leaves her car unlocked with the keys inside because she figures her full coverage will pay if it is stolen. She does not intend for it to be stolen.","q":"Which hazard is this?","choices":["Moral hazard","Morale hazard","Physical hazard","Pure peril"],"answer":1,"explain":"Source: IRMI Glossary. Morale hazard is indifference to loss because insurance will pay. It reflects attitude, not dishonesty.","topic":"Hazards","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/morale-hazard"},{"situation":"A business owner installs sprinklers and fire doors to lower how bad a fire loss could be.","q":"Which risk-handling method is this?","choices":["Avoidance","Transfer","Reduction (loss control)","Retention"],"answer":2,"explain":"Source: IRMI Glossary. Loss reduction lowers how severe a loss is, such as firewalls and sprinklers.","topic":"Risk management","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/loss-reduction"}],"pairs":[{"term":"Peril","match":"Direct cause of a loss, such as fire","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/peril"},{"term":"Hazard","match":"Condition that increases the chance a peril occurs","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/hazard"},{"term":"Pure risk","match":"Chance of loss only; insurable","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/pure-risk"},{"term":"Moral hazard","match":"Insured's character or finances make a covered loss more likely or costly","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/moral-hazard"},{"term":"Morale hazard","match":"Carelessness about preventing loss because insurance will pay","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/morale-hazard"},{"term":"Open perils","match":"Everything covered except what is excluded","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/open-perils"}]},"ch03":{"title":"Chapter 3 - Legal Concepts of Insurance","flashcards":[{"front":"Four essential elements of a valid insurance contract?","back":"Offer and acceptance, consideration, legal purpose, competent parties. All four must be present.","topic":"Contract elements","memory":"OCLC: Only Contracts Legally Count","source":"Cornell LII Wex: contract https://www.law.cornell.edu/wex/contract"},{"front":"Aleatory contract?","back":"Unequal exchange: one party may receive far more than it gave, depending on a future event.","topic":"Contract features","memory":"AUAPC","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/aleatory-contract"},{"front":"Contract of adhesion?","back":"Drafted by one party (the insurer), take it or leave it. Ambiguity is read against the insurer.","topic":"Contract features","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/contract-of-adhesion"},{"front":"Unilateral contract?","back":"Only one party (the insurer) makes a binding promise. The applicant can stop paying premiums.","topic":"Contract features","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/unilateral-contract"},{"front":"Valued contract?","back":"A policy that pays a predefined amount not related to the actual loss incurred. Used mostly in life insurance.","topic":"Valued vs indemnity","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/valued-policy"},{"front":"What is insurable interest?","back":"Property: a lawful and substantial economic interest in the safety or preservation of the insured thing (R.S. 22:853). Personal insurance: a lawful and substantial economic interest in the insured's continued life, health or safety, or for relatives a substantial interest from love and affection (R.S. 22:901). Without it the contract is not enforceable.","topic":"Insurable interest","memory":"","source":"La. R.S. 22:901 and 22:853 https://legis.la.gov/Legis/Law.aspx?d=507771"},{"front":"When must insurable interest exist for life and health?","back":"At the time of application only.","topic":"Insurable interest","memory":"Life/Health = Application","source":"La. R.S. 22:901 (personal insurance) https://legis.la.gov/Legis/Law.aspx?d=507771"},{"front":"Concealment?","back":"A willful act of holding back information that may be pertinent to issuing the policy. It can result in the policy being voided.","topic":"Good faith","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/concealment"},{"front":"Waiver vs estoppel?","back":"Waiver: voluntarily giving up a known right. Estoppel: a party is stopped from denying what it said or did when another relied on it and was harmed.","topic":"Waiver/estoppel","memory":"","source":"IRMI Glossary (waiver, estoppel) https://www.irmi.com/term/insurance-definitions/waiver"},{"front":"Agent vs broker: whom does each represent?","back":"Agent: tied to specific insurers that grant binding authority, so the insurer is bound by the agent's acts. Broker: independent and deemed the customer's representative. Louisiana R.S. 22:1542 licenses both (and solicitors) as producers.","topic":"Agency","memory":"","source":"La. R.S. 22:1542 and Insurance Journal (Louisiana law) https://www.legis.la.gov/Legis/LawPrint.aspx?d=508516"},{"front":"Subrogation?","back":"The insurer's right to recover from the third party who caused the loss after paying its insured.","topic":"Legal doctrines","memory":"SUBSTITUTE: steps into insured's shoes","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/subrogation"},{"front":"Parol evidence rule?","back":"The written contract prevails over oral statements made before it. Prior verbal statements cannot change written terms.","topic":"Legal doctrines","memory":"","source":"Cornell LII Wex https://www.law.cornell.edu/wex/parol_evidence_rule"}],"questions":[{"q":"Which is NOT one of the four essential elements of a valid insurance contract?","choices":["Consideration","Legal purpose","Competent parties","Witnessed signature"],"answer":3,"explain":"The four are offer and acceptance, consideration, legal purpose, competent parties. A witness is not among them. Source: Cornell LII Wex: contract.","topic":"Contract elements","source":"Cornell LII Wex: contract https://www.law.cornell.edu/wex/contract"},{"q":"A contract that is drafted by the insurer and read against the insurer when ambiguous is:","choices":["Aleatory","Adhesion","Unilateral","Conditional"],"answer":1,"explain":"Adhesion means take it or leave it, so ambiguity favors the insured. Source: Cornell LII Wex: adhesion contract.","topic":"Contract features","source":"Cornell LII Wex: adhesion contract https://www.law.cornell.edu/wex/adhesion_contract"},{"q":"Insurable interest is best described as:","choices":["Interest earned on cash value","A financial stake in the insured person or property","The insurer's profit","The producer's commission"],"answer":1,"explain":"Insurable interest is the buyer's financial stake. Without it the contract is a wager. Source: NAIC Glossary of Insurance Terms.","topic":"Insurable interest","source":"NAIC Glossary of Insurance Terms https://content.naic.org/consumer_glossary"},{"q":"A statement believed by the applicant to be true is a:","choices":["Warranty","Representation","Concealment","Counter-offer"],"answer":1,"explain":"Representation is believed true. A warranty is guaranteed true in all respects. Source: La. R.S. 22:860.","topic":"Good faith","source":"La. R.S. 22:860 https://legis.la.gov/legis/Law.aspx?d=507741"},{"q":"Bob and Sherry bought life policies on each other while married, then divorced and kept the policies. When must insurable interest have existed?","choices":["At application only","At claim only","At both application and claim","At every premium due date"],"answer":0,"explain":"For life insurance, interest is required at application. The divorce does not void the policy. Source: La. R.S. 22:901.","topic":"Insurable interest","source":"La. R.S. 22:901 https://legis.la.gov/Legis/Law.aspx?d=507771"},{"q":"Which element may be required at the time of loss for property insurance but is NOT required at claim time for life insurance?","choices":["Offer and acceptance","Insurable interest at the time of claim","Consideration","Legal purpose"],"answer":1,"explain":"Source: IRMI; La. R.S. 22:901. Property insurance may require insurable interest at the time of loss, while life insurance requires it when the contract was made.","topic":"Insurable interest","source":"IRMI; La. R.S. 22:901 https://www.irmi.com/articles/expert-commentary/insurable-interests-and-interests-insured-in-property-insurance"},{"q":"Which is NOT true about void contracts?","choices":["They lack legal effect","They are missing an essential element","They are enforceable until one party sets them aside","A contract for an illegal purpose is an example"],"answer":2,"explain":"A void contract is not enforceable. A voidable one is binding until voided. Source: Cornell LII Wex: voidable / void.","topic":"Void vs voidable","source":"Cornell LII Wex: voidable / void https://www.law.cornell.edu/wex/voidable"},{"q":"Which statement about brokers is NOT correct?","choices":["A broker represents the buyer in a sale","A broker may place coverage with multiple insurers","A broker represents the insurer in disputes","An agent is the insurer's representative"],"answer":2,"explain":"A broker represents the buyer, not the insurer. In disputes, the agent represents the insurer. Source: NAIC Glossary of Insurance Terms.","topic":"Agency","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"Under Louisiana Civil Code art. 1918, which of these is NOT a person lacking capacity to contract?","choices":["An unemancipated minor","An interdict","A person deprived of reason at the time of contracting","An adult of sound mind who is not interdicted"],"answer":3,"explain":"Source: Louisiana Civil Code art. 1918. All persons have capacity to contract except unemancipated minors, interdicts, and persons deprived of reason at the time of contracting.","topic":"Contract elements","source":"Louisiana Civil Code art. 1918 https://www.legis.la.gov/Legis/Law.aspx?d=109165"}],"scenarios":[{"situation":"An agent tells an applicant that the policy covers all damages. The applicant relies on this and buys no more coverage. A claim is later denied because the policy does not cover that loss.","q":"Which doctrine may prevent the insurer from denying the claim?","choices":["Subrogation","Parol evidence","Estoppel","Rescission"],"answer":2,"explain":"Source: IRMI Glossary. Estoppel stops a party from going back on its own earlier words or conduct when the other party reasonably relied on them.","topic":"Waiver/estoppel","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/estoppel"},{"situation":"An insurer pays for repairs to a policyholder's car after a crash caused by another driver. The insurer then wants to recover its payment.","q":"What right does the insurer use?","choices":["Subrogation","Waiver","Reasonable expectations","Coinsurance"],"answer":0,"explain":"Source: IRMI Glossary. After paying a loss, the insurer takes over the insured's right to recover from the party at fault.","topic":"Legal doctrines","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/subrogation"},{"situation":"Sarah owns a car with an auto policy. She tries to buy a policy on her neighbor Mike's car, in which she has no financial stake.","q":"What is the problem?","choices":["She has no insurable interest, so the policy cannot be enforced for her","The contract is conditional","The policy is unilateral","She is a solicitor"],"answer":0,"explain":"Source: La. R.S. 22:853. A property policy is enforceable only for people with an insurable interest, a real economic stake in the property.","topic":"Insurable interest","source":"La. R.S. 22:853 https://legis.la.gov/Legis/Law.aspx?d=507734"}],"pairs":[{"term":"Warranty","match":"Guarantee; an insured's factual statement that, if untrue, may void the policy","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/warranty"},{"term":"Representation","match":"Statement believed true to the best of knowledge","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/representation"},{"term":"Waiver","match":"Voluntary giving up of a known right","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/waiver"},{"term":"Subrogation","match":"Insurer's right to recover from the at-fault third party","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/subrogation"},{"term":"Aleatory","match":"Contract based on an uncertain event, with unequal value exchanged","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/aleatory-contract"},{"term":"Rescission","match":"Insurer's declaration that the policy was never in effect","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/rescission"}]},"ch04":{"title":"Chapter 4 - Life Underwriting","flashcards":[{"front":"What is underwriting?","back":"Research and assessment of possible policyholders to decide eligibility and rate. Also called risk selection; it fights adverse selection.","topic":"Underwriting purpose","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/underwriting"},{"front":"When must insurable interest exist for life insurance?","back":"Only at policy inception (application), not when proceeds are paid.","topic":"Insurable interest","memory":"","source":"La. R.S. 22:901 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507771"},{"front":"Are application statements warranties or representations?","back":"Representations, not warranties. In Louisiana a misstatement defeats the policy only if made with actual intent to deceive and it materially affected acceptance of the risk or the hazard assumed (La. R.S. 22:860).","topic":"Application","memory":"","source":"La. R.S. 22:860 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507741"},{"front":"What is the MIB?","back":"Medical Information Bureau, the shared database of health information from past applications, provided to member insurers.","topic":"Information sources","memory":"","source":"MIB, Who is MIB https://www.mib.com/facts_about_mib.html"},{"front":"Free-look period?","back":"Time to return an individual life policy for a full refund. In Louisiana it is 10 days from receipt of the policy.","topic":"Free look","memory":"","source":"La. R.S. 22:931(A)(10)(a) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"front":"What must a producer do for a replacement?","back":"Get signed statements on existing coverage, read and give the Notice Regarding Replacement when coverage exists, and leave sales materials. The replacing insurer notifies the existing insurer within 5 business days (Reg 70).","topic":"Replacement","memory":"","source":"LAC 37:XIII.8907 and 8911 (Regulation 70) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-8907"},{"front":"Under the FCRA, do the usual 7-year and 10-year reporting limits apply to life insurance with a large face amount?","back":"No. The limits do not apply when life insurance underwriting involves, or may reasonably be expected to involve, a face amount of $150,000 or more. The same exemption covers credit of $150,000 or more and employment at a salary of $75,000 or more.","topic":"FCRA reporting limits","memory":"$150K = limits waived","source":"15 U.S.C. 1681c(b), Cornell LII https://www.law.cornell.edu/uscode/text/15/1681c"},{"front":"Which Louisiana rules govern insurer HIV testing and results?","back":"Insurers' HIV testing practices and results are governed exclusively by Title 22 (Insurance Code) and the Commissioner's regulations (R.S. 40:1171.1; LAC 48:I.13507).","topic":"HIV testing","memory":"","source":"LAC 48:I.13507 and R.S. 40:1171.1 https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-48-SS-I-13507"}],"questions":[{"q":"Underwriting is also known as:","choices":["Claim adjustment","Risk selection","Reinsurance","Surrender processing"],"answer":1,"explain":"Underwriting evaluates and selects risks. Adjusting relates to claims. Source: IRMI Glossary.","topic":"Underwriting purpose","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/underwriting"},{"q":"The risk class that pays a reduced premium is:","choices":["Standard","Preferred","Substandard","Declined"],"answer":1,"explain":"Preferred is the lowest-risk class. Standard pays regular premium. Source: IRMI Glossary.","topic":"Risk classes","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/preferred-risk"},{"q":"Which database holds health information from past applications?","choices":["MIB","APS","ACA","NAIC"],"answer":0,"explain":"The Medical Information Bureau shares health history among member insurers. Source: MIB Group.","topic":"Information sources","source":"MIB Group https://www.mib.com/facts_about_mib.html"},{"q":"Which is NOT a requirement for a replacement?","choices":["Notice Regarding Replacement","Inform the existing insurer","State-mandated disclosure form","Waiting 5 years before replacing"],"answer":3,"explain":"The requirements are the notice, informing the existing insurer, and the state form. There is no 5-year wait. Source: LAC 37:XIII.8911 (Regulation 70).","topic":"Replacement","source":"LAC 37:XIII.8911 (Regulation 70) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-8911"}],"scenarios":[{"situation":"An applicant pays the first premium with the application and receives a conditional receipt. She dies before the policy is issued, and the underwriter finds she met the insurer's insurability standards.","q":"What is the likely result?","choices":["No coverage, since the policy was not issued","Coverage applies back to the date set by the receipt, since she was insurable","Only a premium refund","Coverage only after delivery"],"answer":1,"explain":"Source: IRMI Glossary. With a conditional receipt, if the risk is accepted, coverage starts from the date of the receipt.","topic":"Premium receipts","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/conditional-binding-receipt"},{"situation":"A producer wants a client to cancel an existing life policy and buy a new one from the producer's company.","q":"What must the producer do?","choices":["Nothing special; it is a normal sale","Present and read the replacement notice by the time the application is taken, signed by both","Notify the existing insurer himself within 30 days","Wait for the free look to expire"],"answer":1,"explain":"Source: La. Admin. Code tit. 37, §XIII-8907 (Regulation 70). The producer presents and reads the Notice Regarding Replacement, signed by applicant and producer. The replacing insurer then notifies the existing insurer.","topic":"Replacement","source":"La. Admin. Code tit. 37, §XIII-8907 (Regulation 70) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-8907"},{"situation":"A healthy applicant who goes skydiving every weekend applies for life coverage.","q":"How might the underwriter classify the applicant?","choices":["Preferred automatically","Substandard, issued as a rated policy at a higher premium","Declined only","Standard with no ratings"],"answer":1,"explain":"Source: IRMI Glossary. A substandard risk is less than standard and gets a rated policy with a higher premium. A risky hobby can put a healthy person there.","topic":"Risk classes","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/rated-policy"}],"pairs":[{"term":"Conditional receipt","match":"Coverage from the receipt date, but only if the insurer accepts the risk","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/conditional-binding-receipt"},{"term":"MIB","match":"Member-maintained database of coded underwriting information used to cross-check applications","source":"MIB - The Facts About MIB's Underwriting Services https://www.mib.com/facts_about_mib.html"},{"term":"Substandard","match":"Risk deemed undesirable due to medical condition or hazardous occupation","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"}]},"ch05_1":{"title":"Chapter 5.1 - Life Insurance (Types of Policies)","flashcards":[{"front":"Term life insurance basics?","back":"Pure death protection for a set period. Pays only if the insured dies during the term. No cash value. Also called temporary insurance.","topic":"Term","memory":"","source":"NAIC life insurance consumer page https://content.naic.org/consumer/life-insurance.htm"},{"front":"Renewable vs convertible term?","back":"Renewable: keep term coverage without proof of insurability, premium rises. Convertible: switch to permanent without proof of insurability.","topic":"Term","memory":"Renewable = same coverage, pay more; Convertible = switch, no health questions","source":"NAIC life insurance consumer page https://content.naic.org/consumer/life-insurance.htm"},{"front":"Endowment policy?","back":"Cash value grows fast so it matures before age 100. Pays a death benefit during the period or the face amount at maturity if alive.","topic":"Endowment","memory":"","source":"Cornell LII Wex: Endowment insurance https://www.law.cornell.edu/wex/endowment_insurance"},{"front":"Who bears investment risk in variable life?","back":"The policyowner bears all investment risk. Agents need a life license and a FINRA registered representative license.","topic":"Variable products","memory":"","source":"FINRA Notice to Members 00-44 https://www.finra.org/rules-guidance/notices/00-44"},{"front":"What is a MEC and the 7-pay test?","back":"A life contract that fails the 7-pay test of IRC 7702A(b): premiums paid in the first 7 contract years exceed the net level premiums needed for a paid-up contract after seven level annual premiums.","topic":"MEC","memory":"","source":"26 U.S.C. 7702A https://www.law.cornell.edu/uscode/text/26/7702A"},{"front":"MEC tax treatment?","back":"Distributions and loans are taxed income first (IRC 72(e)(10)), plus a 10 percent additional tax on the taxable portion unless the owner is 59 and a half or older (72(v)).","topic":"MEC","memory":"","source":"26 U.S.C. 72(v) https://www.law.cornell.edu/uscode/text/26/72"},{"front":"Participating vs nonparticipating?","back":"Participating policies pay dividends (reduce premiums, buy more coverage, or take cash). Nonparticipating pay none.","topic":"Dividends","memory":"","source":"NAIC Consumer Glossary https://content.naic.org/consumer_glossary"},{"front":"What must a life insurance contract satisfy under IRC section 7702?","back":"It must meet either the cash value accumulation test or the guideline premium test. Both limit how much cash value can build relative to the death benefit. A contract that fails them loses its life insurance tax treatment.","topic":"Tax definition of life insurance","memory":"7702 = TWO TESTS","source":"26 U.S.C. 7702 https://www.law.cornell.edu/uscode/text/26/7702"}],"questions":[{"q":"Which type of policy provides death protection for a set period with no cash value?","choices":["Whole life","Term life","Universal life","Endowment"],"answer":1,"explain":"Term is temporary protection with no cash value. Source: NAIC Life Insurance consumer page.","topic":"Term","source":"NAIC Life Insurance consumer page https://content.naic.org/consumer/life-insurance.htm"},{"q":"The 7-pay test applies to determining whether a policy is:","choices":["Participating","A MEC","Convertible","Renewable"],"answer":1,"explain":"Failing the 7-pay test makes the policy a MEC. Source: 26 U.S.C. 7702A, Cornell LII.","topic":"MEC","source":"26 U.S.C. 7702A, Cornell LII https://www.law.cornell.edu/uscode/text/26/7702A"},{"q":"A MEC withdrawal before age 59 and a half is generally taxed:","choices":["FIFO, no penalty","LIFO with a 10 percent penalty","Never taxed","Only at death"],"answer":1,"explain":"MEC distributions are LIFO (gains first) and carry a 10 percent penalty before 59 and a half. Source: 26 U.S.C. 72(e)(10) and 72(v), Cornell LII.","topic":"MEC","source":"26 U.S.C. 72(e)(10) and 72(v), Cornell LII https://www.law.cornell.edu/uscode/text/26/72"},{"q":"Under Louisiana consumer credit law, credit life insurance on a loan cannot exceed:","choices":["Twice the total sum payable","Half the debt","The total sum payable under the contract, including finance and credit service charges","$50,000"],"answer":2,"explain":"Source: La. R.S. 9:3542(B)(3). Credit life may not exceed the total sum payable under the contract, including loan finance and credit service charges.","topic":"Term","source":"La. R.S. 9:3542(B)(3) https://www.legis.la.gov/Legis/LawPrint.aspx?d=107634"},{"q":"Which is NOT true of term life?","choices":["Lower initial premiums","Builds guaranteed cash value","Premiums rise on renewal","Can protect insurability with renewable and convertible options"],"answer":1,"explain":"Term has no cash value. Source: NAIC Life Insurance consumer page.","topic":"Term","source":"NAIC Life Insurance consumer page https://content.naic.org/consumer/life-insurance.htm"},{"q":"Which is NOT true of variable life?","choices":["Policyowner bears investment risk","Regulated by state insurance departments and the SEC","Agent needs a life license and FINRA registration","Has a guaranteed minimum cash value"],"answer":3,"explain":"Variable whole life has no guaranteed interest rate or minimum cash value. Source: FINRA Notice to Members 00-44.","topic":"Variable products","source":"FINRA Notice to Members 00-44 https://www.finra.org/rules-guidance/notices/00-44"}],"scenarios":[{"situation":"A 30-year-old buys a 20-year level term policy. In year 12 her health worsens and she wants permanent coverage without a medical exam. Her policy has a conversion option.","q":"What option allows this?","choices":["Renewal","Conversion to a permanent policy without evidence of insurability","Re-entry","Single premium purchase"],"answer":1,"explain":"Source: IRMI Glossary. A convertible policy can be changed to another form without evidence of insurability, usually term to permanent.","topic":"Term","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/convertible"},{"situation":"A couple wants to pay estate taxes at the death of the last surviving spouse and wants a lower premium than two separate policies.","q":"Which policy fits best?","choices":["First-to-die","Second-to-die (survivorship)","Family maintenance","Jumping juvenile"],"answer":1,"explain":"Source: IRMI Glossary. Second-to-die coverage pays when the last insured dies, and its premiums are lower than separate policies.","topic":"Joint life","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/joint-life-and-survivor-or-second-to-die-life-insurance"},{"situation":"A policyowner funds a whole life policy with unusually large premiums in the first few years, exceeding the 7-pay limit. Later she takes a loan from the cash value at age 50.","q":"What is the tax result?","choices":["Loan is tax-free as a policy loan","Loan is taxed LIFO as gain with a 10 percent penalty","Loan is taxed FIFO with no penalty","Policy converts back to normal life insurance"],"answer":1,"explain":"Source: 26 U.S.C. 72(e)(10) and 72(v). A MEC loan is treated as a distribution taxed gain first, with a 10% extra tax before age 59 and a half.","topic":"MEC","source":"26 U.S.C. 72(e)(10) and 72(v) https://www.law.cornell.edu/uscode/text/26/72"}],"pairs":[{"term":"Pure endowment","match":"Pays only if the insured survives to maturity","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/pure-endowment"},{"term":"MEC","match":"Life contract entered into on or after June 21, 1988 that fails the 7-pay test","source":"Cornell LII - 26 U.S.C. 7702A https://www.law.cornell.edu/uscode/text/26/7702A"}]},"ch05_2":{"title":"Chapter 5 (Part 2) - Policy Provisions, Options, Riders and Exclusions","flashcards":[{"front":"Absolute vs collateral assignment","back":"Absolute assignment is a permanent, full transfer of ownership. Collateral assignment is temporary and secures a loan; the lender is paid first from proceeds.","topic":"Assignment","memory":"Absolute = all rights; Collateral = loan security","source":"IRMI glossary (collateral agreement) https://www.irmi.com/term/insurance-definitions/collateral-agreement"},{"front":"Louisiana incontestable clause periods","back":"Individual life (R.S. 22:931): incontestable after two years from issue, except for nonpayment of premiums and military or naval service conditions. Health and accident (R.S. 22:975): after three years, misstatements other than fraudulent ones cannot void the policy or deny a claim.","topic":"Incontestable clause","memory":"Life 2, Health 3","source":"La. R.S. 22:931(A)(2) and 22:975(A)(13) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Suicide exclusion length (Louisiana)","back":"A life policy may exclude self-destruction, sane or insane, within two years of issue. Even then, R.S. 22:931(B)(2) requires at least the reserve on the face amount, less indebtedness.","topic":"Exclusions","memory":"","source":"La. R.S. 22:931(B) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"front":"What does reinstatement require?","back":"Louisiana life: within three years from the date of default, on the insured's application, with evidence of insurability and payment of overdue premiums with interest. Not available if cash surrender value has been exhausted by payment or the extended insurance period has expired.","topic":"Reinstatement","memory":"","source":"La. R.S. 22:931(A)(9) and Alabama DOI glossary https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"front":"Three nonforfeiture options","back":"Cash surrender, reduced paid-up insurance, and extended term insurance (continues the full amount for a limited period). The policy names the automatic option that takes effect if the owner does not elect another within 60 days of the premium due date.","topic":"Nonforfeiture","memory":"CASH, REDUCED, EXTENDED","source":"La. R.S. 22:935 and 22:936 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507792"},{"front":"Reduced paid-up insurance","back":"The cash surrender value buys a fully paid-up permanent life policy for a lesser amount of coverage, based on the insured's age and the cash value.","topic":"Nonforfeiture","memory":"","source":"IRMI glossary (reduced paid-up) https://www.irmi.com/term/insurance-definitions/nonforfeiture-reduced-paid-up-benefit"},{"front":"Insurer's right to defer","back":"Insurer may delay cash surrender or loan payments up to 6 months. It does not apply to death claims.","topic":"Cash value","memory":"","source":"La. R.S. 22:936(A)(2)(b) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507792"}],"questions":[{"q":"An assignment that permanently transfers all ownership rights in a policy is called:","choices":["Collateral assignment","Absolute assignment","Beneficiary designation","Policy reinstatement"],"answer":1,"explain":"Absolute assignment is a full, permanent transfer. Collateral assignment is only temporary security for a loan. Source: IRMI glossary (collateral agreement).","topic":"Assignment","source":"IRMI glossary (collateral agreement) https://www.irmi.com/term/insurance-definitions/collateral-agreement"},{"q":"Which nonforfeiture option provides the highest face amount, though only for a limited time?","choices":["Cash surrender","Reduced paid-up","Extended term","Automatic premium loan"],"answer":2,"explain":"Extended term uses the cash value as a single premium for term coverage, usually for the same face amount. Reduced paid-up gives a smaller face amount for life. Source: La. R.S. 22:935.","topic":"Nonforfeiture","source":"La. R.S. 22:935 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507791"},{"q":"Dividends are paid only on which type of policy?","choices":["Nonparticipating","Participating","Term only","Group credit"],"answer":1,"explain":"Only participating (par) policies pay dividends, and they are not guaranteed. Source: Alabama DOI life insurance glossary.","topic":"Dividends","source":"Alabama DOI life insurance glossary https://aldoi.gov/consumers/LifeGlossary.aspx"},{"q":"A rider that pays double or triple the face amount for death by accident is the:","choices":["Accidental death benefit rider","Waiver of premium rider","Guaranteed insurability option","Cost of living rider"],"answer":0,"explain":"The ADB rider pays a multiple of face for accidental death. Waiver of premium only covers premiums during disability. Source: Alabama DOI life insurance glossary.","topic":"Riders","source":"Alabama DOI life insurance glossary https://aldoi.gov/consumers/LifeGlossary.aspx"},{"q":"How long may an insurer generally delay paying a cash surrender or loan request under the right to defer?","choices":["30 days","90 days","6 months","2 years"],"answer":2,"explain":"The right to defer is up to 6 months. It does not apply to death claims. Source: La. R.S. 22:936(A)(2)(b) and R.S. 22:931(A)(7).","topic":"Cash value","source":"La. R.S. 22:936(A)(2)(b) and R.S. 22:931(A)(7) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507792"},{"q":"Under Louisiana R.S. 22:931, a life policy may exclude death by self-destruction (sane or insane) within what period from the date of issue?","choices":["6 months","1 year","2 years","5 years"],"answer":2,"explain":"Source: La. R.S. 22:931(B)(1)(c). A policy may exclude death by self-destruction, sane or insane, within two years from the date of issue. If the exclusion applies, 22:931(B)(2) still requires payment of at least the reserve on the face amount (less indebtedness), not just a refund of premiums.","topic":"Exclusions","source":"La. R.S. 22:931(B) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"The guaranteed insurability option (GIO) allows the owner to:","choices":["Convert term to whole life without a medical exam","Buy additional coverage at specified times without evidence of insurability","Receive the face amount early if terminally ill","Skip premiums during disability"],"answer":1,"explain":"Source: Alabama DOI life insurance glossary. The guaranteed insurability option lets the policyholder buy additional coverage at stated future times without proving insurability.","topic":"Riders","source":"Alabama DOI life insurance glossary https://aldoi.gov/consumers/LifeGlossary.aspx"},{"q":"Which disability rider benefit does the waiver of premium rider provide?","choices":["Monthly income to the insured","Payment of the policy premiums while totally disabled","A lump sum of the face amount","Reduced premiums for life"],"answer":1,"explain":"It waives premiums only. Income during disability comes from a disability income rider. Source: Alabama DOI life insurance glossary.","topic":"Riders","source":"Alabama DOI life insurance glossary https://aldoi.gov/consumers/LifeGlossary.aspx"},{"q":"Which of the following is NOT a daily living activity used for long-term care benefit triggers?","choices":["Bathing","Toileting","Driving","Transferring"],"answer":2,"explain":"The six standard ADLs are bathing, continence, dressing, eating, toileting and transferring. Driving is not one of them. Source: 26 U.S.C. 7702B(c)(2)(B).","topic":"Living benefits","source":"26 U.S.C. 7702B(c)(2)(B) https://www.law.cornell.edu/uscode/text/26/7702B"},{"q":"Which statement about policy loans is NOT true?","choices":["No credit check is required","Unpaid loans reduce the death benefit","Loan interest on personal policies is tax deductible","They are available on permanent policies"],"answer":2,"explain":"Interest on a personal policy loan is not deductible. The other statements are true. Source: 26 U.S.C. 264(a)(4).","topic":"Policy loans","source":"26 U.S.C. 264(a)(4) https://www.law.cornell.edu/uscode/text/26/264"}],"scenarios":[{"situation":"Maria has paid premiums on her whole life policy for 5 years. She stops paying and does not choose any nonforfeiture option within 60 days.","q":"Under Louisiana law, what happens?","choices":["The policy is surrendered for cash automatically","The paid-up option the policy names as automatic takes effect","The policy is canceled with no value","The insurer must pay the face amount now"],"answer":1,"explain":"Source: La. R.S. 22:936(A)(1)(c). If no other option is elected within 60 days of the missed premium, the paid-up nonforfeiture benefit named in the policy takes effect.","topic":"Nonforfeiture","source":"La. R.S. 22:936(A)(1)(c) https://legis.la.gov/Legis/Law.aspx?d=507792"},{"situation":"Carlos has a $100,000 life policy with a double indemnity rider. He dies in a car crash.","q":"What is paid?","choices":["$100,000","$200,000","$300,000","Nothing, because accidents are excluded"],"answer":1,"explain":"Source: IRMI Glossary. Double indemnity pays two times the face amount when death results from an accident.","topic":"Riders","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/double-indemnity"},{"situation":"Priya names her sister as beneficiary on her policy without making the designation irrevocable. Later she marries and wants to name her husband instead.","q":"What must she do?","choices":["Get her sister's written consent","Name the husband without her sister's consent","Wait until the contestable period ends","Assign the policy absolutely"],"answer":1,"explain":"Source: IRMI Glossary. The owner can change a revocable beneficiary without that beneficiary's consent. An irrevocable beneficiary must consent.","topic":"Beneficiaries","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/revocable-beneficiary"}],"pairs":[{"term":"Extended term","match":"Cash value buys term coverage for the same death benefit amount","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/extended-term-insurance"},{"term":"Paid-up additions","match":"Dividend option buying single-premium coverage added to the face amount","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/paid-up-additions"},{"term":"Waiver of premium","match":"Insurer relinquishes the right to collect premium from the insured","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/waiver-of-premium"},{"term":"Capital sum","match":"Maximum amount payable in one sum for accidental death or dismemberment","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/capital-sum"}]},"ch06":{"title":"Chapter 6 - Group Life Insurance","flashcards":[{"front":"Master policy vs certificate of insurance","back":"The employer (policyholder) owns the master policy. Each insured employee receives a certificate of insurance as evidence of coverage.","topic":"Group basics","memory":"Master = employer; Certificate = employee","source":"La. R.S. 22:656 (former 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"front":"Noncontributory group plan","back":"The employer pays 100% of the premium, and 100% of eligible employees must participate.","topic":"Contributory vs noncontributory","memory":"Non = Nothing paid by employee","source":"La. R.S. 22:941(B)(3) https://legis.la.gov/Legis/LawPrint.aspx?d=507794"},{"front":"Contributory group plan","back":"Employees share the premium cost with the employer. The insurer may, but is not required to, set a minimum participation percentage (La. R.S. 22:941).","topic":"Contributory vs noncontributory","memory":"","source":"La. R.S. 22:941(B)(3) https://legis.la.gov/Legis/LawPrint.aspx?d=507794"},{"front":"Group conversion privilege","back":"On leaving the group, an employee may convert to an individual policy, on a form the insurer customarily issues, without evidence of insurability, if applied for and first premium paid within 31 days.","topic":"Conversion","memory":"31 days, no evidence","source":"Louisiana R.S. 22 group life standard provisions (formerly 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"front":"Conversion premium basis","back":"The converted individual policy is priced at the employee's attained age, not the original age.","topic":"Conversion","memory":"","source":"Louisiana R.S. 22 group life standard provisions (formerly 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"front":"Death during the 31-day conversion window","back":"If the employee dies within the 31 days before converting, the group policy pays the death benefit.","topic":"Conversion","memory":"","source":"Louisiana R.S. 22 group life standard provisions (formerly 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"front":"When the master policy is terminated","back":"Members insured under it for at least 5 years may convert. The individual policy may not exceed the smaller of the insurance that ceased (less any replacement group coverage) or $2,000 (La. R.S. 22 group life conversion provision).","topic":"Conversion","memory":"","source":"Louisiana R.S. 22 group life standard provisions (formerly 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"front":"Adverse selection","back":"An imbalance in an exposure group created when people who perceive a high probability of loss buy coverage more often than others (IRMI).","topic":"Underwriting","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/adverse-selection"},{"front":"Tax treatment of employer-paid group term premiums","back":"The first $50,000 of group term coverage is tax-free to the employee. Cost for coverage above $50,000 may be taxable income.","topic":"Taxation","memory":"Fifty thousand free","source":"IRS Publication 15-B (2026) https://www.irs.gov/publications/p15b"},{"front":"Credit life insurance","back":"Term life insurance that pays off the balance of a loan if the borrower dies (IRMI).","topic":"Special group types","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/credit-life-insurance"},{"front":"Franchise insurance","back":"Insurance for groups too small to qualify for true group coverage (IRMI). Often sold as individual policies to members of such groups.","topic":"Special group types","memory":"","source":"IRMI Glossary https://irmi.com/term/insurance-definitions/franchise-insurance"},{"front":"Blanket insurance","back":"A policy covering special enumerated groups, such as passengers of a common carrier. No individual application is needed from covered persons (La. R.S. 22:1000).","topic":"Special group types","memory":"","source":"La. R.S. 22:1000(A)(3) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507837"}],"questions":[{"q":"In a group life plan, who owns the master policy?","choices":["Each employee","The beneficiary","The employer or policyholder","The state insurance department"],"answer":2,"explain":"The group policyholder, usually the employer, owns the master policy. Employees receive certificates. Source: La. R.S. 22:656 (former 22:942), standard group life provisions.","topic":"Group basics","source":"La. R.S. 22:656 (former 22:942), standard group life provisions https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"q":"Under Louisiana law, when no part of a group life premium is paid by employees, whom must the policy insure?","choices":["Only employees who apply individually","All eligible employees (except those the insurer finds individually uninsurable)","At least 75% of eligible employees","Only employees under age 65"],"answer":1,"explain":"Source: La. R.S. 22:941. A group policy with no employee contributions must insure all eligible employees, or all except those whose individual insurability is unsatisfactory to the insurer. A participation percentage is optional, not fixed at 75%.","topic":"Contributory vs noncontributory","source":"La. R.S. 22:941 https://www.legis.la.gov/Legis/Law.aspx?d=507794"},{"q":"Within how many days after termination of employment must an employee apply to convert group coverage?","choices":["10","31","60","90"],"answer":1,"explain":"The conversion privilege lasts 31 days and needs no proof of insurability. Source: La. R.S. 22:656 (former 22:942).","topic":"Conversion","source":"La. R.S. 22:656 (former 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"q":"How much employer-paid group term coverage is generally tax-free to the employee?","choices":["$10,000","$25,000","$50,000","$100,000"],"answer":2,"explain":"The first $50,000 is tax-free. Coverage above that may create taxable income. Source: 26 U.S.C. 79.","topic":"Taxation","source":"26 U.S.C. 79 https://www.law.cornell.edu/uscode/text/26/79"},{"q":"Which statement about group conversion is NOT true?","choices":["No proof of insurability is required","Premium is based on attained age","The employee may keep the original group rate","It usually converts to individual whole life"],"answer":2,"explain":"The converted policy is priced at attained age in the individual market, not at the group rate. Source: La. R.S. 22:656 (former 22:942).","topic":"Conversion","source":"La. R.S. 22:656 (former 22:942) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"}],"scenarios":[{"situation":"Dana leaves her job and her group life coverage ends on the last day of the month. She has some health problems and wants to keep life insurance.","q":"What is her best option?","choices":["She has no option because she is uninsurable","Apply for conversion to an individual policy within 31 days without proof of insurability","Wait 60 days then reapply to the group","Ask the employer to continue the master policy for her alone"],"answer":1,"explain":"Source: La. R.S. 22:942(10). She can convert to an individual policy without evidence of insurability if she applies and pays within 31 days. The premium is based on her attained age.","topic":"Conversion","source":"La. R.S. 22:942(10) https://legis.la.gov/Legis/Law.aspx?d=507795"},{"situation":"An employer pays the entire premium for group term life. Only 80% of eligible employees are covered.","q":"Does the plan meet standard participation rules for this type?","choices":["Yes, 75% is enough","Yes, the employer can pick any percentage","No, a noncontributory plan must cover all eligible employees","No, it must be contributory"],"answer":2,"explain":"Source: La. R.S. 22:941(B)(3). When employees pay none of the premium, the policy must insure all eligible employees, except those the insurer finds uninsurable.","topic":"Contributory vs noncontributory","source":"La. R.S. 22:941(B)(3) https://legis.la.gov/Legis/Law.aspx?d=507794"},{"situation":"Jordan takes out a car loan, and the lender offers a policy that will pay off the loan balance if Jordan dies.","q":"What is this coverage and who is the beneficiary?","choices":["Franchise life, with Jordan's spouse as beneficiary","Credit life, with the lender as beneficiary","Blanket life, with Jordan's estate as beneficiary","Whole life, with the employer as beneficiary"],"answer":1,"explain":"Source: IRMI Glossary. Credit life is term insurance that pays off the loan balance if the borrower dies, so the lender is paid.","topic":"Special group types","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/credit-life-insurance"}],"pairs":[{"term":"Master policy","match":"Group policy issued to the plan sponsor","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/group-disability-insurance"},{"term":"Certificate of insurance","match":"Document issued to each qualifying employee under the master policy","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/group-disability-insurance"},{"term":"Franchise insurance","match":"Coverage for groups too small to qualify for true group insurance; also called wholesale","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/franchise-insurance"}]},"ch07":{"title":"Chapter 7 - Premiums, Proceeds, Settlement Options and Beneficiaries","flashcards":[{"front":"Three factors that set a life insurance premium","back":"Mortality, interest and expenses. Higher mortality or expenses raise the premium; higher assumed interest lowers it.","topic":"Premium factors","memory":"MIE: Mortality, Interest, Expenses","source":"NY DFS: The Cost of Life Insurance https://www.dfs.ny.gov/consumers/life_insurance/the_cost_of_life_insurance"},{"front":"Earned vs unearned premium","back":"Earned premium is the part for coverage already provided. Unearned premium is the part for coverage not yet provided.","topic":"Reserves","memory":"","source":"IRMI Glossary: Earned premium / Unearned premium https://irmi.com/term/insurance-definitions/earned-premium"},{"front":"Surrender cost index","back":"Average net cost per $1,000 if the policy is surrendered for cash at a set point, such as 10 or 20 years. Suits cash value focused buyers.","topic":"Cost comparison","memory":"","source":"760 IAC 1-24-9 (Cornell LII) https://www.law.cornell.edu/regulations/indiana/760-IAC-1-24-9"},{"front":"Net payment cost index","back":"Average annual premium outlay assuming the policy is not surrendered. Excludes cash value, so it suits death benefit focused buyers.","topic":"Cost comparison","memory":"","source":"760 IAC 1-24-9 (Cornell LII) https://www.law.cornell.edu/regulations/indiana/760-IAC-1-24-9"},{"front":"Accelerated death benefit","back":"Living benefit paying part of the death benefit early to a terminally ill (death expected within 24 months) or chronically ill insured. Generally treated as death proceeds, so tax-free under IRC 101(g).","topic":"Living benefits","memory":"","source":"26 U.S.C. 101(g) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/101"},{"front":"Five settlement options","back":"Lump sum (default), interest only, fixed amount, fixed period, and life income.","topic":"Settlement options","memory":"","source":"IRMI Glossary: Settlement options https://irmi.com/term/insurance-definitions/settlement-options"},{"front":"Fixed amount vs fixed period option","back":"Fixed amount focuses on the dollar income; the payout lasts until funds run out. Fixed period focuses on time, ignoring life expectancy.","topic":"Settlement options","memory":"Amount = dollars; Period = time","source":"IRMI Glossary: Settlement options https://irmi.com/term/insurance-definitions/settlement-options"},{"front":"Life income sub-options","back":"Single (pure) life pays most, no refund. Refund guarantees at least principal. Period certain guarantees years. Joint and survivor covers two lives.","topic":"Settlement options","memory":"","source":"Alabama DOI: Annuity Options https://aldoi.gov/consumers/AnnuityOptions.aspx"},{"front":"Revocable vs irrevocable beneficiary","back":"Owner may change a revocable beneficiary anytime. Changing an irrevocable beneficiary needs that beneficiary's consent, and that beneficiary has a vested interest.","topic":"Beneficiaries","memory":"","source":"IRMI Glossary: Irrevocable beneficiary https://irmi.com/term/insurance-definitions/irrevocable-beneficiary"},{"front":"Per capita vs per stirpes","back":"Per capita splits equally among surviving class members. Per stirpes lets a deceased member's share pass to that member's descendants.","topic":"Beneficiaries","memory":"Per stirpes = by the branch","source":"Cornell LII Wex: Per stirpes / Per capita https://www.law.cornell.edu/wex/per_stirpes"},{"front":"Income tax on life insurance proceeds","back":"Premiums are not deductible. Lump-sum death benefit is generally income-tax-free. Installment interest is taxable. Policy loans are generally not taxable, except for a MEC.","topic":"Taxation","memory":"","source":"26 U.S.C. 101 and 72(e) https://www.law.cornell.edu/uscode/text/26/101"}],"questions":[{"q":"Gross premium equals:","choices":["Net premium minus expenses","Net premium plus expenses","Mortality minus interest only","Cash value plus dividends"],"answer":1,"explain":"Gross premium adds the expense loading to the net premium. Source: IRMI Glossary.","topic":"Premium basics","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/gross-premium"},{"q":"Which settlement option pays benefits for as long as the beneficiary lives?","choices":["Fixed period","Interest only","Fixed amount","Life income"],"answer":3,"explain":"Life income is based on life expectancy and cannot be outlived. Fixed period ends after the chosen years. Source: IRMI Glossary.","topic":"Settlement options","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/life-income-option"},{"q":"Under per stirpes with three children, one deceased child who left two children, how much does each surviving child receive (exact)?","choices":["One-half","One-quarter","One-third","One-sixth"],"answer":2,"explain":"Each of the three branches takes one-third. The deceased child's two children share one-third, so each gets one-sixth. Source: Cornell LII Wex: Per stirpes.","topic":"Beneficiaries","source":"Cornell LII Wex: Per stirpes https://www.law.cornell.edu/wex/per_stirpes"},{"q":"Which index is best for a buyer who plans to surrender the policy in 10 to 20 years?","choices":["Net payment cost index","Surrender cost index","Loss ratio","Persistency ratio"],"answer":1,"explain":"The surrender cost index assumes the policy is surrendered. The net payment cost index assumes it is not. Source: 760 IAC 1-24-9 Life insurance buyer's guide (Cornell LII).","topic":"Cost comparison","source":"760 IAC 1-24-9 Life insurance buyer's guide (Cornell LII) https://www.law.cornell.edu/regulations/indiana/760-IAC-1-24-9"},{"q":"Which statement about premium factors is NOT correct?","choices":["Higher mortality raises premium","Higher expenses raise premium","Higher interest earnings raise premium","Interest earned reduces the premium needed"],"answer":2,"explain":"Higher interest earnings lower the premium, not raise it. Source: NY DFS: The Cost of Life Insurance.","topic":"Premium factors","source":"NY DFS: The Cost of Life Insurance https://www.dfs.ny.gov/consumers/life_insurance/the_cost_of_life_insurance"},{"q":"Which is NOT true of an irrevocable beneficiary?","choices":["Has a vested interest","May receive a copy of the policy","Must consent to a policy loan","Can be changed by the owner at any time without consent"],"answer":3,"explain":"Changes to an irrevocable beneficiary require that beneficiary's consent. Source: IRMI Glossary: Irrevocable beneficiary.","topic":"Beneficiaries","source":"IRMI Glossary: Irrevocable beneficiary https://irmi.com/term/insurance-definitions/irrevocable-beneficiary"},{"q":"Which is NOT a feature of a viatical settlement?","choices":["The policy owner is called the viator","The viator receives less than the expected death benefit","The buyer takes the death benefit later","The viator is paid the full death benefit"],"answer":3,"explain":"Source: La. R.S. 22:1791. A viatical settlement contract pays the viator compensation of less than the expected death benefit in exchange for the death benefit or an ownership interest in the policy. The viator is the policy owner.","topic":"Settlements","source":"La. R.S. 22:1791 https://www.legis.la.gov/Legis/LawPrint.aspx?d=508788"},{"q":"Which statement about taxation of life insurance is NOT correct?","choices":["Premiums for personal policies are not deductible","Lump-sum proceeds are generally income-tax-free","Interest paid on installments is tax-free","A 1035 exchange is generally not taxable"],"answer":2,"explain":"Interest earned on installments is taxable; the principal portion is not. Source: 26 U.S.C. 101 (Cornell LII).","topic":"Taxation","source":"26 U.S.C. 101 (Cornell LII) https://www.law.cornell.edu/uscode/text/26/101"}],"scenarios":[{"situation":"A physician certifies that Tom has an illness expected to cause his death within 24 months. His life policy has an accelerated benefit provision, and he takes part of the death benefit now.","q":"How is the accelerated payment generally taxed?","choices":["Generally tax-free, treated like a death benefit","Fully taxable as ordinary income","Taxable unless he waits until death","Taxed with a 10% penalty"],"answer":0,"explain":"Source: 26 U.S.C. 101(g). Amounts paid to a terminally ill insured (death expected within 24 months) are treated as paid by reason of death, which is generally tax-free.","topic":"Living benefits","source":"26 U.S.C. 101(g) https://www.law.cornell.edu/uscode/text/26/101"},{"situation":"The insured's policy names three adult children as beneficiaries. One child dies before the insured and leaves two children. The policy says per stirpes.","q":"How is the death benefit divided?","choices":["Each of the two surviving children gets one-half","Each of the two surviving children gets one-third, and the grandchildren share one-third","The grandchildren get nothing","Everything goes to the estate"],"answer":1,"explain":"Source: IRMI Glossary. Per stirpes means by branches: a beneficiary who dies first passes their full share to their heirs.","topic":"Beneficiaries","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/per-stirpes"},{"situation":"A beneficiary wants predictable payments of $2,000 a month until the proceeds are used up, not a set number of years and not for life.","q":"Which option fits?","choices":["Fixed period","Interest only","Fixed amount","Joint and survivor"],"answer":2,"explain":"Source: IRMI Glossary. Fixed amount pays set installments until principal and interest run out. Fixed period pays for a set number of years.","topic":"Settlement options","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/fixed-amount-option"}],"pairs":[{"term":"Gross premium","match":"Pure premium adjusted upward to include insurer expenses","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/gross-premium"},{"term":"Fixed period option","match":"Equal payments over a chosen number of years","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/fixed-period-option"},{"term":"Contingent beneficiary","match":"Receives benefit if the primary dies first","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/contingent-beneficiary"},{"term":"Life settlement","match":"Sale or transfer of a life policy to a third party","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"}]},"ch08":{"title":"Chapter 8 - Uses of Life Insurance and Annuity Basics","flashcards":[{"front":"Child's Social Security survivor benefit age","back":"A child is generally eligible while under age 18, or age 18 or older if a full-time student in grade 12 or below, or disabled before age 22 (20 CFR 404.350, 404.367).","topic":"Needs analysis","memory":"","source":"20 CFR 404.350 and 404.367 https://www.law.cornell.edu/cfr/text/20/404.350"},{"front":"Key person insurance","back":"Covers an employee whose death would hurt the business. The business is applicant, owner, premium payor and beneficiary. Premiums are generally not deductible.","topic":"Business uses","memory":"","source":"IRMI Glossary; 26 U.S.C. 264 (Cornell LII) https://www.irmi.com/term/insurance-definitions/key-person-life-insurance"},{"front":"Purpose of a buy-sell agreement","back":"Funds the purchase of a deceased owner's share of the business, so the survivors can buy it and the family receives cash.","topic":"Business uses","memory":"","source":"IRMI buy/sell agreement https://www.irmi.com/term/insurance-definitions/buy-sell-agreement"},{"front":"Number of policies in cross-purchase","back":"n x (n - 1). Three partners need 6 policies; four partners need 12. An entity plan needs one per owner.","topic":"Buy-sell","memory":"Each buys one on every other partner","source":"IRMI glossary: cross purchase https://www.irmi.com/term/insurance-definitions/cross-purchase"},{"front":"Corporate-owned life insurance (COLI) tax basics","back":"Death proceeds are generally income-tax-free to the corporation, subject to notice and consent rules. The $50,000 group-term rule does not apply to business-owned life insurance.","topic":"COLI","memory":"","source":"26 U.S.C. 101(j) and 79(b)(2)(A) https://www.law.cornell.edu/uscode/text/26/101"},{"front":"Split-dollar","back":"A method of sharing a policy's cost and benefits between employer and employee. It is an arrangement, not a type of policy.","topic":"Employer plans","memory":"","source":"26 CFR 1.61-22 https://www.law.cornell.edu/cfr/text/26/1.61-22"},{"front":"Annuity exclusion ratio","back":"The portion of each annuity payment that is a tax-free return of the investment, with the rest taxable.","topic":"Annuities","memory":"","source":"26 U.S.C. 72(b) https://www.law.cornell.edu/uscode/text/26/72"},{"front":"1035 exchange","back":"Moves an annuity or life policy to another contract without immediate tax on the gain; tax is deferred, not eliminated.","topic":"Annuities","memory":"","source":"26 U.S.C. 1035(a) https://www.law.cornell.edu/uscode/text/26/1035"}],"questions":[{"q":"Key person life insurance is purchased on:","choices":["The business owner's spouse","An employee valuable to the business","A competitor","A customer"],"answer":1,"explain":"The business insures the key employee and receives the benefit if that person dies. Source: IRMI Glossary: key person life insurance.","topic":"Business uses","source":"IRMI Glossary: key person life insurance https://www.irmi.com/term/insurance-definitions/key-person-life-insurance"},{"q":"A buy-sell agreement funded with life insurance is intended to:","choices":["Provide the funds to buy a deceased owner's interest","Reduce the business's income taxes","Pay the owner a retirement income","Insure a key employee"],"answer":0,"explain":"The insurance provides the funds for the survivors or the business to buy the deceased owner's share from the estate. Source: IRMI buy/sell agreement.","topic":"Buy-sell","source":"IRMI buy/sell agreement https://www.irmi.com/term/insurance-definitions/buy-sell-agreement"},{"q":"Who is the annuitant in an annuity?","choices":["The company issuing the contract","The person whose life determines payments","The person who must pay tax on death","The agent"],"answer":1,"explain":"The annuitant's life sets the length of payments. The owner and annuitant can be different people. Source: IRMI annuitant.","topic":"Annuities","source":"IRMI annuitant https://www.irmi.com/term/insurance-definitions/annuitant"},{"q":"Federal estate tax on the estate of a decedent is generally due:","choices":["Within 6 months of death","9 months after death","Within 30 days of death","At the time of filing the next income tax return"],"answer":1,"explain":"The estate tax return and payment are generally due 9 months after death. State rules can differ. Source: 26 U.S.C. 6075(a).","topic":"Estate planning","source":"26 U.S.C. 6075(a) https://www.law.cornell.edu/uscode/text/26/6075"},{"q":"The first $50,000 tax-free rule applies to which kind of coverage?","choices":["Corporate-owned life insurance (COLI)","Group term life insurance","Key person life","Split-dollar"],"answer":1,"explain":"The $50,000 figure comes from the group term rule. It does not apply to business-owned life insurance such as COLI. Source: 26 U.S.C. 79(a).","topic":"Taxation","source":"26 U.S.C. 79(a) https://www.law.cornell.edu/uscode/text/26/79"},{"q":"Which is NOT typical of key person life insurance?","choices":["The business is the beneficiary","The business owns the policy","Premiums are generally not deductible","The insured employee's family is the sole beneficiary"],"answer":3,"explain":"Source: IRMI Glossary (key person life insurance) and 26 U.S.C. 264(a)(1). The company typically owns the policy and is the beneficiary (IRMI), and premiums are not deductible when the taxpayer benefits from the policy (264(a)(1)). The employee's family is not the sole beneficiary in the typical arrangement.","topic":"Business uses","source":"IRMI Glossary: key person life insurance; 26 U.S.C. 264 (Cornell LII) https://www.irmi.com/term/insurance-definitions/key-person-life-insurance"},{"q":"Which is NOT true of split-dollar?","choices":["It is an arrangement for sharing cost and benefits","It is a type of policy","Employer and employee may share premiums","It is a method of financing"],"answer":1,"explain":"Split-dollar is a method of financing, not a policy type. Source: 26 CFR 1.61-22(b)(1).","topic":"Employer plans","source":"26 CFR 1.61-22(b)(1) https://www.law.cornell.edu/cfr/text/26/1.61-22"}],"scenarios":[{"situation":"Three partners want to fund a buy-sell agreement where each partner buys a policy on each of the others. Partner A dies.","q":"How many policies were purchased, and who receives the proceeds on Partner A's life?","choices":["3 policies; the business","6 policies; the surviving partners who own those policies","6 policies; Partner A's family","9 policies; the partnership"],"answer":1,"explain":"Source: Connelly v. United States (2024). In a cross-purchase plan each owner buys a policy on each other owner (3 x 2 = 6), and proceeds go to the surviving owners.","topic":"Buy-sell","source":"Connelly v. United States (2024) https://www.law.cornell.edu/supremecourt/text/23-146"},{"situation":"A corporation buys a policy on its top salesperson and names itself as owner and beneficiary. The salesperson's departure or death would seriously reduce sales.","q":"What is this arrangement?","choices":["Executive bonus plan","Key person insurance","Deferred compensation","Cross-purchase agreement"],"answer":1,"explain":"Source: IRMI Glossary. Key person (key employee) insurance pays the business for losses when a key person dies or is disabled.","topic":"Business uses","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/key-employee-insurance"},{"situation":"Two co-owners of a bakery sign a contract: if one dies, that owner's estate sells the share back to the business at a set price. The business buys life insurance on each owner to pay for it.","q":"What is this arrangement?","choices":["A buy-sell agreement funded by life insurance","A joint and survivor annuity","Key person insurance","A group term plan"],"answer":0,"explain":"Source: IRMI Glossary. A buy-sell agreement has a deceased owner's estate sell the interest at a set price, usually funded by life insurance.","topic":"Buy-sell","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/buy-sell-agreement"}],"pairs":[{"term":"Key person insurance","match":"Company owns policy and is beneficiary on a key employee","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/key-person-life-insurance"},{"term":"Cross-purchase","match":"Each owner buys policies on the other owners","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/cross-purchase"},{"term":"Entity plan","match":"Business itself buys a deceased owner's share","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/entity-buy-sell-agreement"},{"term":"Annuitant","match":"Person during whose life an annuity is payable","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"}]},"ch09":{"title":"Chapter 9 - Annuities","flashcards":[{"front":"Fixed vs variable annuity risk","back":"Fixed annuity: general account, the insurer bears investment risk. Variable annuity: separate account, the owner bears investment risk.","topic":"Fixed vs variable","memory":"","source":"NAIC annuities topic page https://content.naic.org/insurance-topics/annuities"},{"front":"Variable annuity regulation","back":"Regulated by state insurance commissions and the SEC, with FINRA regulating the sellers. Read the prospectus. The seller needs a state insurance license and securities registration under FINRA rules.","topic":"Regulation","memory":"","source":"SEC Investor Tips: Variable Annuities; FINRA Insurance Agents page https://www.sec.gov/investor/pubs/varannty.htm"},{"front":"Parties to an annuity","back":"Insurer, owner (holds contract rights such as withdrawals and changing the beneficiary), annuitant (the person during whose life the annuity is payable), and beneficiary.","topic":"Parties","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"front":"Death benefit during accumulation","back":"Usually the greater of the account value or a guaranteed minimum (for example, purchase payments less withdrawals), not a face amount like life insurance.","topic":"Accumulation","memory":"","source":"SEC Investor Tips: Variable Annuities https://www.sec.gov/investor/pubs/varannty.htm"},{"front":"Qualified vs non-qualified annuity","back":"Qualified annuities fund an IRA, 403(b) or other tax-benefited retirement arrangement. Non-qualified annuities are bought with after-tax dollars, and earnings grow tax-deferred until withdrawn.","topic":"Tax class","memory":"","source":"IRI Annuities Glossary https://www.irionline.org/programs/education/annuities-glossary/"},{"front":"Single premium immediate annuity (SPIA)","back":"Bought with one lump sum, with income payments beginning within one year of purchase.","topic":"Timing","memory":"","source":"NAIC annuities topic page https://content.naic.org/insurance-topics/annuities"},{"front":"Accumulation units vs annuity units","back":"Accumulation units are bought during the savings phase. At payout the number of annuity units is fixed, but unit value varies, so payment = units x unit value.","topic":"Variable annuity","memory":"","source":"IRI Annuities Glossary https://www.irionline.org/programs/education/annuities-glossary/"},{"front":"Equity-indexed annuity","back":"A fixed annuity that earns interest or provides benefits linked to an external reference or equity index, subject to a minimum guarantee.","topic":"Types","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"front":"Straight life payout option","back":"Pays income for the annuitant's lifetime and stops at the annuitant's death, with no payments continuing to a beneficiary.","topic":"Payout options","memory":"Straight life stops at death","source":"ACLI Glossary https://www.acli.com/industry-facts/glossary"},{"front":"Period certain vs refund","back":"Period certain continues payments to a beneficiary through a minimum set number of years if the annuitant dies early (guarantees time). Refund returns the purchase price less payments already made (guarantees money).","topic":"Payout options","memory":"Period = time; Refund = money","source":"IRI Annuities Glossary https://www.irionline.org/programs/education/annuities-glossary/"},{"front":"Joint and survivor annuity","back":"A life annuity over two annuitants, usually spouses, with payments continuing while either is alive.","topic":"Payout options","memory":"","source":"ACLI Glossary https://www.acli.com/industry-facts/glossary"},{"front":"Early withdrawal costs","back":"Withdrawals before age 59 1/2 are generally subject to a 10% additional federal tax on the portion includible in income, on top of regular income tax.","topic":"Charges and tax","memory":"","source":"26 U.S.C. 72(q) https://www.law.cornell.edu/uscode/text/26/72"},{"front":"Annuity withdrawal tax order (LIFO)","back":"Earnings are generally withdrawn first and taxed as ordinary income. Contracts issued before August 14, 1982 use FIFO, with basis out first.","topic":"Taxation","memory":"","source":"26 U.S.C. 72(e) https://www.law.cornell.edu/uscode/text/26/72"},{"front":"403(b) / TSA","back":"A tax-sheltered annuity plan for employees of public schools and 501(c)(3) nonprofit organizations.","topic":"Qualified plans","memory":"","source":"26 U.S.C. 403(b) https://www.law.cornell.edu/uscode/text/26/403"}],"questions":[{"q":"In a variable annuity, who bears the investment risk?","choices":["The insurer","The owner","The state","The agent"],"answer":1,"explain":"Variable annuity values depend on separate account performance, so the owner bears the risk. In a fixed annuity the insurer does. Source: SEC, Variable Annuities: What You Should Know.","topic":"Fixed vs variable","source":"SEC, Variable Annuities: What You Should Know https://www.sec.gov/investor/pubs/varannty.htm"},{"q":"At the latest, a single premium immediate annuity must start paying within:","choices":["30 days","60 days","12 months","5 years"],"answer":2,"explain":"Source: 26 U.S.C. 72(u)(4). An immediate annuity is purchased with a single premium and its annuity starting date is no later than 1 year from purchase.","topic":"Timing","source":"26 U.S.C. 72(u)(4) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"A section 1035 exchange is NOT permitted from:","choices":["Annuity to annuity","Life insurance to annuity","Endowment to annuity","Annuity to life insurance"],"answer":3,"explain":"A tax-free exchange can go from life insurance or an annuity into an annuity, but not from an annuity into life insurance. Source: 26 U.S.C. 1035(a).","topic":"1035 exchange","source":"26 U.S.C. 1035(a) https://www.law.cornell.edu/uscode/text/26/1035"},{"q":"Which tax rate or penalty applies to early withdrawals from an annuity before age 59 1/2 (earnings, absent an exception)?","choices":["5%","10%","25%","50%"],"answer":1,"explain":"A 10% federal penalty applies, in addition to ordinary income tax and any surrender charge. Source: 26 U.S.C. 72(q).","topic":"Charges and tax","source":"26 U.S.C. 72(q) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"Which statement about 403(b) plans is NOT correct?","choices":["They are for public school employees","They are for 501(c)(3) nonprofit employees","They are for all private for-profit employees","They are also known as TSAs"],"answer":2,"explain":"403(b) plans cover public school employees and 501(c)(3) nonprofit employees, not all private employees. Source: 26 U.S.C. 403(b).","topic":"Qualified plans","source":"26 U.S.C. 403(b) https://www.law.cornell.edu/uscode/text/26/403"},{"q":"Which is NOT true of a variable annuity?","choices":["The owner chooses among subaccounts","A prospectus is required","The insurer guarantees the investment return","A securities license is required to sell it"],"answer":2,"explain":"The investment return is not guaranteed; the owner bears the risk. Source: SEC, Variable Annuities: What You Should Know.","topic":"Fixed vs variable","source":"SEC, Variable Annuities: What You Should Know https://www.sec.gov/investor/pubs/varannty.htm"},{"q":"When a corporation owns an annuity and the annuitant is not a natural person, what is generally the result?","choices":["The income is tax-deferred","Interest is taxed yearly as ordinary income","The 10% penalty is waived","The annuity is tax-free"],"answer":1,"explain":"Non-natural owners lose tax deferral, except in listed exceptions such as a trust or agent, estate, qualified plan or an immediate annuity. Source: 26 U.S.C. 72(u)(1).","topic":"Corporate-owned","source":"26 U.S.C. 72(u)(1) https://www.law.cornell.edu/uscode/text/26/72"}],"scenarios":[{"situation":"Lena, age 66, wants a guaranteed income she cannot outlive and does not want to take market risk. She is not concerned with leaving money to heirs.","q":"Which choice best matches her needs?","choices":["A variable annuity with growth subaccounts only","A fixed annuity paying income for life","A term policy","An annuity with a period certain only of 5 years"],"answer":1,"explain":"Source: FINRA. With a fixed annuity the insurer guarantees the interest rate and the payout, and payouts can last a lifetime.","topic":"Suitability","source":"FINRA: Annuities https://www.finra.org/investors/investing/investment-products/annuities"},{"situation":"Ben owns a variable annuity during the accumulation phase and wants to move the money to another annuity without paying tax now. He asks about a replacement.","q":"What applies?","choices":["He must surrender it and pay tax","A 1035 exchange can defer the tax, and the basis carries over","The exchange permanently eliminates the tax","He may only exchange into a life policy"],"answer":1,"explain":"Source: 26 U.S.C. 1035. No gain is recognized on an annuity-for-annuity exchange, and basis carries over under section 1031(d).","topic":"1035 exchange","source":"26 U.S.C. 1035 https://www.law.cornell.edu/uscode/text/26/1035"},{"situation":"A retired couple buys a joint and survivor annuity. After the first spouse dies, the contract pays the survivor.","q":"Which statement is correct?","choices":["Payments stop at the first death","Payments continue as long as either annuitant lives","The survivor receives a refund of the principal only","The payments become taxable at 10%"],"answer":1,"explain":"Source: IRMI Glossary. A joint and survivorship annuity keeps paying as long as either annuitant is alive.","topic":"Payout options","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/joint-and-survivorship-annuity"}],"pairs":[{"term":"Period certain","match":"Payments continue for a set period even if the payee dies","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/life-income-with-period-certain-option"},{"term":"Variable annuity","match":"Payments rise or fall with investment performance of the underlying portfolio","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/variable-annuity"},{"term":"403(b) plan","match":"Plan only public educational institutions or 501(c)(3) organizations may establish","source":"IRS - IRC 403(b) tax-sheltered annuity plans https://www.irs.gov/retirement-plans/irc-403b-tax-sheltered-annuity-plans"}]},"ch10":{"title":"Chapter 10 - Social Security","flashcards":[{"front":"How many quarters make a person fully insured?","back":"40 quarters (about 10 years). They need not be consecutive, and you can earn at most 4 per year.","topic":"Insured status","memory":"FULLY = full retirement and disability.","source":"42 USC 414(a)(2) https://www.law.cornell.edu/uscode/text/42/414"},{"front":"What is currently insured status?","back":"6 of the last 13 quarters (about 3 years). It qualifies the family for survivor benefits only.","topic":"Insured status","memory":"CURRENTLY = only the family gets death benefits.","source":"42 USC 414(b) https://www.law.cornell.edu/uscode/text/42/414"},{"front":"FRA for anyone born in 1960 or later?","back":"Age 67. Before 1938 it was 65, and it rises gradually for births 1938 to 1959.","topic":"Retirement","memory":"","source":"42 USC 416(l)(1)(E) https://www.law.cornell.edu/uscode/text/42/416"},{"front":"Benefit if claimed at 62 with FRA 67?","back":"About 70% of PIA, permanently reduced. The 80% figure applies only to FRA 65.","topic":"Retirement","memory":"","source":"42 USC 402(q) https://www.law.cornell.edu/uscode/text/42/402"},{"front":"2026 earnings limit for someone under FRA all year?","back":"$24,480 a year. $1 is withheld for every $2 earned above the limit.","topic":"Earnings test","memory":"Under FRA: $1 for $2.","source":"Federal Register (SSA) Cost-of-Living Increase and Other Determinations for 2026 https://www.govinfo.gov/content/pkg/FR-2025-11-03/html/2025-19763.htm"},{"front":"2026 earnings test in the year you reach FRA?","back":"$65,160 limit, $1 withheld per $3 over it, counting only months before the FRA month. No limit from the FRA month on.","topic":"Earnings test","memory":"FRA year: $1 for $3.","source":"Federal Register (SSA) Cost-of-Living Increase and Other Determinations for 2026 https://www.govinfo.gov/content/pkg/FR-2025-11-03/html/2025-19763.htm"},{"front":"Lump-sum death benefit amount?","back":"$255, unchanged for decades. Paid to an eligible spouse or, in some cases, children.","topic":"Survivor benefits","memory":"","source":"42 USC 402(i) https://www.law.cornell.edu/uscode/text/42/402"},{"front":"When does the blackout period start and end?","back":"It starts when the youngest child turns 16 (or at once if no children) and ends when the spouse reaches 60. Child benefits run to 18.","topic":"Blackout","memory":"Blackout starts at 16, not 18.","source":"20 CFR 404.341 https://www.law.cornell.edu/cfr/text/20/404.341"},{"front":"Survivor benefit percentages for parents?","back":"One dependent parent gets 82.5% of PIA. If two parents qualify, each gets 75%. A child gets 75%.","topic":"Survivor benefits","memory":"One parent 82.5, two parents 75 each.","source":"42 USC 402(h)(2) https://www.law.cornell.edu/uscode/text/42/402"},{"front":"SSDI work requirement and waiting period?","back":"Fully insured, with 20 of the last 40 quarters (age 31+). 5-month waiting period; benefits begin in the 6th month.","topic":"Disability","memory":"","source":"42 USC 423(c) https://www.law.cornell.edu/uscode/text/42/423"},{"front":"What happens to SSDI at FRA?","back":"Disability benefits convert to retirement benefits at FRA (66 or 67 for most people now), not at 65.","topic":"Disability","memory":"","source":"42 U.S.C. 423 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/423"},{"front":"Which Medicare parts are optional, and who runs Medicare?","back":"Part B is a voluntary program, and Parts C and D are optional. Part A is automatic and premium-free for most people who paid Medicare payroll taxes about 10 years. CMS administers Medicare, and the Part B premium can change each year.","topic":"Medicare","memory":"A = hospital, B = medical.","source":"Medicare.gov costs; 42 U.S.C. 1395j and 1395c https://www.medicare.gov/basics/costs/medicare-costs"}],"questions":[{"q":"Which term means the full Social Security benefit payable at full retirement age?","choices":["AIME","PIA","COLA","SGA"],"answer":1,"explain":"PIA is the primary insurance amount, the benefit at FRA. AIME is only the earnings average used to compute it. Source: 42 U.S.C. 415.","topic":"Benefit math","source":"42 U.S.C. 415 https://www.law.cornell.edu/uscode/text/42/415"},{"q":"A person who is currently insured but not fully insured can receive which benefits?","choices":["Retirement only","Retirement and disability","Survivor benefits only","No benefits"],"answer":2,"explain":"Currently insured status (6 of the last 13 quarters) supports survivor benefits only. Retirement and disability need fully insured status. Source: 42 U.S.C. 414(b) and 402(a).","topic":"Insured status","source":"42 U.S.C. 414(b) and 402(a) https://www.law.cornell.edu/uscode/text/42/414"},{"q":"What does SGA stand for in the SSA definition of disability?","choices":["Supplemental guaranteed annuity","Substantial gainful activity","Standard group allowance","Survivor gross allotment"],"answer":1,"explain":"A person is totally disabled if unable to perform substantial gainful activity in any job in the national economy. Source: 42 U.S.C. 423(d)(1)(A).","topic":"Disability","source":"42 U.S.C. 423(d)(1)(A) https://www.law.cornell.edu/uscode/text/42/423"},{"q":"How many quarters are needed to be fully insured?","choices":["20","30","40","52"],"answer":2,"explain":"40 quarters, about 10 years. Max 4 per year, and they need not be consecutive. Source: 42 U.S.C. 414(a).","topic":"Insured status","source":"42 U.S.C. 414(a) https://www.law.cornell.edu/uscode/text/42/414"},{"q":"What is the 2026 Social Security taxable maximum?","choices":["$160,200","$176,100","$184,500","No maximum"],"answer":2,"explain":"The 2026 taxable maximum is $184,500. Only Medicare tax has no maximum, which is the tempting distractor. Source: Federal Register (SSA) Cost-of-Living Increase and Other Determinations for 2026.","topic":"FICA","source":"Federal Register (SSA) Cost-of-Living Increase and Other Determinations for 2026 https://www.govinfo.gov/content/pkg/FR-2025-11-03/html/2025-19763.htm"},{"q":"How long is the SSDI waiting period?","choices":["5 months","6 months","12 months","24 months"],"answer":0,"explain":"There is a 5-month wait, so benefits begin in the 6th month. The 12-month figure is how long the disability must last. Source: 42 USC 423(c)(2).","topic":"Disability","source":"42 USC 423(c)(2) https://www.law.cornell.edu/uscode/text/42/423"},{"q":"A worker born in 1962 claims at 62. About what share of PIA is paid?","choices":["100%","80%","75%","70%"],"answer":3,"explain":"With FRA 67, claiming at 62 pays about 70% of PIA. The 80% figure applies only to FRA 65. Source: 42 USC 402(q).","topic":"Retirement","source":"42 USC 402(q) https://www.law.cornell.edu/uscode/text/42/402"},{"q":"Which statement about the blackout period is NOT correct?","choices":["It ends when the surviving spouse reaches 60","Children's benefits continue during it","It starts when the youngest child turns 18","It starts immediately if there are no children"],"answer":2,"explain":"It starts when the youngest child turns 16, not 18. Child benefits run to 18 (19 if in high school). Source: 20 CFR 404.341.","topic":"Blackout","source":"20 CFR 404.341 https://www.law.cornell.edu/cfr/text/20/404.341"},{"q":"Which statement about SSDI is NOT correct?","choices":["It converts to retirement benefits at FRA","There is no partial disability benefit","It requires the disability to last at least 12 months or result in death","It ends automatically at age 65 for everyone"],"answer":3,"explain":"SSDI converts to retirement at FRA, which is 66 or 67 for most people now, not at 65. Source: 42 USC 416(l).","topic":"Disability","source":"42 USC 416(l) https://www.law.cornell.edu/uscode/text/42/416"},{"q":"Which statement about survivor benefit amounts is NOT correct?","choices":["A child receives 75% of PIA","One dependent parent receives 82.5% of PIA","Each of two dependent parents receives 75% of PIA","Each of two dependent parents receives 82.5% of PIA"],"answer":3,"explain":"82.5% goes to ONE dependent parent. When two parents qualify, each gets 75%. Source: 42 USC 402(h)(2).","topic":"Survivor benefits","source":"42 USC 402(h)(2) https://www.law.cornell.edu/uscode/text/42/402"}],"scenarios":[{"situation":"Priya dies at age 40. She has 30 quarters of coverage, and 8 of them are in the last 13 quarters.","q":"What is her insured status?","choices":["Fully insured only","Neither fully nor currently insured","Both fully and currently insured","Currently insured only"],"answer":2,"explain":"Source: 20 CFR 404.110 and 404.120. Fully insured needs 1 quarter per year after age 21 (under 20 at age 40, never more than 40). Currently insured needs 6 of the last 13 quarters.","topic":"Insured status","source":"20 CFR 404.110 and 404.120 https://www.ecfr.gov/current/title-20/part-404/section-404.110"},{"situation":"A 45-year-old widow does not work. Her deceased husband was insured, and their child is 15.","q":"Is she receiving survivor benefits now, and when will the blackout end?","choices":["Yes now; the blackout starts at the child's 16th birthday and ends when she turns 60","No; the blackout is already running and ends at 62","No; benefits start only when she turns 60","Yes now; the blackout starts at the child's 18th birthday and ends at 65"],"answer":0,"explain":"Source: 20 CFR 404.339 and SSA. A widow is paid while caring for the worker's child under 16. After that, widow's benefits start at 60.","topic":"Blackout","source":"20 CFR 404.339; SSA Survivor eligibility https://www.ecfr.gov/current/title-20/part-404/section-404.339"},{"situation":"Tom is 64 in 2026 and has FRA 67. He collects retirement benefits while earning $30,000 from a part-time job.","q":"How much is withheld for the year under the 2026 earnings test?","choices":["$0, because there is no limit at his age","$2,760","$5,520","$1,840"],"answer":1,"explain":"Source: SSA. The 2026 limit before the NRA year is $24,480. $30,000 minus $24,480 is $5,520, and $1 withheld per $2 over is $2,760.","topic":"Earnings test","source":"SSA: Exempt Amounts Under the Earnings Test https://www.ssa.gov/oact/cola/rtea.html"}],"pairs":[{"term":"Part B","match":"Medicare medical insurance for doctor services and outpatient care","source":"Medicare.gov - Parts of Medicare https://www.medicare.gov/basics/get-started-with-medicare/medicare-basics/parts-of-medicare"},{"term":"Blackout period","match":"Spouse gets nothing from child's 16th birthday to spouse's 60th","source":"SSA Handbook 211 - Requirements for Insured Status https://www.ssa.gov/OP_Home/handbook/handbook.02/handbook-0211.html"},{"term":"Currently insured","match":"6 of last 13 quarters; survivor benefits only","source":"SSA Handbook 211 - Requirements for Insured Status https://www.ssa.gov/OP_Home/handbook/handbook.02/handbook-0211.html"}]},"ch11":{"title":"Chapter 11 - Retirement Plans","flashcards":[{"front":"Qualified vs. nonqualified plan?","back":"Qualified plans follow IRS rules and ERISA, get tax breaks, and cannot favor the highly paid. Nonqualified plans get no tax breaks and can favor executives.","topic":"Plan types","memory":"","source":"26 U.S.C. 401(a)(4) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/401"},{"front":"Defined contribution vs. defined benefit?","back":"DC sets the contribution and the employee bears investment risk. DB sets the benefit by formula and the employer bears the risk.","topic":"Plan types","memory":"DC = Dollars Contributed. DB = Dollars Benefit.","source":"U.S. Department of Labor, Types of Retirement Plans https://www.dol.gov/general/topic/retirement/typesofplans"},{"front":"Which ERISA exemptions are correct?","back":"Church and governmental plans are exempt. Collectively bargained (union) plans are generally NOT exempt.","topic":"ERISA","memory":"","source":"29 U.S.C. 1003(b) (Cornell LII) https://www.law.cornell.edu/uscode/text/29/1003"},{"front":"ERISA participation rule and annual form?","back":"Age 21 with 1 year of service (2 years if 100% immediate vesting). Plans file Form 5500 annually; the summary plan description is due within 90 days.","topic":"ERISA","memory":"","source":"29 U.S.C. 1052 and 1024 (Cornell LII) https://www.law.cornell.edu/uscode/text/29/1052"},{"front":"When is a plan top-heavy?","back":"When more than 60% of assets belong to key employees, measured on the last day of the prior plan year.","topic":"ERISA","memory":"","source":"26 U.S.C. 416(g) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/416"},{"front":"Who can use a 403(b)?","back":"Only 501(c)(3) nonprofits, public school employees, and some ministers. A for-profit employer uses a 401(k).","topic":"Plan types","memory":"","source":"IRS, 403(b) tax-sheltered annuity plans https://www.irs.gov/retirement-plans/irc-403b-tax-sheltered-annuity-plans"},{"front":"2026 401(k) employee deferral limit?","back":"$24,500 for 2026.","topic":"401(k)","memory":"","source":"IRS newsroom https://www.irs.gov/newsroom/401k-limit-increases-to-24500-for-2026-ira-limit-increases-to-7500"},{"front":"SIMPLE plan key facts?","back":"For employers with 100 or fewer employees, $5,000 prior-year pay, no other qualified plan, and immediate 100% vesting.","topic":"Small business","memory":"SIMPLE = 100 or fewer, instant vesting.","source":"26 U.S.C. 408(p) https://www.law.cornell.edu/uscode/text/26/408"},{"front":"What is a SARSEP?","back":"Salary reduction SEP for employers with 25 or fewer employees, set up before 1997. No new SARSEPs; existing ones may continue.","topic":"Small business","memory":"SARSEP = Salary + pre-1997.","source":"IRS SARSEP page https://www.irs.gov/retirement-plans/plan-sponsor/salary-reduction-simplified-employee-pension-plan-sarsep"},{"front":"RMD starting age under SECURE 2.0?","back":"73 for people born 1951 to 1959, and 75 for those born 1960 or later.","topic":"RMDs","memory":"","source":"26 U.S.C. 401(a)(9)(C)(v) https://www.law.cornell.edu/uscode/text/26/401"},{"front":"Penalty for missing an RMD now?","back":"25% of the shortfall, or 10% if corrected within two years.","topic":"RMDs","memory":"","source":"IRS RMD FAQ https://www.irs.gov/retirement-plans/retirement-plans-faqs-regarding-required-minimum-distributions"},{"front":"Inherited IRA rule for most non-spouse beneficiaries?","back":"They must empty the account within 10 years. Narrow exceptions include minor children of the owner, disabled or chronically ill people, and those not over 10 years younger.","topic":"Inherited IRA","memory":"","source":"IRS RMD FAQs https://www.irs.gov/retirement-plans/retirement-plan-and-ira-required-minimum-distributions-faqs"},{"front":"When is a Roth IRA withdrawal tax-free?","back":"The account must be at least 5 years old AND a qualifying event occurs: age 59 1/2, death, disability, or first home purchase ($10,000 lifetime).","topic":"Roth IRA","memory":"","source":"26 U.S.C. 408A(d)(2) and 72(t)(8) https://www.law.cornell.edu/uscode/text/26/408A"},{"front":"Direct vs. indirect rollover?","back":"Direct (trustee to trustee) has no withholding. Indirect has 20% withheld, and the owner must replace it from other money within 60 days.","topic":"Rollovers","memory":"Direct = no withholding.","source":"IRS Topic 413 https://www.irs.gov/taxtopics/tc413"},{"front":"Coverdell ESA key limits?","back":"Contributions up to $2,000 per beneficiary a year, and none after the beneficiary reaches 18 (except special needs). Balance must generally be distributed by age 30.","topic":"Education savings","memory":"","source":"26 U.S.C. 530 https://www.law.cornell.edu/uscode/text/26/530"}],"questions":[{"q":"Which type of plan can favor highly paid employees?","choices":["Qualified plan","Nonqualified plan","401(k) plan","ERISA-covered pension"],"answer":1,"explain":"Nonqualified plans such as NQDCs and SERPs can favor executives. Qualified plans cannot discriminate in favor of the highly paid. Source: 26 U.S.C. 401(a)(4) (Cornell LII).","topic":"Plan types","source":"26 U.S.C. 401(a)(4) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/401"},{"q":"Who bears the investment risk in a defined contribution plan?","choices":["The employer","The PBGC","The plan actuary","The employee"],"answer":3,"explain":"In a DC plan the benefit depends on contributions plus investment results, so the employee bears the risk. In a DB plan the employer does. Source: U.S. Department of Labor, Types of Retirement Plans.","topic":"Plan types","source":"U.S. Department of Labor, Types of Retirement Plans https://www.dol.gov/general/topic/retirement/typesofplans"},{"q":"What does a 457 plan serve?","choices":["Any private employer","State and local government and some nonprofit employees","Only self-employed people","Only public school teachers"],"answer":1,"explain":"457 plans are for state and local government and some nonprofit employees. 403(b) is the one for 501(c)(3)s and public schools. Source: 26 U.S.C. 457(e)(1) (Cornell LII).","topic":"Plan types","source":"26 U.S.C. 457(e)(1) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/457"},{"q":"Which Act introduced the Roth IRA?","choices":["ERISA of 1974","Pension Protection Act of 2006","Taxpayer Relief Act of 1997","SECURE Act of 2019"],"answer":2,"explain":"The Taxpayer Relief Act of 1997 created the Roth IRA. ERISA is the 1974 law protecting retirement benefits. Source: 26 U.S.C. 408A (Cornell LII).","topic":"Roth IRA","source":"26 U.S.C. 408A (Cornell LII) https://www.law.cornell.edu/uscode/text/26/408A"},{"q":"How much is withheld on an indirect rollover from a qualified plan?","choices":["10%","20%","25%","0%"],"answer":1,"explain":"20% is withheld on an indirect rollover. A direct trustee-to-trustee rollover has no withholding. Source: IRS, Rollovers of retirement plan and IRA distributions.","topic":"Rollovers","source":"IRS, Rollovers of retirement plan and IRA distributions https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"q":"How long does the owner have to complete a rollover to avoid tax?","choices":["30 days","45 days","60 days","90 days"],"answer":2,"explain":"The 60-day rule applies. The 90-day figure is the deadline for the summary plan description. Source: IRS, Rollovers of retirement plan and IRA distributions.","topic":"Rollovers","source":"IRS, Rollovers of retirement plan and IRA distributions https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"q":"What is the early withdrawal penalty on a traditional IRA before age 59 1/2?","choices":["5%","10%","20%","25%"],"answer":1,"explain":"10% plus income tax. The 25% figure is the current RMD-miss penalty, a different rule. Source: IRS, Exceptions to tax on early distributions.","topic":"Traditional IRA","source":"IRS, Exceptions to tax on early distributions https://www.irs.gov/retirement-plans/plan-participant-employee/retirement-topics-exceptions-to-tax-on-early-distributions"},{"q":"What is the lifetime limit for the first-home-purchase exception (IRA penalty and Roth qualified withdrawals)?","choices":["$5,000","$10,000","$15,000","$24,500"],"answer":1,"explain":"The first-time home purchase exception is $10,000 lifetime, for both traditional IRA penalty relief and Roth qualified withdrawals. Source: 26 U.S.C. 72(t)(8) (Cornell LII).","topic":"Early withdrawals","source":"26 U.S.C. 72(t)(8) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"Which statement about ERISA is NOT correct?","choices":["It requires annual Form 5500 reporting","Church plans are exempt","Collectively bargained plans are generally exempt","Employee contributions are always 100% vested"],"answer":2,"explain":"Union plans are generally covered by ERISA. Only church and governmental plans are exempt. Source: 29 U.S.C. 1003(b) (Cornell LII).","topic":"ERISA","source":"29 U.S.C. 1003(b) (Cornell LII) https://www.law.cornell.edu/uscode/text/29/1003"},{"q":"Which statement about a Roth IRA is NOT correct?","choices":["Contributions are made with after-tax dollars","There are no RMDs during the owner's life","Contributions are tax-deductible","Contributions can always be withdrawn tax-free"],"answer":2,"explain":"Roth contributions are not deductible. Their payoff is tax-free qualified withdrawals, and contributions come out tax-free because they were already taxed. Source: 26 U.S.C. 408A(c)(1) (Cornell LII).","topic":"Roth IRA","source":"26 U.S.C. 408A(c)(1) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/408A"},{"q":"Which statement about RMDs is NOT correct?","choices":["The age is 73 for people born 1951 to 1958","The age is 75 for people born 1960 or later","The penalty for a missed RMD is 50%","Roth IRAs have no RMDs during the owner's life"],"answer":2,"explain":"Source: IRS Retirement plan and IRA RMD FAQs; 26 U.S.C. 401(a)(9)(C)(v). The excise tax for a missed RMD is 25%, or 10% if timely corrected within two years, not 50%. (Birth year 1959 is ambiguous in the statute, so it is left out of the choices.)","topic":"RMDs","source":"26 U.S.C. 401(a)(9)(C)(v); IRS RMD page https://www.law.cornell.edu/uscode/text/26/401"},{"q":"Which statement about inherited IRAs is NOT correct?","choices":["Most non-spouse beneficiaries must empty the account within 10 years","A surviving spouse can roll the account into their own IRA","Most non-spouse beneficiaries can stretch payments over their lifetime","A minor child of the owner is a narrow exception"],"answer":2,"explain":"After the SECURE Act, most non-spouse beneficiaries face the 10-year rule, not a lifetime stretch. Source: 26 U.S.C. 401(a)(9)(H) and (E) (Cornell LII).","topic":"Inherited IRA","source":"26 U.S.C. 401(a)(9)(H) and (E) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/401"}],"scenarios":[{"situation":"Lee leaves his job and receives a check payable to himself for his 401(k) balance. The plan withheld 20% for taxes. He deposits the check into an IRA 30 days later.","q":"What should Lee have done to avoid the problem?","choices":["Wait 90 days before depositing","Deposit it into a Roth IRA instead","Cash the check and pay the 10% penalty","Request a direct trustee-to-trustee rollover"],"answer":3,"explain":"Source: IRS. A direct rollover avoids the mandatory 20% withholding. With a 60-day rollover he must use other money to roll over the full amount.","topic":"Rollovers","source":"IRS: Rollovers of Retirement Plan and IRA Distributions https://www.irs.gov/retirement-plans/plan-participant-employee/rollovers-of-retirement-plan-and-ira-distributions"},{"situation":"A 45-year-old woman works for a for-profit manufacturing company. She asks whether she can contribute to a 403(b) plan through her employer.","q":"What is the answer?","choices":["Yes, any employer can offer a 403(b)","No, 403(b) plans are only for 501(c)(3) nonprofits, public schools and some ministers","Yes, but only after age 50","No, because 403(b) plans are nonqualified"],"answer":1,"explain":"Source: IRS. 403(b) plans are for public schools, certain 501(c)(3) organizations and some ministers. For-profit employers use plans like a 401(k).","topic":"Plan types","source":"IRS: IRC 403(b) Tax-Sheltered Annuity Plans https://www.irs.gov/retirement-plans/irc-403b-tax-sheltered-annuity-plans"},{"situation":"A self-employed consultant has no employees. She wants a retirement plan with high contribution limits and simple administration.","q":"Which plan fits best?","choices":["SARSEP","A SEP (or solo 401(k)-type plan)","A coverdell ESA","A nonqualified deferred compensation plan"],"answer":1,"explain":"Source: IRS. A SEP is easy to set up, open even to the self-employed, and allows up to 25% of pay. A SARSEP had to be set up before 1997.","topic":"Small business","source":"IRS: Simplified Employee Pension Plan (SEP) https://www.irs.gov/retirement-plans/plan-sponsor/simplified-employee-pension-plan-sep"}],"pairs":[{"term":"ERISA","match":"1974 law setting minimum standards for private retirement and health plans","source":"U.S. Department of Labor - ERISA https://www.dol.gov/general/topic/retirement/erisa"},{"term":"NQDC","match":"Nonqualified deferred pay, not taxed as income until paid if rules are met","source":"IRS Publication 525 https://www.irs.gov/publications/p525"},{"term":"Money purchase plan","match":"Defined contribution plan with a fixed contribution formula","source":"IRS - Choosing a retirement plan: Money purchase plan https://www.irs.gov/retirement-plans/choosing-a-retirement-plan-money-purchase-plan"},{"term":"ESOP","match":"Qualified defined contribution plan investing mainly in employer stock","source":"IRS - Employee Stock Ownership Plans (ESOPs) https://www.irs.gov/retirement-plans/employee-stock-ownership-plans-esops"},{"term":"Conduit IRA","match":"Temporary holding account for funds moving between qualified plans","source":"IRS Publication 590-A https://www.irs.gov/publications/p590a"},{"term":"Coverdell ESA","match":"Education account: $2,000 a year per beneficiary under 18","source":"IRS Publication 970 https://www.irs.gov/publications/p970"}]},"ch12":{"title":"Chapter 12 - Health and Accident Insurance","flashcards":[{"front":"COBRA coverage length by qualifying event?","back":"18 months for job loss or reduced hours (29 if disabled). 36 months for death, divorce, child aging out, or Medicare eligibility.","topic":"COBRA","memory":"18 for the employee leaving, 36 for the family.","source":"26 U.S.C. 4980B (Cornell LII) https://www.law.cornell.edu/uscode/text/26/4980B"},{"front":"COBRA employer size, election time, and cost cap?","back":"Employers with 20 or more employees. 60 days to elect. Up to 102% of the premium.","topic":"COBRA","memory":"","source":"26 U.S.C. 4980B and DOL COBRA pages https://www.law.cornell.edu/uscode/text/26/4980B"},{"front":"What did the ACA do to preexisting-condition exclusions?","back":"It banned them in most individual and group plans (2014). The old HIPAA lookback and 63-day break rules are history only.","topic":"HIPAA and ACA","memory":"","source":"42 U.S.C. 300gg-3 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/300gg-3"},{"front":"ACA rules on dependents and benefit limits?","back":"Children may stay on a parent's plan until age 26, married or not. Plans may not set lifetime or annual dollar limits on essential health benefits.","topic":"HIPAA and ACA","memory":"","source":"HealthCare.gov; 45 CFR 147.126 https://www.healthcare.gov/young-adults/children-under-26/"},{"front":"ACA metal tiers: what share of costs does each plan pay (estimated)?","back":"Bronze 60%, Silver 70%, Gold 80%, Platinum 90% (estimated plan share of covered costs).","topic":"HIPAA and ACA","memory":"60-70-80-90.","source":"HealthCare.gov plan categories https://www.healthcare.gov/choose-a-plan/plans-categories/"},{"front":"2026 HSA contribution limits and catch-up?","back":"$4,400 self-only, $8,750 family (IRS Pub. 969). Age 55 or older at year end adds $1,000. Requires an HDHP. Contributions stop once the individual is entitled to Medicare (26 U.S.C. 223(b)(7)).","topic":"HSA","memory":"","source":"IRS Publication 969 https://www.irs.gov/publications/p969"},{"front":"HSA penalty for nonqualified withdrawals?","back":"20% penalty plus income tax. Qualified medical withdrawals are tax-free. Medigap premiums are NOT qualified.","topic":"HSA","memory":"","source":"26 U.S.C. 223 (Cornell LII) https://www.law.cornell.edu/uscode/text/26/223"},{"front":"Who is primary when a worker with a group plan is 65+?","back":"If the employer has 20 or more employees, the group plan is primary and Medicare secondary. Under 20, Medicare is primary.","topic":"Coordination of benefits","memory":"","source":"42 U.S.C. 1395y(b)(1) Medicare Secondary Payer https://www.law.cornell.edu/uscode/text/42/1395y"},{"front":"Birthday rule for dependent children?","back":"The plan of the parent whose birthday falls earlier in the calendar year is primary. Each spouse's own plan is primary for that spouse.","topic":"Coordination of benefits","memory":"","source":"Connecticut Office of the Healthcare Advocate; NAIC COB model https://portal.ct.gov/oha/learn-about-health-insurance/coordination-of-benefits/birthday-rule"},{"front":"Accidental means vs. accidental results?","back":"Means: the cause itself must be accidental, not merely an unexpected result of a deliberate act (stricter). Results: only the outcome must be unintended. Courts and policy wording vary.","topic":"AD&D","memory":"","source":"IRMI glossary https://www.irmi.com/term/insurance-definitions/accidental-means"},{"front":"Principal sum vs. capital sum in AD&D?","back":"Principal sum is the full benefit, paid on accidental death. Loss of a single member generally pays a fraction of it (often one-half), set by the policy schedule.","topic":"AD&D","memory":"","source":"IRMI glossary AD&D https://www.irmi.com/term/insurance-definitions/accidental-death-and-dismemberment"},{"front":"Tax rule for disability income benefits?","back":"Benefits are tax-free if the insured paid the premiums (individual policy or employee-paid group). Employer-paid group disability benefits are taxable.","topic":"Taxation","memory":"","source":"IRS Publication 525; 26 U.S.C. 104(a)(3) https://www.irs.gov/publications/p525"}],"questions":[{"q":"What does the out-of-pocket maximum NOT count?","choices":["Deductibles","Coinsurance","Premiums","Copayments"],"answer":2,"explain":"Premiums and non-covered services do not count toward the out-of-pocket maximum. After it is reached, insurance pays 100% of covered costs. Source: HealthCare.gov glossary.","topic":"Cost sharing","source":"HealthCare.gov glossary https://www.healthcare.gov/glossary/out-of-pocket-maximum-limit/"},{"q":"What is a 501(c)(9) trust (VEBA) used for?","choices":["Funding employee benefits","Funding retirement plans for the self-employed","Holding HSA funds","Paying workers' compensation claims"],"answer":0,"explain":"A VEBA is a funding vehicle for employee benefits, with deductible contributions and a single purpose. Source: 26 U.S.C. 501(c)(9).","topic":"Funding","source":"26 U.S.C. 501(c)(9) https://www.law.cornell.edu/uscode/text/26/501"},{"q":"How many days does a person have to elect COBRA coverage?","choices":["30 days","60 days","90 days","102 days"],"answer":1,"explain":"60 days. The 102% figure is the maximum premium share, not a time limit. Source: 29 U.S.C. 1165.","topic":"COBRA","source":"29 U.S.C. 1165 https://www.law.cornell.edu/uscode/text/29/1165"},{"q":"Under the ACA, how long can a child stay on a parent's health plan?","choices":["Until age 19","Until age 23","Until age 26","Until age 30"],"answer":2,"explain":"Source: 42 U.S.C. 300gg-14. Coverage must remain available until the child turns 26. Age 30 relates to the Coverdell ESA balance distribution rule, 26 U.S.C. 530, a different rule.","topic":"ACA","source":"42 U.S.C. 300gg-14 https://www.law.cornell.edu/uscode/text/42/300gg-14"},{"q":"A group has 18 employees and a worker over 65 is covered. Who pays first?","choices":["The group plan","Medicare","They split equally","Neither; a Medigap plan pays first"],"answer":1,"explain":"Employers with fewer than 20 employees: Medicare is primary. With 20 or more, the group plan is primary. Source: 42 U.S.C. 1395y(b)(1)(A).","topic":"Coordination of benefits","source":"42 U.S.C. 1395y(b)(1)(A) https://www.law.cornell.edu/uscode/text/42/1395y"},{"q":"Which statement about COBRA is NOT correct?","choices":["It applies to employers with 20 or more employees","A covered employee who dies gives dependents 36 months","The participant may be charged up to 102% of the premium","It guarantees coverage at the employer's cost"],"answer":3,"explain":"COBRA continuation is at the participant's own expense. Charging up to 102% covers administration. Source: 29 U.S.C. 1162 and 1161(b).","topic":"COBRA","source":"29 U.S.C. 1162 and 1161(b) https://www.law.cornell.edu/uscode/text/29/1162"},{"q":"Which statement about HIPAA and the ACA is NOT correct?","choices":["HIPAA does not apply to disability income plans","The ACA banned preexisting-condition exclusions in most plans","The old 63-day break rule is still a current rule","HIPAA has Privacy and Security Rules"],"answer":2,"explain":"The 63-day break and creditable coverage rules are old HIPAA rules made obsolete by the ACA. Know them as history. Source: 42 U.S.C. 300gg-3.","topic":"HIPAA and ACA","source":"42 U.S.C. 300gg-3 https://www.law.cornell.edu/uscode/text/42/300gg-3"},{"q":"Which statement about HSAs is NOT correct?","choices":["Contributions are limited to 100% of the deductible","An HDHP is required","Earnings grow tax-free","The balance is fully portable"],"answer":0,"explain":"Source: 26 U.S.C. 223. The annual HSA limit is a statutory dollar amount indexed for inflation, not a percentage of the deductible. An HDHP is required for eligibility.","topic":"HSA","source":"26 U.S.C. 223 https://www.law.cornell.edu/uscode/text/26/223"}],"scenarios":[{"situation":"Carla works for an employer with 35 employees. She is terminated for reasons other than gross misconduct and has a family on her group health plan. She is not disabled.","q":"How long can she keep group coverage, and at what maximum cost?","choices":["36 months at 100%","18 months at 102%","29 months at 102%","18 months at 150%"],"answer":1,"explain":"Source: 29 U.S.C. 1162 and 1161. Job loss gives 18 months at up to 102% of the premium. COBRA applies to employers with 20 or more employees.","topic":"COBRA","source":"29 U.S.C. 1162 and 1161 https://www.law.cornell.edu/uscode/text/29/1162"},{"situation":"Matt's individual disability policy must be renewed by the insurer each year, but his premium can go up if it is raised for his whole class.","q":"What renewability type is it?","choices":["Cancelable","Conditionally renewable","Guaranteed renewable","Optionally renewable"],"answer":2,"explain":"Source: IRMI Glossary. Guaranteed renewable means the insurer must renew, but the premium can change for the entire class.","topic":"Renewability","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/guaranteed-renewable"},{"situation":"A surgeon loses one hand in an accident. Her AD&D policy pays a lump sum for the loss.","q":"What is the maximum one-sum amount an AD&D policy pays for accidental death or dismemberment called?","choices":["Elimination period","Capital sum","Coinsurance","Residual benefit"],"answer":1,"explain":"Source: IRMI Glossary. The capital sum is the maximum amount payable in one sum for accidental death or dismemberment.","topic":"AD&D","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/capital-sum"}],"pairs":[{"term":"COBRA","match":"Continuation of group coverage at own expense, up to 102%","source":"29 U.S.C. 1162 (Cornell LII) https://www.law.cornell.edu/uscode/text/29/1162"},{"term":"Coinsurance","match":"Percentage the insured pays after the deductible","source":"HealthCare.gov Glossary - Coinsurance https://www.healthcare.gov/glossary/co-insurance/"},{"term":"Principal sum","match":"AD&D amount paid for accidental death","source":"IRMI Glossary - Principal Sum https://www.irmi.com/term/insurance-definitions/principal-sum"},{"term":"Probationary period","match":"Set time after policy start when sickness is not covered","source":"IRMI Glossary - Probationary Period https://www.irmi.com/term/insurance-definitions/probationary-period"},{"term":"Business overhead expense","match":"Pays an owner's business expenses during disability, not owner pay","source":"IRS Publication 334 https://www.irs.gov/publications/p334"},{"term":"Hospital indemnity","match":"Fixed payment per day of hospital stay","source":"45 CFR 148.220 (Cornell LII) https://www.law.cornell.edu/cfr/text/45/148.220"}]},"ch13":{"title":"Chapter 13 - Health Insurance Providers (and Government Health Programs)","flashcards":[{"front":"HMO key features?","back":"Limits coverage to doctors who work for or contract with the HMO. Generally no out-of-network coverage except in an emergency.","topic":"HMO vs. PPO","memory":"","source":"HealthCare.gov plan types https://www.healthcare.gov/choose-a-plan/plan-types/"},{"front":"PPO key features?","back":"Network of contracted providers; you pay less in network. Out-of-network providers can be used without a referral for an additional cost.","topic":"HMO vs. PPO","memory":"","source":"HealthCare.gov plan types https://www.healthcare.gov/choose-a-plan/plan-types/"},{"front":"POS vs. EPO?","back":"POS: pay less in network and need a referral from your primary care doctor to see a specialist. EPO: covered only in network, except in an emergency.","topic":"HMO vs. PPO","memory":"","source":"HealthCare.gov plan types https://www.healthcare.gov/choose-a-plan/plan-types/"},{"front":"What is capitation?","back":"A fixed payment per member assigned to a physician or medical group, regardless of services used.","topic":"HMO","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/consumer_glossary"},{"front":"Medicare Part A vs. Part B funding and cost?","back":"Part A: payroll taxes, usually premium-free, automatic. Part B: general revenue plus premiums, optional. Part B pays 80% after the deductible.","topic":"Medicare","memory":"","source":"CMS Brief Summaries of Medicare & Medicaid https://www.cms.gov/files/document/brief-summaries-medicare-medicaid-september-30-2022.pdf"},{"front":"Who administers Medicare?","back":"CMS administers Medicare. The Social Security Administration handles enrollment and public information.","topic":"Medicare","memory":"","source":"CMS Brief Summaries of Medicare & Medicaid https://www.cms.gov/files/document/brief-summaries-medicare-medicaid-september-30-2022.pdf"},{"front":"Medicare eligibility for disabled people under 65?","back":"24 months of Social Security disability benefits. ALS skips the wait (Medicare starts the month disability benefits begin). ESRD has its own rule: coverage generally begins the third month after dialysis starts.","topic":"Medicare","memory":"","source":"Medicare & You handbook (medicare.gov) https://www.medicare.gov/publications/10050-medicare-and-you.pdf"},{"front":"When is Medicare primary for age-based coverage?","back":"With employer plans under 20 employees, Medicare pays first. At 20 or more, the group plan is primary. Disability-based line is 100 employees.","topic":"Medicare","memory":"Age: 20. Disability: 100.","source":"Medicare & You handbook (medicare.gov) https://www.medicare.gov/publications/10050-medicare-and-you.pdf"},{"front":"Medicare assignment vs. excess charge?","back":"With assignment the doctor accepts the Medicare-approved amount as full payment. The excess charge is the extra billed by a doctor who does not accept assignment.","topic":"Medicare","memory":"","source":"CMS Brief Summaries of Medicare & Medicaid https://www.cms.gov/files/document/brief-summaries-medicare-medicaid-september-30-2022.pdf"},{"front":"Medicare vs. Medicaid?","back":"Medicare: federal health and hospital insurance for people 65+ and certain younger Social Security recipients; eligibility does not depend on income. Medicaid: jointly financed by state and federal governments for low-income individuals.","topic":"Government programs","memory":"","source":"Cornell LII Wex (Medicaid, Medicare) https://www.law.cornell.edu/wex/medicaid"},{"front":"Four Louisiana workers' compensation disability benefit types?","back":"Temporary total, permanent total, supplemental earnings benefits, and permanent partial (La. R.S. 23:1221).","topic":"Workers' compensation","memory":"","source":"La. R.S. 23:1221 https://legis.la.gov/legis/Law.aspx?d=83447"},{"front":"TRICARE plans and what is a MEWA?","back":"TRICARE current U.S. plans include Prime and Select (Extra and Standard are no longer listed). A MEWA is an arrangement providing welfare benefits to employees of two or more employers (ERISA 3(40)).","topic":"Other programs","memory":"","source":"TRICARE health plans; DOL MEWA guidance (ERISA 3(40)) https://www.tricare.mil/Plans/HealthPlans"}],"questions":[{"q":"Which Medicare part is financed through the Federal Hospital Insurance Trust Fund, supported by payroll taxes?","choices":["Part B","Part C","Part D","Part A"],"answer":3,"explain":"Source: 42 U.S.C. 1395i. The Federal Hospital Insurance Trust Fund, which pays for Part A hospital insurance, is funded by Treasury transfers tied to payroll (FICA) taxes.","topic":"Medicare","source":"42 U.S.C. 1395i https://www.law.cornell.edu/uscode/text/42/1395i"},{"q":"Medicaid is best described as:","choices":["A federal program for people over 65","A joint federal-state program for low-income people, run by the states","A private insurance plan for veterans","A program funded only by payroll taxes"],"answer":1,"explain":"Medicaid (Title XIX, 1965) is joint federal-state and need-based. Medicare is the federal age/disability program. Source: 42 U.S.C. 1396-1 (Title XIX).","topic":"Government programs","source":"42 U.S.C. 1396-1 (Title XIX) https://www.law.cornell.edu/uscode/text/42/1396-1"},{"q":"How many months of SSDI must a disabled person under 65 receive before Medicare begins (outside ESRD and ALS)?","choices":["5 months","12 months","36 months","24 months"],"answer":3,"explain":"24 months of Social Security disability benefits. The 5-month figure is the SSDI waiting period itself. Source: Medicare & You handbook (medicare.gov).","topic":"Medicare","source":"Medicare & You handbook (medicare.gov) https://www.medicare.gov/publications/10050-medicare-and-you.pdf"},{"q":"What does Part B pay after the deductible for covered services?","choices":["50%","80%","100%","90%"],"answer":1,"explain":"Part B pays 80% and the enrollee pays 20% coinsurance after the deductible. Source: Medicare.gov Medicare costs.","topic":"Medicare","source":"Medicare.gov Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"q":"For age-based Medicare, at what employer size does the group plan become primary?","choices":["10 or more","20 or more","50 or more","100 or more"],"answer":1,"explain":"20 or more employees. The 100-employee line applies to disability-based Medicare. Source: 42 CFR 411.172 (Cornell LII).","topic":"Medicare","source":"42 CFR 411.172 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/411.172"},{"q":"Which statement about PPOs is NOT correct?","choices":["They offer discounted fees through a provider network","They are prepaid plans","Referrals are not required","Out-of-network care is covered at reduced benefits"],"answer":1,"explain":"PPOs are fee-for-service, not prepaid. HMOs are the prepaid type. Source: HealthCare.gov plan types.","topic":"HMO vs. PPO","source":"HealthCare.gov plan types https://www.healthcare.gov/choose-a-plan/plan-types/"},{"q":"Which statement about Medicare is NOT correct?","choices":["Part A is usually premium-free if eligible","Part B enrollment is optional","It was established in 1965","It is run by the states"],"answer":3,"explain":"Medicare is a federal program run by CMS. Medicaid is the one administered by the states. Source: CMS Brief Summaries of Medicare & Medicaid.","topic":"Medicare","source":"CMS Brief Summaries of Medicare & Medicaid https://www.cms.gov/files/document/brief-summaries-medicare-medicaid-september-30-2022.pdf"},{"q":"Which is NOT covered by Medicare Parts A and B?","choices":["Private-duty nursing","Inpatient hospital stays","Doctor visits","Preventive screenings"],"answer":0,"explain":"Private-duty nurses and personal attendants are excluded from both parts. The others are covered under A or B. Source: Medicare & You handbook (medicare.gov).","topic":"Medicare","source":"Medicare & You handbook (medicare.gov) https://www.medicare.gov/publications/10050-medicare-and-you.pdf"},{"q":"Which statement about workers' compensation benefits is NOT correct?","choices":["Medical benefits have no time limit","Survivor benefits cover dependents and burial expenses","Rehabilitation services are included","Employees pay the premiums"],"answer":3,"explain":"Employers fund workers' compensation through state programs, private insurers or self-insurance. Employees do not pay premiums. Source: La. R.S. 23:1163.","topic":"Workers' compensation","source":"La. R.S. 23:1163 https://legis.la.gov/legis/Law.aspx?d=83387"}],"scenarios":[{"situation":"Ruth wants to see specialists without getting a referral first. She does not mind paying more for care outside the network.","q":"Which structure fits her?","choices":["Staff-model HMO","POS plan","PPO","Closed-panel HMO"],"answer":2,"explain":"Source: HealthCare.gov. A PPO lets you see out-of-network providers without a referral at extra cost. A POS plan needs a referral to see a specialist.","topic":"HMO vs. PPO","source":"HealthCare.gov: Health plan types https://www.healthcare.gov/choose-a-plan/plan-types/"},{"situation":"Greg is 67 and works for a company with 15 employees. He is covered by the company's group health plan and is also eligible for Medicare.","q":"Which coverage pays first?","choices":["The group plan","Medicare","Medicaid","They pay equal shares"],"answer":1,"explain":"Source: Medicare.gov. With an employer of fewer than 20 employees, Medicare pays first and the group plan pays second.","topic":"Medicare","source":"Medicare.gov: Who pays first https://www.medicare.gov/health-drug-plans/coordination/who-pays-first"},{"situation":"Several small employers want to join together to offer health benefits to their workers through one arrangement.","q":"What is this arrangement called?","choices":["A multiple employer welfare arrangement (MEWA)","A Health Savings Account","TRICARE","A Medigap policy"],"answer":0,"explain":"Source: IRMI Glossary. A MEWA is a benefit plan or arrangement involving two or more employers that provides medical and other benefits.","topic":"Other programs","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/multiple-employer-welfare-arrangement"}],"pairs":[{"term":"HMO","match":"Provides or arranges health care for enrollees for a prepaid charge","source":"La. R.S. 22:242 https://legis.la.gov/Legis/Law.aspx?d=506416"},{"term":"PPO","match":"Network plan; pay less in network, no referral needed to go outside","source":"HealthCare.gov - Plan types https://www.healthcare.gov/choose-a-plan/plan-types/"},{"term":"Capitation","match":"Fixed periodic payment per enrollee, whether or not services are used","source":"42 CFR 438.2 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/438.2"},{"term":"Medicaid","match":"State-administered program for low-income people","source":"42 CFR 430.0 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/430.0"},{"term":"Medicare Part B","match":"Voluntary medical coverage funded by enrollee premiums and federal funds","source":"42 U.S.C. 1395j (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395j"},{"term":"Precertification","match":"Insurer approval required before certain services, except emergencies","source":"HealthCare.gov Glossary - Preauthorization https://www.healthcare.gov/glossary/preauthorization/"}]},"ch14":{"title":"Chapter 14 - Medical Expense Insurance","flashcards":[{"front":"What does coinsurance mean?","back":"The percentage of covered costs the insured pays after the deductible has been met (for example 20%, so the insurer pays 80%, written 80/20).","topic":"Coinsurance","memory":"","source":"HealthCare.gov Glossary https://www.healthcare.gov/glossary/co-insurance/"},{"front":"What does a stop-loss provision do?","back":"It caps the insured's total out-of-pocket costs. After the limit, the insurer pays 100%.","topic":"Coinsurance","memory":"","source":"HealthCare.gov Glossary https://www.healthcare.gov/glossary/out-of-pocket-maximum-limit/"},{"front":"Order of the claims calculation?","back":"Subtract the deductible first, then apply coinsurance to what remains, then check the stop-loss cap.","topic":"Claims math","memory":"Deductible first, then coinsurance.","source":"HealthCare.gov Glossary https://www.healthcare.gov/glossary/co-insurance/"},{"front":"Who receives hospital indemnity benefits, and on what basis?","back":"Hospital indemnity pays a pre-determined, fixed benefit or daily indemnity for a hospital or intensive care stay (NAIC glossary).","topic":"Specialty policies","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"front":"HSA vs. HRA vs. FSA?","back":"HSA: requires an HDHP; contributions can come from the individual, employer or others. HRA: employer-funded only. FSA: funded usually by employee salary reductions; use-it-or-lose-it, with a plan-allowed grace period or limited carryover (IRS Pub. 969).","topic":"Tax-advantaged accounts","memory":"HRA = employer; FSA = use it or lose it.","source":"IRS Publication 969 https://www.irs.gov/publications/p969"}],"questions":[{"q":"Which account can be funded ONLY by the employer?","choices":["HSA","HRA","FSA","MSA"],"answer":1,"explain":"An HRA is employer-funded only. HSAs can be funded by individual or employer, and FSAs by the employee. Source: IRS Publication 969.","topic":"Tax-advantaged accounts","source":"IRS Publication 969 https://www.irs.gov/publications/p969"},{"q":"Which statement about hospital indemnity policies is NOT correct?","choices":["Benefits are paid to the insured","Benefits are a fixed amount per day, week or month","Benefits depend on days confined","Benefits are based on actual medical expenses"],"answer":3,"explain":"Hospital indemnity pays a fixed benefit regardless of actual bills. Reimbursement policies pay actual charges. Source: Maryland Insurance Administration.","topic":"Specialty policies","source":"Maryland Insurance Administration https://insurance.maryland.gov/Consumer/Pages/Hospital-Fixed-Indemnity.aspx"},{"q":"Which statement about FSAs is NOT correct?","choices":["They are funded by the employee through a cafeteria plan","They require a high-deductible health plan","They are generally use it or lose it","Some employers allow a limited carryover or grace period"],"answer":1,"explain":"An HDHP is required for an HSA, not an FSA. Source: IRS Publication 969.","topic":"Tax-advantaged accounts","source":"IRS Publication 969 https://www.irs.gov/publications/p969"}],"scenarios":[{"situation":"Ben has $5,000 of covered medical bills. His policy has a $1,000 deductible and 80/20 coinsurance, with no stop-loss reached.","q":"How much does Ben pay in total?","choices":["$800","$1,000","$1,800","$4,000"],"answer":2,"explain":"Source: HealthCare.gov. Ben pays the $1,000 deductible, then 20% of the remaining $4,000 ($800), for $1,800 total.","topic":"Claims math","source":"HealthCare.gov: Coinsurance https://www.healthcare.gov/glossary/co-insurance/"},{"situation":"Lisa has a basic health plan that pays from the first dollar. She adds major medical coverage that pays above it, with a deductible in between the two.","q":"What is that in-between deductible called?","choices":["Coinsurance","Corridor deductible","Elimination period","Stop-loss"],"answer":1,"explain":"Source: IRMI Glossary. A corridor deductible sits between a first-dollar health plan and the major medical coverage above it.","topic":"Basic vs. major","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/corridor-self-insured-retention"},{"situation":"A worker wants a health account that she personally owns, that is portable and works together with a high-deductible health plan.","q":"Which account fits?","choices":["HRA","FSA","HSA","Employer-only reimbursement account"],"answer":2,"explain":"Source: IRS Publication 969. An HSA requires an HDHP and is portable, staying with you if you change jobs. An HRA is employer-funded and employer-owned.","topic":"Tax-advantaged accounts","source":"IRS Publication 969 https://www.irs.gov/publications/p969"}],"pairs":[{"term":"Relative value","match":"Service's unit value times a conversion factor sets payment","source":"42 CFR 414.20 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/414.20"},{"term":"HRA","match":"Reimbursement account funded only by the employer","source":"HealthCare.gov Glossary - HRA https://www.healthcare.gov/glossary/health-reimbursement-account-hra/"},{"term":"Critical illness","match":"Lump sum paid on diagnosis of a listed serious illness","source":"IRMI Glossary - Critical Illness Insurance https://www.irmi.com/term/insurance-definitions/critical-illness-insurance"}]},"ch15":{"title":"Chapter 15 - Disability Income Insurance","flashcards":[{"front":"Waiver of premium rider","back":"The insurer gives up its right to collect premium while the insured is totally disabled. It pays no income and is not a loan. Waiting period and end age vary by policy.","topic":"Riders","memory":"","source":"IRMI glossary: waiver of premium https://www.irmi.com/term/insurance-definitions/waiver-of-premium"},{"front":"What does disability income insurance pay for?","back":"Source: IRMI Glossary: Disability Income Insurance. It provides periodic payments to replace income lost when the insured cannot work because of sickness or injury.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Disability Income Insurance https://www.irmi.com/term/insurance-definitions/disability-income-insurance"},{"front":"Which causes of inability to work does disability income insurance respond to?","back":"Source: IRMI Glossary: Disability Income Insurance. Sickness or injury.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Disability Income Insurance https://www.irmi.com/term/insurance-definitions/disability-income-insurance"},{"front":"Why must a disability definition be read carefully?","back":"Source: IRMI Glossary: Disability Income Insurance. The definition of disability varies substantially from policy to policy and decides when benefits are payable.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Disability Income Insurance https://www.irmi.com/term/insurance-definitions/disability-income-insurance"},{"front":"What is an elimination period?","back":"Source: IRMI Glossary: Elimination Period. A waiting period that must run before disability income benefits become payable.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Elimination Period https://www.irmi.com/term/insurance-definitions/elimination-period"},{"front":"Elimination period vs. probationary period?","back":"Source: IRMI Glossary: Probationary Period. A probationary period bars benefits for sickness commencing during a specified time (e.g., 15-30 days) after policy inception; IRMI's elimination period entry also calls the elimination period a waiting or probationary period before benefits are payable.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Probationary Period https://www.irmi.com/term/insurance-definitions/probationary-period"},{"front":"What is a probationary period?","back":"Source: IRMI Glossary: Probationary Period. A provision in some disability income policies stating benefits are not payable for sickness arising during a set time after the policy begins.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Probationary Period https://www.irmi.com/term/insurance-definitions/probationary-period"},{"front":"What is a partial disability?","back":"Source: IRMI Glossary: Partial Disability. A disability that is not total.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Partial Disability https://www.irmi.com/term/insurance-definitions/partial-disability"},{"front":"How do policies often define partial disability?","back":"Source: IRMI Glossary: Partial Disability. As the inability to perform one or more of the important duties of the insured's occupation.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Partial Disability https://www.irmi.com/term/insurance-definitions/partial-disability"},{"front":"How is a partial disability benefit typically set?","back":"Source: IRMI Glossary: Partial Disability. Partial disability is a disability that is not total; its benefit is typically a set share of the total disability benefit, paid for a limited period.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Partial Disability https://www.irmi.com/term/insurance-definitions/partial-disability"},{"front":"What is waiver of premium?","back":"Source: IRMI Glossary: Waiver of Premium. An insurer's known relinquishment of its right to collect premium from the insured.","topic":"Disability income insurance","memory":"","source":"IRMI Glossary: Waiver of Premium https://www.irmi.com/term/insurance-definitions/waiver-of-premium"},{"front":"Tax on benefits when the employee paid the premium with after-tax dollars?","back":"Source: Cornell LII, 26 U.S.C. 104. Benefits are excluded from gross income under IRC 104(a)(3), because they are not attributable to untaxed employer contributions.","topic":"Disability income insurance","memory":"","source":"Cornell LII, 26 U.S.C. 104 https://www.law.cornell.edu/uscode/text/26/104"},{"front":"Tax on benefits when the employer paid the premium?","back":"Source: Cornell LII, 26 U.S.C. 105. Under IRC 105(a), amounts attributable to employer contributions or paid by the employer are included in gross income.","topic":"Disability income insurance","memory":"","source":"Cornell LII, 26 U.S.C. 105 https://www.law.cornell.edu/uscode/text/26/105"}],"questions":[{"q":"Which coverage pays if the insured cannot perform the duties of his or her own job, even if another job is possible?","choices":["Any-occupation","Own-occupation","Residual","Presumptive"],"answer":1,"explain":"Own-occupation looks only at the insured's own job. Any-occupation is the tempting one, but it pays only if no suitable job can be done. Source: NAIC Consumer Insight: Simplifying the Complications of Disability Insurance.","topic":"Own vs any occupation","source":"NAIC Consumer Insight: Simplifying the Complications of Disability Insurance https://content.naic.org/article/consumer-insight-simplifying-complications-disability-insurance"},{"q":"Under accidental results, what must be unexpected?","choices":["Only the cause","Both the cause and the result","The insured's activity","Only the result"],"answer":3,"explain":"Accidental results requires only that the RESULT be unexpected. Requiring both cause and result is the stricter accidental means rule. Source: IRMI Glossary: accidental means.","topic":"Accidental means","source":"IRMI Glossary: accidental means https://www.irmi.com/term/insurance-definitions/accidental-means"},{"q":"Under the percent-of-earnings method, what percentage of pre-disability earnings is usually paid?","choices":["60%","50%","20%","100%"],"answer":0,"explain":"Source: NAIC Consumer Insight, Simplifying the Complications of Disability Insurance. A typical disability benefit is approximately 60% of pre-disability earned income, so $5,000 a month of earnings gives about $3,000.","topic":"Benefit calculation","source":"NAIC Consumer Insight: Simplifying the Complications of Disability Insurance https://content.naic.org/article/consumer-insight-simplifying-complications-disability-insurance"},{"q":"Which expense does business overhead expense insurance NOT pay?","choices":["Rent","Employee salaries","The disabled owner's salary","Equipment leases"],"answer":2,"explain":"BOE pays operating expenses of the business. The owner's own salary is not covered. Source: NAIC Small Business Insurance.","topic":"Business uses","source":"NAIC Small Business Insurance https://content.naic.org/consumer/small-business.htm"},{"q":"Which statement about the waiver of premium rider is NOT correct?","choices":["It pays the insured a monthly income","It keeps the policy in force during total disability","It relieves the insured of paying premiums while totally disabled","It is not a loan"],"answer":0,"explain":"Source: IRMI glossary, waiver of premium. The insurer gives up its right to collect premium; it does not pay the insured income and is not a loan.","topic":"Riders","source":"IRMI glossary: waiver of premium https://www.irmi.com/term/insurance-definitions/waiver-of-premium"},{"topic":"Disability Income and Related Insurance","q":"A disability income policy requires a period to pass after disability begins before benefits are payable. This is the:","choices":["Grace period","Elimination period","Free-look period","Contestable period"],"answer":1,"explain":"Source: IRMI Glossary: Elimination Period. The elimination period is a waiting period that must run before benefits are payable.","verdict":"confirmed","source":"IRMI Glossary: Elimination Period https://www.irmi.com/term/insurance-definitions/elimination-period"},{"topic":"Disability Income and Related Insurance","q":"A policy bars benefits for sickness during a set time after the policy begins. This provision is a:","choices":["Waiver of premium","Residual benefit","Probationary period","Presumptive disability clause"],"answer":2,"explain":"Source: IRMI Glossary: Probationary Period. A probationary period stipulates benefits are not payable for sickness during a specified time after the policy starts.","verdict":"confirmed","source":"IRMI Glossary: Probationary Period https://www.irmi.com/term/insurance-definitions/probationary-period"},{"topic":"Disability Income and Related Insurance","q":"An insured's disability is not total, and the policy pays for inability to perform important duties of the occupation. This is:","choices":["Partial disability","Accidental death","Total disability","Presumptive disability"],"answer":0,"explain":"Source: IRMI Glossary: Partial Disability. IRMI defines partial disability as a disability that is not total.","verdict":"confirmed","source":"IRMI Glossary: Partial Disability https://www.irmi.com/term/insurance-definitions/partial-disability"},{"topic":"Disability Income and Related Insurance","q":"Waiver of premium is best described as the insurer's relinquishment of its right to:","choices":["Deny a claim","Collect premium from the insured","Cancel the policy","Adjust the benefit amount"],"answer":1,"explain":"Source: IRMI Glossary: Waiver of Premium. Waiver of premium is the known relinquishment by an insurer of the right to collect premium from an insured.","verdict":"corrected","source":"IRMI Glossary: Waiver of Premium https://www.irmi.com/term/insurance-definitions/waiver-of-premium"},{"topic":"Disability Income and Related Insurance","q":"An employee pays all premiums on a disability policy with after-tax income. Benefits received are generally:","choices":["Fully taxable","Excluded from gross income","Taxable above 50 percent","Taxable only after one year"],"answer":1,"explain":"Source: Cornell LII, 26 U.S.C. 104. IRC 104(a)(3) excludes accident and health benefits not attributable to untaxed employer contributions.","verdict":"confirmed","source":"Cornell LII, 26 U.S.C. 104 https://www.law.cornell.edu/uscode/text/26/104"},{"topic":"Disability Income and Related Insurance","q":"Under IRC 105(a), disability benefits are included in gross income to the extent they are:","choices":["Paid by the insured personally","Paid after the elimination period","Attributable to employer contributions","Paid for an accidental injury"],"answer":2,"explain":"Source: Cornell LII, 26 U.S.C. 105. Section 105(a) includes amounts attributable to employer contributions or paid by the employer.","verdict":"confirmed","source":"Cornell LII, 26 U.S.C. 105 https://www.law.cornell.edu/uscode/text/26/105"},{"topic":"Disability Income and Related Insurance","q":"Disability income insurance replaces income lost when the insured cannot work because of:","choices":["Injury only","Death only","Sickness or injury","Medical bills only"],"answer":2,"explain":"Source: IRMI Glossary: Disability Income Insurance. Disability income replaces income lost when the insured cannot work because of sickness or injury.","verdict":"corrected","source":"IRMI Glossary: Disability Income Insurance https://www.irmi.com/term/insurance-definitions/disability-income-insurance"}],"scenarios":[{"situation":"A dentist loses the use of her hands and can no longer practice dentistry. She can still teach dental students.","q":"Does she receive benefits under an own-occupation policy and under an any-occupation policy?","choices":["Both policies pay","Neither policy pays","Own-occupation pays; any-occupation does not","Any-occupation pays; own-occupation does not"],"answer":2,"explain":"Source: IRMI Glossary. Own-occupation means unable to do your own job; any-occupation means unable to do any gainful job. She can still teach.","topic":"Own vs any occupation","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/total-disability"},{"situation":"Paul becomes disabled. His disability income policy has a 90-day elimination period.","q":"When can benefits become payable?","choices":["Only after the 90-day waiting period runs","On the first day of disability","After 30 days","Only after 1 year"],"answer":0,"explain":"Source: IRMI Glossary. The elimination period is a waiting period that must run before disability benefits are payable.","topic":"Waiting periods","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/elimination-period"},{"situation":"A business owner wants to keep the business running and cover rent and employee salaries while he is disabled.","q":"Which coverage fits?","choices":["Disability buy-sell","Key person disability","Business overhead expense","Reducing term"],"answer":2,"explain":"Source: IRMI Glossary. Overhead expense insurance pays business costs like rent, utilities and employee salaries during the owner's disability, not the owner's own pay.","topic":"Business uses","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/overhead-expense-insurance"}],"pairs":[{"term":"Own-occupation","match":"Pays if you cannot do your own job","source":"IRMI Glossary - Total Disability https://www.irmi.com/term/insurance-definitions/total-disability"},{"term":"Any-occupation","match":"Pays only if you cannot do any gainful occupation","source":"IRMI Glossary - Total Disability https://www.irmi.com/term/insurance-definitions/total-disability"},{"term":"Probationary period","match":"One-time wait after issue, sickness only","source":"IRMI Glossary - Probationary Period https://www.irmi.com/term/insurance-definitions/probationary-period"},{"term":"Elimination period","match":"Waiting period before disability benefits are payable","source":"IRMI Glossary - Elimination Period https://www.irmi.com/term/insurance-definitions/elimination-period"},{"term":"Flat partial benefit","match":"Set percentage, often 50%, of the total disability benefit","source":"IRMI Glossary - Partial Disability https://www.irmi.com/term/insurance-definitions/partial-disability"}]},"ch16":{"title":"Chapter 16 - Private Insurance Plans for Seniors","flashcards":[{"front":"Medigap plan letters","back":"Standardized plans: A, B, C, D, F, G, K, L, M, N (ten plans). C and F are closed to people newly eligible for Medicare on or after Jan 1, 2020.","topic":"Medigap","memory":"","source":"Medicare.gov compare Medigap plan benefits https://www.medicare.gov/health-drug-plans/medigap/basics/compare-plan-benefits"},{"front":"Medigap open enrollment","back":"6 months, starting when the person first enrolls in Part B at 65 or older. Guaranteed issue: no refusal and no rate-up.","topic":"Medigap","memory":"","source":"42 U.S.C. 1395ss(s)(2)(A) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"front":"Five Medigap minimum standards","back":"Cover Parts A and B; adjust with Medicare law; preexisting exclusion max 6 months; cover Part B 20% coinsurance; 30-day free look.","topic":"Medigap","memory":"","source":"42 U.S.C. 1395ss(c)(4), (s)(2)(B), (p)(2)(B) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"front":"Foreign travel emergency in Medigap","back":"Optional benefit in certain plans, not standard in every plan and not in Plan A. Check the plan's benefit chart.","topic":"Medigap","memory":"","source":"Medicare.gov compare Medigap plan benefits https://www.medicare.gov/health-drug-plans/medigap/basics/compare-plan-benefits"},{"front":"Plan F vs Plan G","back":"Plan F covers the Part B deductible, so it cannot be sold to people newly eligible for Medicare on or after Jan 1, 2020 (MACRA). Plan G does not cover it and remains available.","topic":"Medigap","memory":"","source":"42 U.S.C. 1395ss(z) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"front":"Plan K vs Plan L","back":"K covers 50% of most cost sharing; L covers 75%. Both pay 100% after the annual out-of-pocket limit.","topic":"Medigap","memory":"K = 50, L = 75.","source":"Medicare.gov compare Medigap plan benefits https://www.medicare.gov/health-drug-plans/medigap/basics/compare-plan-benefits"},{"front":"Medicare Select","back":"Medigap plan that uses a network of hospitals and doctors for full benefits. Emergencies are covered outside the network. Lower premiums.","topic":"Medicare Select","memory":"","source":"42 U.S.C. 1395ss(t) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"front":"Part D late enrollment penalty","back":"1% of the base beneficiary premium for each full uncovered month without creditable coverage or Part D (42 CFR 423.286(d)(3)); lasts as long as the person has Part D.","topic":"Part D","memory":"","source":"42 CFR 423.286(d)(3) https://www.law.cornell.edu/cfr/text/42/423.286"},{"front":"LTC benefit trigger","back":"Unable to perform at least 2 of 6 ADLs for at least 90 days, or severe cognitive impairment.","topic":"Long-term care","memory":"2 of 6, 90 days.","source":"26 U.S.C. 7702B(c)(2) https://www.law.cornell.edu/uscode/text/26/7702B"},{"front":"The six ADLs","back":"Bathing, dressing, toileting, transferring, continence, eating.","topic":"Long-term care","memory":"","source":"26 U.S.C. 7702B(c)(2)(B) https://www.law.cornell.edu/uscode/text/26/7702B"},{"front":"Calendar days vs service days (LTC elimination)","back":"Calendar: every consecutive day counts, faster access. Service days: only days care is received count, slower access.","topic":"Long-term care","memory":"","source":"ACL Long-Term Care Glossary https://acl.gov/ltc/glossary"},{"front":"LTC partnership program","back":"State-run, federally supported. Gives dollar-for-dollar asset protection from the Medicaid spend-down, equal to benefits paid.","topic":"Long-term care","memory":"","source":"42 U.S.C. 1396p(b)(1)(C) https://www.law.cornell.edu/uscode/text/42/1396p"}],"questions":[{"q":"What is the main purpose of a Medicare supplement (Medigap) policy?","choices":["Replace Medicare Parts A and B","Cover prescription drugs only","Pay for long-term custodial care","Fill gaps such as deductibles and coinsurance in Parts A and B"],"answer":3,"explain":"Medigap adds to Original Medicare. Replacing Parts A and B describes Medicare Advantage (Part C). Source: Medicare.gov Medigap.","topic":"Medigap","source":"Medicare.gov Medigap https://www.medicare.gov/health-drug-plans/medigap"},{"q":"Which Part C plan type is run by health care providers, who take on the financial risk?","choices":["HMO","PSO","PPO","PFFS"],"answer":1,"explain":"A provider-sponsored organization (PSO) is run by providers rather than insurers. PFFS lets members see any approved provider that accepts the plan's terms. Source: 42 CFR 422.4 (Cornell LII).","topic":"Part C","source":"42 CFR 422.4 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/422.4"},{"q":"Under LTC elimination periods, calendar days differ from service days because calendar days:","choices":["Count only days care is received","Count every consecutive day, so benefits start sooner","Exclude weekends","Apply only to home care"],"answer":1,"explain":"Calendar days count every day, giving faster access. Service days count only days when care is actually received. Source: ACL Long-Term Care Glossary.","topic":"Long-term care","source":"ACL Long-Term Care Glossary https://acl.gov/ltc/glossary"},{"q":"Medicare Select differs from standard Medigap because it:","choices":["Allows any provider with no limits","Costs more","Requires network providers for full benefits and has lower premiums","Replaces Part B"],"answer":2,"explain":"Medicare Select works like managed care, with lower premiums in exchange for using network providers. Emergencies are covered outside the network. Source: 42 U.S.C. 1395ss(t).","topic":"Medicare Select","source":"42 U.S.C. 1395ss(t) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"q":"How long is the Medigap open enrollment (guaranteed issue) period?","choices":["30 days","90 days","1 year","6 months"],"answer":3,"explain":"It lasts 6 months from the start of Part B at 65 or older. The 30-day figure is the Medigap free-look period. Source: 42 U.S.C. 1395ss(s)(2)(A) and (c)(4).","topic":"Medigap","source":"42 U.S.C. 1395ss(s)(2)(A) and (c)(4) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"q":"What share of most cost sharing does Medigap Plan L cover?","choices":["50%","25%","75%","100%"],"answer":2,"explain":"Plan L covers 75% (insured pays 25%). Plan K covers 50%. Source: Medicare.gov compare Medigap plan benefits.","topic":"Medigap","source":"Medicare.gov compare Medigap plan benefits https://www.medicare.gov/health-drug-plans/medigap/basics/compare-plan-benefits"},{"q":"What is the usual LTC benefit trigger?","choices":["Unable to do 1 of 6 ADLs for 30 days","Unable to do 2 of 6 ADLs for at least 90 days","Unable to do 3 of 6 ADLs for 180 days","Unable to work for 2 years"],"answer":1,"explain":"The trigger is at least 2 of 6 ADLs for at least 90 days, or severe cognitive impairment. Source: 26 U.S.C. 7702B(c)(2)(A).","topic":"Long-term care","source":"26 U.S.C. 7702B(c)(2)(A) https://www.law.cornell.edu/uscode/text/26/7702B"},{"q":"A Medigap agent's first-year commission cannot exceed what percent of the subsequent-year commission?","choices":["100%","150%","300%","200%"],"answer":3,"explain":"First-year commission may not exceed 200% of the renewal commission. Source: LAC 37:XIII.555.","topic":"Medigap","source":"LAC 37:XIII.555 https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-555"},{"q":"Which is NOT a core benefit included in every Medigap plan?","choices":["Foreign travel emergency coverage","First 3 pints of blood","365 extra hospital days","Hospice coinsurance"],"answer":0,"explain":"Foreign travel emergency is optional in certain plans (not Plan A). The other three are core benefits in every plan. Source: Medicare.gov compare Medigap plan benefits.","topic":"Medigap","source":"Medicare.gov compare Medigap plan benefits https://www.medicare.gov/health-drug-plans/medigap/basics/compare-plan-benefits"},{"q":"Which is NOT one of the five Medigap minimum standards?","choices":["30-day free look","Cover the Part B 20% coinsurance","Preexisting condition exclusion of up to 12 months","Benefits adjust with Medicare law changes"],"answer":2,"explain":"The preexisting condition exclusion may not exceed 6 months, not 12. Source: 42 U.S.C. 1395ss(s)(2)(B).","topic":"Medigap","source":"42 U.S.C. 1395ss(s)(2)(B) https://www.law.cornell.edu/uscode/text/42/1395ss"}],"scenarios":[{"situation":"Ellen turns 65 and enrolls in Medicare Part B. She applies for a Medigap policy within her first 6 months. She has a heart condition.","q":"Can the insurer refuse her or rate her up?","choices":["Yes, because of the heart condition","Yes, but only with a 12-month wait","No, her Medigap open enrollment period protects her","Only if she is under 70"],"answer":2,"explain":"Source: Medicare.gov. During the 6-month Medigap open enrollment period, insurers can't refuse her or charge more for health problems.","topic":"Medigap","source":"Medicare.gov: Get ready to buy (Medigap) https://www.medicare.gov/health-drug-plans/medigap/ready-to-buy"},{"situation":"Frank can no longer bathe or dress himself and needs hands-on help. His LTC policy requires inability to do 2 of 6 ADLs for 90 days, and the need lasts 90 days.","q":"Does he meet the benefit trigger?","choices":["No, he needs 3 ADLs","No, the period must be 180 days","Only if he has cognitive impairment","Yes, 2 ADLs for at least 90 days"],"answer":3,"explain":"Source: 26 U.S.C. 7702B(c)(2). Chronically ill means unable to do at least 2 ADLs for at least 90 days. Bathing and dressing are ADLs.","topic":"Long-term care","source":"26 U.S.C. 7702B(c)(2) https://www.law.cornell.edu/uscode/text/26/7702B"}],"pairs":[{"term":"Medigap","match":"Private add-on to Original Medicare Parts A and B","source":"Medicare.gov - Parts of Medicare https://www.medicare.gov/basics/get-started-with-medicare/medicare-basics/parts-of-medicare"},{"term":"Medicare Advantage (Part C)","match":"Private plan alternative to Original Medicare, bundling Parts A and B","source":"Medicare.gov - Parts of Medicare https://www.medicare.gov/basics/get-started-with-medicare/medicare-basics/parts-of-medicare"},{"term":"Plan F","match":"Not sold to people newly eligible for Medicare on or after Jan 1, 2020","source":"42 U.S.C. 1395ss(z) (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395ss"},{"term":"PSO","match":"Part C plan run by health care providers","source":"42 CFR 422.350 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/422.350"},{"term":"Partnership program","match":"Dollar-for-dollar protection from Medicaid spend-down","source":"42 U.S.C. 1396p (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1396p"}]},"ch17":{"title":"Chapter 17 - Health Policy Provisions","flashcards":[{"front":"How many required provisions in La. R.S. 22:975(A)?","back":"14 required provisions in subsection A (entire contract, reinstatement, notice of claim, claim forms, proof of loss, etc.). Optional provisions are in subsection B.","topic":"NAIC model law","memory":"","source":"La. R.S. 22:975 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Louisiana grace period, individual health and accident policy","back":"30 days from the date the premium was due (La. R.S. 22:977).","topic":"Grace period","memory":"LA = 30.","source":"La. R.S. 22:977 https://www.legis.la.gov/legis/Law.aspx?d=507814"},{"front":"Entire contract provision","back":"Contract = policy + application + endorsements + riders. Agents cannot change it; only an authorized executive officer can.","topic":"Mandatory provisions","memory":"","source":"La. R.S. 22:975(A)(1) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Notice of claim deadline","back":"Within 20 days of the loss, or as soon as reasonably possible.","topic":"Claims","memory":"","source":"La. R.S. 22:975(A)(3) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Claim forms deadline","back":"The insurer must provide claim forms within 15 days of receiving notice of claim.","topic":"Claims","memory":"","source":"La. R.S. 22:975(A)(4) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Proof of loss deadline","back":"Within 90 days after the date of loss (or after the period of disability ends for loss-of-time claims). Late proof is excused if not reasonably possible to file on time, but in no event later than 1 year after proof was otherwise required.","topic":"Claims","memory":"","source":"La. R.S. 22:975(A)(5) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Legal actions provision","back":"No suit until 60 days after proof of loss is filed; no suit after 1 year from the time proof of loss is required (La. R.S. 22:975).","topic":"Mandatory provisions","memory":"","source":"La. R.S. 22:975(A)(11) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Reinstatement coverage start","back":"After the insurer accepts a defaulted premium, the policy is reinstated: accidental injury is covered immediately; sickness is covered only if it begins more than 10 days after acceptance.","topic":"Reinstatement","memory":"","source":"La. R.S. 22:975(A)(2) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"Free look period (long-term care)","back":"Long-term care applicants may return the policy within 30 days of delivery for a premium refund, for any reason (La. R.S. 22:1186(F)).","topic":"Free look","memory":"","source":"La. R.S. 22:1186(F) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507978"},{"front":"Change of occupation (optional provision)","back":"More hazardous job: maximum benefit reduced. Less hazardous job: premium reduced.","topic":"Optional provisions","memory":"MORE hazard = LESS benefit.","source":"La. R.S. 22:975(B)(1) and (A)(9) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"front":"ACA dependent coverage age","back":"Dependent coverage until age 26. It is a dependent coverage requirement, not a conversion privilege.","topic":"Dependent coverage","memory":"","source":"42 U.S.C. 300gg-14 https://www.law.cornell.edu/uscode/text/42/300gg-14"}],"questions":[{"q":"Which provision states that the contract consists of the policy, application, endorsements, and riders?","choices":["Legal actions","Entire contract","Proof of loss","Insuring clause"],"answer":1,"explain":"The entire contract provision limits the contract to those documents. Outside statements do not count. Source: La. R.S. 22:975(A)(1).","topic":"Mandatory provisions","source":"La. R.S. 22:975(A)(1) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"What does the change of occupation optional provision do if the insured moves to a more hazardous job?","choices":["Raises the premium","Cancels the policy","Increases the benefit","Reduces the maximum benefit"],"answer":3,"explain":"A more hazardous job reduces the benefit. A less hazardous job reduces the premium. Source: La. R.S. 22:975(B)(1).","topic":"Optional provisions","source":"La. R.S. 22:975(B)(1) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"Which provision says the insurer pays only a proportionate amount if disability benefits would exceed the insured's earnings?","choices":["Relation of earnings","Misstatement of age","Unpaid premiums","Conformity with state statutes"],"answer":0,"explain":"Relation of earnings (average earnings clause) prevents over-insurance. Source: La. R.S. 22:975(B)(5).","topic":"Optional provisions","source":"La. R.S. 22:975(B)(5) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"Under the right of assignment provision, benefits can be:","choices":["Paid only to the insured","Paid only after the insured is reimbursed","Paid directly to the health provider","Paid only to the estate"],"answer":2,"explain":"Assignment lets benefits go directly to the provider so the insured does not pay first and wait for reimbursement. Source: La. R.S. 22:975(A)(7).","topic":"Other provisions","source":"La. R.S. 22:975(A)(7) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"Under Louisiana law (R.S. 22:977), what grace period must an individual health and accident policy provide?","choices":["7 days","10 days","30 days","45 days"],"answer":2,"explain":"Source: La. R.S. 22:977. Louisiana requires a grace period of thirty days from the date the premium was due.","topic":"Grace period","source":"La. R.S. 22:977 https://www.legis.la.gov/legis/Law.aspx?d=507814"},{"q":"How many days after receiving notice must the insurer provide claim forms?","choices":["10","20","30","15"],"answer":3,"explain":"The insurer has 15 days. Notice of claim itself is due within 20 days of the loss. Source: La. R.S. 22:975(A)(4).","topic":"Claims","source":"La. R.S. 22:975(A)(4) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"How long must a claimant wait after proof of loss before filing suit?","choices":["At least 60 days","At least 3 years","At least 90 days","No waiting period"],"answer":0,"explain":"Source: La. R.S. 22:975(A)(11). No suit may be brought before sixty days after proof of loss. Proof of loss itself is due within ninety days (A(5)); the three-year period is the time limit on certain defenses (A(13)).","topic":"Mandatory provisions","source":"La. R.S. 22:975(A)(11) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"Which of these is an OPTIONAL provision, not a required one, under La. R.S. 22:975?","choices":["Reinstatement","Notice of claim","Physical examination and autopsy","Relation of earnings"],"answer":3,"explain":"Source: La. R.S. 22:975. Relation of earnings is in subsection B (optional). Reinstatement, notice of claim, and physical examination are in subsection A (required).","topic":"Mandatory provisions","source":"La. R.S. 22:975 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"Under La. R.S. 22:975(A)(2), a reinstated policy covers sickness that begins:","choices":["Immediately on reinstatement","More than 10 days after the insurer accepts the premium","More than 30 days after acceptance","More than 45 days after acceptance"],"answer":1,"explain":"Source: La. R.S. 22:975(A)(2). The reinstated policy covers loss due to sickness beginning more than ten days after acceptance of the defaulted premium.","topic":"Reinstatement","source":"La. R.S. 22:975(A)(2) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"}],"scenarios":[{"situation":"Ben's quarterly premium is due March 1 and he does not pay. He dies on March 20.","q":"What happens to the death benefit?","choices":["The policy lapsed, so nothing is paid","The full face amount is paid","The benefit is paid minus the unpaid premium","Only premiums paid are refunded"],"answer":2,"explain":"Source: La. R.S. 22:931(A)(1). Louisiana life grace is 30 days or one month, so March 20 is inside it. The unpaid premium is deducted from the benefit.","topic":"Grace period","source":"La. R.S. 22:931(A)(1) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"situation":"Carl's individual health policy lapsed for nonpayment. Later the insurer accepts his late premium.","q":"Under Louisiana law, what happens?","choices":["The policy is reinstated; it covers later accidents, and sickness that begins more than 10 days later","Nothing until the insurer approves a new application","Reinstatement after 45 days, with all coverage at once","Reinstated, but only sickness is covered for the first 10 days"],"answer":0,"explain":"Source: La. R.S. 22:975(A)(2). Accepting the late premium reinstates the policy. It covers accidents after that, and sickness only if it starts more than 10 days later.","topic":"Reinstatement","source":"La. R.S. 22:975(A)(2) https://legis.la.gov/Legis/Law.aspx?d=507812"}],"pairs":[{"term":"Notice of claim","match":"Due within 20 days after the accident or start of sickness","source":"La. R.S. 22:975(A)(3) https://legis.la.gov/Legis/Law.aspx?d=507812"},{"term":"Proof of loss","match":"Due within 90 days after the loss (disability: after liability period)","source":"La. R.S. 22:975(A)(5) https://legis.la.gov/Legis/Law.aspx?d=507812"},{"term":"Absolute assignment","match":"Transfer of title; assignee is treated as the policy owner","source":"La. R.S. 22:876 https://legis.la.gov/Legis/Law.aspx?d=507757"},{"term":"Collateral assignment","match":"Pledge of the policy as security; assignee is a pledgee","source":"La. R.S. 22:876 https://legis.la.gov/Legis/Law.aspx?d=507757"},{"term":"Irrevocable beneficiary","match":"Cannot be changed without that beneficiary's consent","source":"IRMI Glossary - Irrevocable Beneficiary https://www.irmi.com/term/insurance-definitions/irrevocable-beneficiary"}]},"ch18":{"title":"Chapter 18 - Underwriting and Policy Issue (Health)","flashcards":[{"front":"Primary goal of underwriting","back":"Evaluate and select risks to protect against adverse selection (more high-risk people seeking coverage).","topic":"Underwriting","memory":"","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms?id=37"},{"front":"Representation vs warranty","back":"Representation: true to the best of knowledge, matters only if material. Warranty: must be completely true; breach can void the policy.","topic":"Representations","memory":"Representation = best of my knowledge. Warranty = guarantee every word.","source":"La. R.S. 22:860 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507741"},{"front":"Misrepresentation vs fraud","back":"In Louisiana, a misrepresentation in an application defeats coverage only if made with intent to deceive or if it materially affected acceptance of the risk (La. R.S. 22:860).","topic":"Representations","memory":"","source":"La. R.S. 22:860 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507741"},{"front":"Medical Information Bureau (MIB)","back":"Services exclusively for member insurers. Information is shared in a coded format and used during underwriting; it is not used for marketing.","topic":"MIB","memory":"","source":"MIB Facts About MIB https://mib.com/facts_about_mib.html"},{"front":"Insurable interest (La. R.S. 22:901)","back":"Closely related persons: substantial interest from love and affection. Others: lawful and substantial economic interest in the insured's life, health or bodily safety.","topic":"Insurable interest","memory":"","source":"La. R.S. 22:901(C) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507771"},{"front":"Earned vs unearned premium","back":"Unearned premium is the portion of the premium not yet earned by the insurer (coverage time remaining); it may be refunded if the policy is canceled. Earned premium is the portion already earned.","topic":"Premiums","memory":"","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/unearned-premium"}],"questions":[{"q":"Under Louisiana law, statements made by the insured in a written life, annuity, or health and accident application are, absent fraud, deemed:","choices":["Warranties","Representations","Conditions precedent","Counter-offers"],"answer":1,"explain":"Source: La. R.S. 22:611 (former 22:860). In the absence of fraud, application statements are deemed representations and not warranties.","topic":"Representations","source":"La. R.S. 22:611 (former 22:860) https://legis.la.gov/Legis/Law.aspx?d=507741"},{"q":"Under Louisiana law, an insurer may not issue a life policy that takes effect as of a date more than how long before the application was made (where the premium is reduced by the earlier date)?","choices":["30 days","3 months","1 year","6 months"],"answer":3,"explain":"Source: La. R.S. 22:904. Life policies may not be dated more than six months before the application was made if the premium is thereby reduced.","topic":"Key dates","source":"La. R.S. 22:904 https://legis.la.gov/legis/Law.aspx?d=507774"},{"q":"Under Louisiana law, how many days from receipt does an insured have to examine a life insurance policy (free look)?","choices":["10 days","20 days","31 days","60 days"],"answer":0,"explain":"Source: Louisiana R.S. 22:931(A)(10)(a). The policy must tell the insured that ten days are allowed from receipt to examine it, with return of advanced premium.","topic":"Policy delivery","source":"Louisiana R.S. 22:931 https://www.legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"When the policy is replaced, who must sign the notice of replacement?","choices":["Only the applicant","Only the agent","The insurer's underwriter","Both the agent and the applicant"],"answer":3,"explain":"Both the agent and the applicant sign the notice of replacement. Source: Louisiana Administrative Code 37:XIII.8907 and 8909 (Cornell LII).","topic":"Replacement","source":"Louisiana Administrative Code 37:XIII.8907 and 8909 (Cornell LII) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-8909"},{"q":"Which is NOT true of the MIB?","choices":["Its code services are available only to member companies","It is used by member insurers during underwriting","It can be used for any marketing purpose","It shares applicant information in a coded format"],"answer":2,"explain":"Source: MIB Consumer Privacy Policy and MIB Facts page. MIB services are exclusively for member companies, information is kept in coded format, and the permitted uses (underwriting, fraud detection, compliance) do not include marketing.","topic":"MIB","source":"MIB Consumer Privacy Policy https://www.mib.com/privacy_policy.html"},{"q":"Under La. R.S. 22:901(C), what interest must a person who is NOT closely related by blood or law to the insured have?","choices":["A substantial interest based on love and affection","A lawful and substantial economic interest in the insured's life, health or bodily safety","No interest is required","Only friendship with the insured"],"answer":1,"explain":"Source: La. R.S. 22:901(C). Closely related individuals may rely on a substantial interest engendered by love and affection; other persons need a lawful and substantial economic interest.","topic":"Insurable interest","source":"La. R.S. 22:901(C) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507771"}],"scenarios":[{"situation":"Nina's application says she was never treated for asthma. She was treated two years ago and forgot. The insurer learns this after a claim.","q":"Under Louisiana law, how is her statement treated?","choices":["A warranty that automatically voids the policy","A representation; it bars the claim only if made to deceive or if it materially affected the risk","Fraud, because it was untrue","Irrelevant to the contract"],"answer":1,"explain":"Source: La. R.S. 22:860(B). Application statements are representations, not warranties. A false one bars recovery only if made to deceive or if it materially affected the risk.","topic":"Representations","source":"La. R.S. 22:860(B) https://legis.la.gov/Legis/Law.aspx?d=507741"},{"situation":"A 42-year-old with a history of heart bypass surgery applies. The insurer offers coverage at a higher premium.","q":"What type of offer is this?","choices":["A preferred offer","A binding receipt","A trial application","A rated (substandard) policy offer"],"answer":3,"explain":"Source: IRMI Glossary. A rated policy is issued at a higher-than-standard premium for a substandard risk.","topic":"Counter-offers","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/rated-policy"}],"pairs":[{"term":"Representation","match":"True to best of knowledge; matters if material","source":"IRMI Glossary - Representation https://www.irmi.com/term/insurance-definitions/representation"},{"term":"Warranty","match":"Must be completely true; breach can void policy","source":"IRMI Glossary - Warranty https://www.irmi.com/term/insurance-definitions/warranty"},{"term":"Conditional receipt","match":"Coverage from receipt date if the insurer accepts the risk","source":"IRMI Glossary - Conditional Binding Receipt https://www.irmi.com/term/insurance-definitions/conditional-binding-receipt"},{"term":"Experience rating","match":"Premium based on the insured group's own loss experience","source":"IRMI Glossary - Experience Rating https://www.irmi.com/term/insurance-definitions/experience-rating"},{"term":"Community rating","match":"Everyone in an area pays the same price","source":"HealthCare.gov Glossary - Community rating https://www.healthcare.gov/glossary/community-rating/"}]},"ch19":{"title":"Bonus - Social Insurance Study Tool Slides","flashcards":[{"front":"Who is eligible for Medicare?","back":"People 65 or older, people under 65 with qualifying disabilities, and people of any age with ESRD or ALS.","topic":"Medicare","memory":"","source":"42 U.S.C. 426 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/426"},{"front":"Medicare Part A: coverage and cost","back":"Inpatient hospital, SNF, hospice, some home health. Usually free if you or your spouse paid Medicare taxes 10+ years.","topic":"Medicare Part A","memory":"","source":"Medicare.gov Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"front":"Part A coinsurance trigger","back":"Coinsurance applies after 60 days in a hospital or 20 days in a skilled nursing facility.","topic":"Medicare Part A","memory":"","source":"Medicare.gov Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"front":"Medicare Part B basics","back":"Optional medical coverage: doctor, outpatient, preventive, equipment. Monthly premium (income-adjusted), annual deductible, then 20% coinsurance.","topic":"Medicare Part B","memory":"","source":"Medicare.gov Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"front":"Part B late enrollment penalty","back":"10% increase for each 12-month delay in enrolling.","topic":"Medicare Part B","memory":"","source":"Medicare.gov avoid penalties https://www.medicare.gov/basics/costs/medicare-costs/avoid-penalties"},{"front":"Medicare Part C (Advantage)","back":"Offered by private insurers as an alternative to Original Medicare. Must be enrolled in A and B. Often includes Part D and extras.","topic":"Medicare Part C","memory":"All-in-one.","source":"42 U.S.C. 1395w-22 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395w-22"},{"front":"What does Part C not cover?","back":"It must cover A and B except hospice; Original Medicare still pays hospice.","topic":"Medicare Part C","memory":"","source":"42 U.S.C. 1395w-22 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395w-22"},{"front":"Medicare Part D","back":"Prescription drugs through private plans. Must be enrolled in A or B. Annual out-of-pocket cap; the donut hole was eliminated January 1, 2025.","topic":"Medicare Part D","memory":"","source":"42 U.S.C. 1395w-102 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395w-102"},{"front":"Medicare enrollment window","back":"7 months: 3 before the 65th birthday month, the birthday month, and 3 after.","topic":"Medicare","memory":"","source":"Medicare.gov when coverage starts https://www.medicare.gov/basics/get-started-with-medicare/sign-up/when-does-medicare-coverage-start"},{"front":"Medicaid in one line","back":"Joint federal-state program for low-income people (children, pregnant women, elderly, disabled). States administer; rules vary by state.","topic":"Medicaid","memory":"Medicaid = Aid for the poor.","source":"42 U.S.C. 1396-1 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1396-1"},{"front":"Medicaid mandatory vs optional benefits","back":"Mandatory: inpatient/outpatient hospital, physician, lab and X-ray, nursing facility, home health, family planning, EPSDT, nurse midwife. Optional: prescription drugs, dental, eyeglasses, physical therapy. Source: Medicaid.gov.","topic":"Medicaid","memory":"","source":"Medicaid.gov Mandatory & Optional Medicaid Benefits https://www.medicaid.gov/medicaid/benefits/mandatory-optional-medicaid-benefits"},{"front":"Medicaid and long-term care","back":"Medicare does not cover long-term care; Medicaid may cover it if you meet state eligibility rules, and nursing facility services are a mandatory Medicaid benefit. Source: Medicare.gov; Medicaid.gov.","topic":"Medicaid","memory":"","source":"Medicare.gov Long-term care; Medicaid.gov mandatory benefits https://www.medicare.gov/coverage/long-term-care"},{"front":"Social Security retirement eligibility","back":"40 work credits (about 10 years). Earliest age 62 (reduced); benefit increases for delay up to age 70.","topic":"Social Security","memory":"","source":"42 U.S.C. 414(a)(2); 42 U.S.C. 402(a); 20 CFR 404.313 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/414"},{"front":"SSDI waiting period and Medicare","back":"5-month waiting period (waived for ALS). Medicare begins 24 months after benefits start, except ALS.","topic":"Social Security","memory":"","source":"42 U.S.C. 423(c)(2), 423(a)(1) and 426(b), (h) (Cornell LII) https://www.law.cornell.edu/uscode/text/42/423"},{"front":"SSDI vs SSI","back":"SSDI requires insured status from work credits (42 USC 423). SSI is a needs-based program for the aged, blind, or disabled and does not depend on work history. Source: Cornell LII.","topic":"Social Security","memory":"SSDI = work history. SSI = need.","source":"Cornell LII Wex: SSI; 42 U.S.C. 423 https://www.law.cornell.edu/wex/supplemental_security_income_(ssi)"}],"questions":[{"q":"Which Medicare part covers prescription drugs through private plans?","choices":["Part A","Part B","Part C only","Part D"],"answer":3,"explain":"Part D is the prescription drug part. Part C can include drug coverage but is the all-in-one Advantage option. Source: Medicare.gov Part D.","topic":"Medicare","source":"Medicare.gov Part D https://www.medicare.gov/health-drug-plans/part-d/basics"},{"q":"Which Medicare part is usually free if you or your spouse paid Medicare taxes for 10 or more years?","choices":["Part A","Part B","Part C","Part D"],"answer":0,"explain":"Part A (hospital) is usually premium-free. Part B carries a monthly premium. Source: Medicare.gov Medicare costs.","topic":"Medicare Part A","source":"Medicare.gov Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"q":"What does Part B cover?","choices":["Inpatient hospital stays only","Doctor services, outpatient care, preventive services, and equipment","Private insurer all-in-one plans","Long-term nursing home care"],"answer":1,"explain":"Part B is medical insurance. Inpatient hospital is Part A, and long-term custodial nursing home care is paid by Medicaid. Source: 42 U.S.C. 1395k (Cornell LII).","topic":"Medicare Part B","source":"42 U.S.C. 1395k (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395k"},{"q":"Which program is the primary payer of long-term nursing home care?","choices":["Medicare Part A","Social Security","Medicaid","Part D"],"answer":2,"explain":"Medicaid pays for long-term nursing home and custodial care. Medicare does not cover custodial care. Source: Medicare.gov long-term care.","topic":"Medicaid","source":"Medicare.gov long-term care https://www.medicare.gov/coverage/long-term-care"},{"q":"What coinsurance applies under Part B after the annual deductible?","choices":["10%","20%","50%","None"],"answer":1,"explain":"Part B pays after the deductible with 20% coinsurance owed by the beneficiary. Source: Medicare.gov Medicare costs.","topic":"Medicare Part B","source":"Medicare.gov Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"q":"How many work credits are needed for retirement benefits and to be fully insured?","choices":["4","20","40","35"],"answer":2,"explain":"40 credits (about 10 years; most earn 4 per year). 35 is the number of highest-earning years used for AIME. Source: 42 U.S.C. 414 (Cornell LII).","topic":"Social Security","source":"42 U.S.C. 414 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/414"},{"q":"How long after SSDI benefits start does Medicare eligibility begin (except ALS)?","choices":["5 months","12 months","36 months","24 months"],"answer":3,"explain":"Medicare starts 24 months after disability benefits begin. The 5-month figure is the SSDI waiting period. Source: 42 U.S.C. 426 (Cornell LII).","topic":"Social Security","source":"42 U.S.C. 426 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/426"},{"q":"The Medicare enrollment window around the 65th birthday is:","choices":["7 months","3 months","6 months","12 months"],"answer":0,"explain":"It is 7 months: 3 before the birthday month, the month itself, and 3 after. Source: Medicare.gov when coverage starts.","topic":"Medicare","source":"Medicare.gov when coverage starts https://www.medicare.gov/basics/get-started-with-medicare/sign-up/when-does-medicare-coverage-start"},{"q":"Which is NOT required of a Part C (Medicare Advantage) plan?","choices":["Cover everything in Parts A and B","Cover hospice care","Be offered by a private insurer","Require enrollment in Parts A and B"],"answer":1,"explain":"Part C covers everything in A and B except hospice, which Original Medicare still pays. Source: 42 U.S.C. 1395w-22 (Cornell LII).","topic":"Medicare Part C","source":"42 U.S.C. 1395w-22 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395w-22"},{"q":"Which statement about Medicaid is NOT true?","choices":["States run it under federal rules","Enrollment is year-round","It is mainly for people with low income","It has one nationwide set of eligibility rules"],"answer":3,"explain":"Medicaid eligibility and benefits vary by state within minimum federal guidelines. Source: 42 U.S.C. 1396-1 (Cornell LII).","topic":"Medicaid","source":"42 U.S.C. 1396-1 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1396-1"},{"q":"Which statement about SSI is NOT true?","choices":["It is needs-based","It requires a work history","It is funded by general tax revenues","It is for the elderly, blind, or disabled with limited income"],"answer":1,"explain":"SSI does not depend on work history. SSDI is the work-history benefit. Source: 42 U.S.C. 1382 (Cornell LII).","topic":"Social Security","source":"42 U.S.C. 1382 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1382"},{"q":"Which statement about Part D is NOT true?","choices":["There is an annual out-of-pocket cap","A late penalty can apply without creditable coverage","The donut hole still exists","Enrollment requires Part A or B"],"answer":2,"explain":"The coverage gap (donut hole) was eliminated on January 1, 2025. Source: 42 U.S.C. 1395w-102 (Cornell LII).","topic":"Medicare Part D","source":"42 U.S.C. 1395w-102 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/1395w-102"}],"scenarios":[{"situation":"Ray is turning 65 and has not signed up for Medicare yet. His birthday is in June.","q":"When is his enrollment window?","choices":["Only the month of his birthday","The 3 months after his birthday","March through September","The 12 months after his birthday"],"answer":2,"explain":"Source: Medicare.gov. The Initial Enrollment Period is 7 months: 3 months before the birthday month, that month, and 3 months after.","topic":"Medicare","source":"Medicare.gov: When does Medicare coverage start? https://www.medicare.gov/basics/get-started-with-medicare/sign-up/when-does-medicare-coverage-start"},{"situation":"Dana is a low-income senior who has Medicare and also qualifies for Medicaid. She is also in a nursing home for long-term custodial care.","q":"What does her coverage look like?","choices":["She is a dual eligible; Medicaid may help pay Medicare costs and covers long-term nursing home care","Medicare alone pays for custodial care","She must drop Medicare","She is only eligible for SSI"],"answer":0,"explain":"Source: Medicare.gov. People with both Medicare and full Medicaid are dually eligible. Medicaid covers things Medicare doesn't, like nursing home care.","topic":"Medicaid","source":"Medicare.gov: Medicaid https://www.medicare.gov/basics/costs/help/medicaid"},{"situation":"A worker becomes disabled and starts SSDI. Another person has never worked and has very low income and resources, and is disabled.","q":"Which benefit does each person generally receive?","choices":["Both receive SSDI","Worker gets SSI; non-worker gets SSDI","Worker gets SSDI; non-worker may qualify for SSI","Neither qualifies"],"answer":2,"explain":"Source: SSA. SSDI requires enough work history. SSI is for people with little income and resources who are disabled, blind, or 65+.","topic":"Social Security","source":"SSA: Who can get SSI https://www.ssa.gov/ssi/eligibility"}],"pairs":[{"term":"Medicare Part A","match":"Hospital insurance, usually premium-free","source":"Medicare.gov - Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"term":"Medicare Part B","match":"Medical insurance; you usually pay 20% coinsurance","source":"Medicare.gov - Medicare costs https://www.medicare.gov/basics/costs/medicare-costs"},{"term":"Medicare Part C","match":"Private all-in-one Medicare Advantage plan","source":"Medicare.gov - Parts of Medicare https://www.medicare.gov/basics/get-started-with-medicare/medicare-basics/parts-of-medicare"},{"term":"Medicare Part D","match":"Prescription drug coverage through private plans","source":"Medicare.gov - Parts of Medicare https://www.medicare.gov/basics/get-started-with-medicare/medicare-basics/parts-of-medicare"},{"term":"Medicaid","match":"Joint federal-state aid for low-income people","source":"42 CFR 430.0 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/430.0"},{"term":"SSI","match":"Needs-based benefit, no work history required","source":"SSA - SSI Overview https://www.ssa.gov/ssi/text-over-ussi.htm"}]},"addendum":{"title":"Addendum: Louisiana Regulation and Exam Blueprint","flashcards":[{"front":"Louisiana passing score on the PSI exam?","back":"70% (R.S. 22:1545(A)).","topic":"Exam format","memory":"","source":"La. R.S. 22:1545(A) https://legis.la.gov/Legis/Law.aspx?d=508519"},{"front":"Louisiana life free look period?","back":"10 days from receipt of the policy (R.S. 22:931(A)(10)(a)).","topic":"Life policy rules","memory":"","source":"La. R.S. 22:931 https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"front":"Louisiana incontestability: life versus health?","back":"Life: 2 years (R.S. 22:931(A)(2)). Health: 3 years (R.S. 22:975).","topic":"Policy rules","memory":"Life 2, health 3","source":"La. R.S. 22:931(A)(2) and 22:975 https://codes.findlaw.com/la/revised-statutes/la-rev-stat-tit-22-sect-975/"},{"front":"Louisiana grace period: life versus health?","back":"Life: 30 days or one month, at the insurer's option (R.S. 22:931(A)(1)). Health: 30 days (R.S. 22:977).","topic":"Policy rules","memory":"","source":"La. R.S. 22:931(A)(1) and 22:977 https://codes.findlaw.com/la/revised-statutes/la-rev-stat-tit-22-sect-977/"},{"front":"Louisiana life reinstatement window?","back":"Within 3 years of default (R.S. 22:931(A)(9)).","topic":"Life policy rules","memory":"","source":"La. R.S. 22:931(A)(9) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"front":"Youngest age a minor may contract for life, health, or accident insurance in Louisiana?","back":"15 (R.S. 22:852(B)). Age of majority is 18 (Civil Code art. 29).","topic":"Contract capacity","memory":"","source":"La. R.S. 22:852(B) https://codes.findlaw.com/la/revised-statutes/la-rev-stat-tit-22-sect-852/"},{"front":"Louisiana CE requirement per 2-year renewal?","back":"24 hours, including at least 3 hours of ethics (R.S. 22:1573(C)).","topic":"Licensing and CE","memory":"24 total, 3 ethics","source":"La. R.S. 22:1573(C) https://codes.findlaw.com/la/revised-statutes/la-rev-stat-tit-22-sect-1573/"},{"front":"Louisiana annuity training requirement?","back":"One-time 4-credit course approved by LDI for producers who sell annuities (R.S. 22:1576(B)(1)(a)).","topic":"Licensing and CE","memory":"","source":"La. R.S. 22:1576 https://www.legis.la.gov/Legis/LawPrint.aspx?d=815030"},{"front":"Louisiana guaranty association limits per person?","back":"Death $300,000; cash surrender and withdrawal values $100,000; health $500,000; annuity present value $250,000; $500,000 aggregate (R.S. 22:2083(C) and (D)).","topic":"Guaranty association","memory":"300 / 100 / 500 / 250 / 500 cap","source":"La. R.S. 22:2083 https://codes.findlaw.com/la/revised-statutes/la-rev-stat-tit-22-sect-2083/"},{"front":"What are the federal Do Not Call calling hours for telemarketing?","back":"Telemarketing calls may be made only from 8:00 a.m. to 9:00 p.m. in the consumer's local time.","topic":"Do Not Call","memory":"8 TO 9","source":"16 CFR 310.4(c) https://www.law.cornell.edu/cfr/text/16/310.4"},{"front":"How often must telemarketing call lists be checked against the National Do Not Call Registry?","back":"At least every 31 days.","topic":"Do Not Call","memory":"31 DAYS","source":"16 CFR 310.4(b)(3)(iv) https://www.law.cornell.edu/cfr/text/16/310.4"},{"front":"What is pretexting under the Gramm-Leach-Bliley Act?","back":"Getting a consumer's nonpublic personal information from a financial institution through false or fraudulent statements, forged documents, or impersonation. It is a federal crime with fines and possible imprisonment.","topic":"Privacy (GLBA)","memory":"PRETEXT = FALSE PRETENSE","source":"15 U.S.C. 6821 and 6823 https://www.law.cornell.edu/uscode/text/15/6823"}],"questions":[{"q":"How long is the Louisiana life insurance free look period?","choices":["20 days from application","31 days from issue","30 days from receipt","10 days from receipt"],"answer":3,"explain":"R.S. 22:931(A)(10)(a): 10 days from receipt of the policy. Source: La. R.S. 22:931.","topic":"Life policy rules","source":"La. R.S. 22:931 https://www.legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"What is the Louisiana incontestability period for a health policy?","choices":["1 year","2 years","3 years","5 years"],"answer":2,"explain":"R.S. 22:975: 3 years for health. Life is 2 years (R.S. 22:931(A)(2)). Source: La. R.S. 22:975(A)(13).","topic":"Policy rules","source":"La. R.S. 22:975(A)(13) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507812"},{"q":"Within what time after default may a lapsed Louisiana life policy be reinstated under the statutory provision?","choices":["1 year","3 years","5 years","7 years"],"answer":1,"explain":"R.S. 22:931(A)(9): within 3 years of default. Source: La. R.S. 22:931(A)(9).","topic":"Life policy rules","source":"La. R.S. 22:931(A)(9) https://www.legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"What is the aggregate Louisiana guaranty association limit per individual?","choices":["$300,000","$250,000","$100,000","$500,000"],"answer":3,"explain":"Source: La. R.S. 22:2083(D). The association's aggregate limit is $500,000 for any one individual. $300,000 is only the life death benefit cap in 22:2083(C)(2)(a).","topic":"Guaranty association","source":"La. R.S. 22:2083 https://legis.la.gov/Legis/Law.aspx?d=509204"},{"q":"At what minimum age may a Louisiana minor contract for life, health, or accident insurance?","choices":["18","16","12","15"],"answer":3,"explain":"R.S. 22:852(B): a minor 15 or older may contract. The age of majority is 18 (Civil Code art. 29). Source: La. R.S. 22:852(B).","topic":"Contract capacity","source":"La. R.S. 22:852(B) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507733"},{"q":"Which statement about Louisiana policy rules is NOT correct?","choices":["Life grace period is 30 days or one month","Health grace period is 30 days","Life grace period is 31 days","Life free look is 10 days from receipt"],"answer":2,"explain":"R.S. 22:931(A)(1) sets 30 days or one month. Louisiana does not use a 31-day life grace period. Source: La. R.S. 22:931(A)(1).","topic":"Policy rules","source":"La. R.S. 22:931(A)(1) https://www.legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"Which is NOT a correct Louisiana guaranty association limit?","choices":["Death benefits $300,000","Life cash surrender and withdrawal values $100,000","Health benefits $500,000","Annuity present value $500,000"],"answer":3,"explain":"Source: La. R.S. 22:2083(C)(2) and (D). Annuity present value is capped at $250,000 under (C)(2)(c). The $500,000 figure is the aggregate cap per individual in subsection (D).","topic":"Guaranty association","source":"La. R.S. 22:2083 https://legis.la.gov/Legis/Law.aspx?d=509204"}],"scenarios":[{"situation":"A Louisiana insurer issued an individual life policy. The insured dies 18 months later, and the insurer finds a misstatement on the application and considers contesting the claim.","q":"Under the Louisiana life incontestability provision, is the policy still contestable?","choices":["No, the period is 1 year","Yes, the 2-year period has not ended","No, the period is 3 years and has ended","Yes, but only in the first 10 days"],"answer":1,"explain":"Source: La. R.S. 22:931(A)(2). Louisiana life policies become incontestable after 2 years, so 18 months is inside it. Health uses 3 years (R.S. 22:975).","topic":"Policy rules","source":"La. R.S. 22:931(A)(2) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"situation":"Marcus is renewing his Louisiana life and health producer license. He completed 24 CE hours, but only 2 were ethics.","q":"Does he meet the CE requirement?","choices":["No, at least 3 of the 24 hours must be ethics","Yes, 24 total hours is all that matters","Yes, ethics hours are optional for life and health","No, he needs 30 hours total"],"answer":0,"explain":"Source: La. R.S. 22:1573(C). Life and health producers need 24 hours before each renewal, with at least 3 in ethics.","topic":"Licensing and CE","source":"La. R.S. 22:1573(C) https://legis.la.gov/Legis/Law.aspx?d=508549"}],"pairs":[{"term":"Life free look","match":"10 days from receipt","source":"La. R.S. 22:931(A)(10) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"term":"Life incontestability","match":"2 years","source":"La. R.S. 22:931(A)(2) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"term":"Health incontestability","match":"3 years","source":"La. R.S. 22:975(A)(13) https://legis.la.gov/Legis/Law.aspx?d=507812"},{"term":"Minimum minor contract age","match":"15 years old","source":"La. R.S. 22:852(B) https://legis.la.gov/Legis/Law.aspx?d=507733"},{"term":"Annuity training","match":"One-time 4 hours, separate from CE","source":"LDI - Annuity Training Requirements https://www.ldi.la.gov/industry/producer-adjuster/education/annuity-training-requirements"}]},"practiceexam":{"title":"Practice Exam: Louisiana Life & Health (original questions)","flashcards":[],"questions":[{"q":"Which of these is NOT an essential element of a valid insurance contract?","choices":["Offer and acceptance","Consideration","Competent parties","A notarized signature"],"answer":3,"topic":"Contract law","explain":"Notarization is not required. The four core elements are offer and acceptance, consideration, competent parties, and legal purpose. Source: general contract law. Source: Cornell LII Wex: Contract.","source":"Cornell LII Wex: Contract https://www.law.cornell.edu/wex/contract"},{"q":"Why is an insurance policy called a contract of adhesion?","choices":["Only the applicant may end it","Both parties negotiate every term","The insurer drafts the policy and the applicant accepts or rejects it","It is a government contract"],"answer":2,"topic":"Contract law","explain":"The insurer writes the terms and the applicant takes them as written. Source: general contract law. Source: Cornell LII Wex: Adhesion contract.","source":"Cornell LII Wex: Adhesion contract https://www.law.cornell.edu/wex/adhesion_contract"},{"q":"When a policy term is ambiguous, how is it generally interpreted?","choices":["By a coin toss","Only by the agent's testimony","In the insurer's favor","Against the drafter, which is usually the insurer"],"answer":3,"topic":"Contract law","explain":"The contra proferentem rule reads ambiguity against the party that drafted the contract. Source: general contract law. Source: Cornell LII Wex: Contra proferentem.","source":"Cornell LII Wex: Contra proferentem https://www.law.cornell.edu/wex/contra_proferentem"},{"q":"Under Louisiana law, when can a false statement in a life or health application bar recovery under the policy?","choices":["Only if the agent was told about it","When made with actual intent to deceive, or when it materially affected the insurer's acceptance of the risk","Never, once the policy is issued","Whenever the answer was incomplete, even if harmless"],"answer":1,"topic":"Application and underwriting","explain":"Source: La. R.S. 22:860(B). A false statement does not bar recovery unless it was made with actual intent to deceive or it materially affected the insurer's acceptance of the risk.","source":"La. R.S. 22:860 https://codes.findlaw.com/la/revised-statutes/la-rev-stat-tit-22-sect-860/"},{"q":"The three main factors used to calculate a life insurance premium are:","choices":["Commission, profit, and tax","Age, sex, and occupation","Mortality, interest, and expenses","Face amount, term, and riders"],"answer":2,"topic":"Premiums","explain":"Premiums reflect mortality (death risk), interest earned, and expenses (loading). Source: general actuarial principles. Source: Alabama Department of Insurance Life Glossary (Dividend).","source":"Alabama Department of Insurance Life Glossary (Dividend) https://aldoi.gov/consumers/LifeGlossary.aspx"},{"q":"Under La. R.S. 22:931, an individual life policy must give a grace period for premium payment of:","choices":["Thirty days, or one month at the insurer's option","60 days","10 days","90 days"],"answer":0,"topic":"Policy provisions","explain":"Source: Louisiana R.S. 22:931(A)(1) (legis.la.gov). The insured is entitled to a grace period of thirty days or, at the insurer's option, one month.","source":"La. R.S. 22:931(A)(1) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"The standard incontestable period for life insurance is:","choices":["1 year","2 years","5 years","6 months"],"answer":1,"topic":"Policy provisions","explain":"After two years in force during the insured's lifetime, the insurer generally cannot contest the policy for misrepresentation. Source: standard incontestability provision. Source: La. R.S. 22:931(A)(2).","source":"La. R.S. 22:931(A)(2) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"Under La. R.S. 22:931, a life policy may exclude death by suicide, sane or insane, for how long after issue?","choices":["1 year","2 years","3 years","For life"],"answer":1,"topic":"Policy provisions","explain":"Source: Louisiana R.S. 22:931(B)(1)(c) (legis.la.gov). Self-destruction within two years from the date of issue may be excluded; the insurer then owes at least the reserve (less indebtedness), not necessarily a premium refund.","source":"La. R.S. 22:931(B)(1)(c) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"Under Louisiana law, the free look period for an individual life insurance policy is:","choices":["60 days","3 days","10 days","30 days"],"answer":2,"topic":"Louisiana regulation","explain":"Louisiana allows 10 days, from receipt of the contract, to examine it and return it for a refund. Source: Louisiana Department of Insurance life insurance guide; Louisiana R.S. 22:931 as cited by LDI. Source: La. R.S. 22:931(A)(10)(a).","source":"La. R.S. 22:931(A)(10)(a) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"A revocable beneficiary can be changed:","choices":["Only with the beneficiary's written consent","Only in group policies","Never","By the owner, without the beneficiary's consent"],"answer":3,"topic":"Beneficiaries","explain":"A revocable beneficiary can be replaced at any time without consent. Source: general beneficiary law. Source: IRMI Glossary: Revocable beneficiary.","source":"IRMI Glossary: Revocable beneficiary https://www.irmi.com/term/insurance-definitions/revocable-beneficiary"},{"q":"If a beneficiary dies before the insured under a per stirpes designation, that beneficiary's share goes to:","choices":["The deceased beneficiary's descendants","The insurer","The owner's estate only","The surviving beneficiaries"],"answer":0,"topic":"Beneficiaries","explain":"Per stirpes passes the share down the family branch. Source: general estate and beneficiary law. Source: Cornell LII Wex: Per stirpes.","source":"Cornell LII Wex: Per stirpes https://www.law.cornell.edu/wex/per_stirpes"},{"q":"Which nonforfeiture option keeps the original face amount in force for a limited time?","choices":["Cash surrender","Extended term","Reduced paid-up","Automatic premium loan"],"answer":1,"topic":"Nonforfeiture","explain":"Extended term uses the cash value to buy term insurance at the original face amount for as long as the cash value allows. Source: standard nonforfeiture provisions. Source: IRMI Glossary: Extended term insurance.","source":"IRMI Glossary: Extended term insurance https://www.irmi.com/term/insurance-definitions/extended-term-insurance"},{"q":"Dividends on a participating life insurance policy are generally:","choices":["Always taxable as ordinary income","Paid only in cash","Guaranteed income","Not guaranteed, and generally not taxable up to the premiums paid"],"answer":3,"topic":"Dividends and tax","explain":"Source: IRS Publication 525. Dividends not included in income reduce the policy's cost basis, so they are generally not taxed until they exceed the premiums paid. Dividends are not guaranteed.","source":"IRS Publication 525 https://www.irs.gov/publications/p525"},{"q":"A life insurance policy becomes a modified endowment contract (MEC) when:","choices":["Premiums paid exceed the 7-pay limit","The owner is over 65","It has an outstanding loan","It is surrendered"],"answer":0,"topic":"Tax","explain":"Failing the 7-pay test under IRC section 7702A creates a MEC. Source: IRC section 7702A. Source: IRC 7702A.","source":"IRC 7702A https://www.law.cornell.edu/uscode/text/26/7702A"},{"q":"When a life insurance policy is sold to an unrelated buyer for value, the death benefit above the buyer's basis is generally:","choices":["Tax-free","Taxable","Deductible","Excluded from the estate"],"answer":1,"topic":"Tax","explain":"This is the transfer-for-value rule, with exceptions for the insured, partners, and certain entities. Source: IRC section 101(a)(2). Source: IRC 101(a)(2).","source":"IRC 101(a)(2) https://www.law.cornell.edu/uscode/text/26/101"},{"q":"Life insurance death proceeds paid in a lump sum are generally:","choices":["Deductible by the estate","Taxable to the beneficiary","Income-tax-free to the beneficiary","Subject to a 10% penalty"],"answer":2,"topic":"Tax","explain":"Death proceeds are generally excluded from the beneficiary's income. Source: IRC section 101(a). Source: IRC 101(a)(1).","source":"IRC 101(a)(1) https://www.law.cornell.edu/uscode/text/26/101"},{"q":"The early withdrawal penalty on the taxable part of an annuity before age 59½ is generally:","choices":["20%","None","5%","10%"],"answer":3,"topic":"Annuities and tax","explain":"A 10% additional tax applies, with exceptions such as death or disability. Source: IRC section 72(q). Source: IRC 72(q).","source":"IRC 72(q) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"Non-annuitized withdrawals from a deferred annuity are generally taxed:","choices":["LIFO, gains first","Pro rata every time","Not at all","FIFO, return of basis first"],"answer":0,"topic":"Annuities and tax","explain":"Annuity withdrawals come out of gains first. Source: IRC section 72(e). Source: IRC 72(e).","source":"IRC 72(e) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"Which exchange can generally be made tax-free under IRC section 1035?","choices":["Annuity to life insurance","Life insurance to annuity","Annuity to cash","Life insurance to cash"],"answer":1,"topic":"Tax","explain":"Life to annuity is allowed. Annuity to life insurance is not. Source: IRC section 1035. Source: IRC 1035(a).","source":"IRC 1035(a) https://www.law.cornell.edu/uscode/text/26/1035"},{"q":"The exclusion ratio on an annuity payout determines:","choices":["The death benefit","The portion of each payment excluded from income","The commission rate","The surrender charge"],"answer":1,"topic":"Annuities and tax","explain":"It is the share of each payment that returns after-tax premium. Source: IRC section 72(b). Source: IRC 72(b).","source":"IRC 72(b) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"For a traditional IRA owner born in 1960 or later, required minimum distributions generally begin at age:","choices":["75","65","70½","73"],"answer":0,"topic":"Retirement plans","explain":"Under SECURE 2.0, RMDs begin at 75 for those born in 1960 or later. Source: SECURE 2.0 Act, IRS. Source: IRC 401(a)(9)(C).","source":"IRC 401(a)(9)(C) https://www.law.cornell.edu/uscode/text/26/401"},{"q":"A qualified Roth IRA withdrawal generally requires:","choices":["Age 65 only","No holding period","Employer approval","A 5-year holding period and age 59½ or another qualifying event"],"answer":3,"topic":"Retirement plans","explain":"Earnings must meet the five-year rule and a qualifying event to be tax-free. Source: IRC section 408A. Source: IRC 408A(d)(2).","source":"IRC 408A(d)(2) https://www.law.cornell.edu/uscode/text/26/408A"},{"q":"A SIMPLE IRA is generally available to employers with:","choices":["100 or fewer employees","10 or fewer employees","500 or fewer employees","Any number of employees"],"answer":0,"topic":"Retirement plans","explain":"SIMPLE IRAs are for small employers, generally with 100 or fewer employees. Source: IRC section 408(p). Source: IRC 408(p)(2)(C).","source":"IRC 408(p)(2)(C) https://www.law.cornell.edu/uscode/text/26/408"},{"q":"The full retirement age for Social Security for people born in 1960 or later is:","choices":["70","65","66","67"],"answer":3,"topic":"Social Security","explain":"Full retirement age is 67 for those born in 1960 or later. Source: Social Security Administration. Source: 42 U.S.C. 416(l) (Cornell LII).","source":"42 U.S.C. 416(l) (Cornell LII) https://www.law.cornell.edu/uscode/text/42/416"},{"q":"Fully insured status for Social Security retirement benefits generally requires:","choices":["40 quarters of coverage","60 quarters of coverage","6 quarters of coverage","20 quarters of coverage"],"answer":0,"topic":"Social Security","explain":"Most workers need 40 quarters, about 10 years. Source: Social Security Administration. Source: 42 U.S.C. 414(a) (Cornell LII).","source":"42 U.S.C. 414(a) (Cornell LII) https://www.law.cornell.edu/uscode/text/42/414"},{"q":"Medicare Part A primarily covers:","choices":["Inpatient hospital care","Dental care","Long-term custodial care","Prescription drugs"],"answer":0,"topic":"Medicare","explain":"Part A covers inpatient hospital stays and some related care. Source: CMS, Medicare.gov. Source: Medicare.gov, What Part A covers.","source":"Medicare.gov, What Part A covers https://www.medicare.gov/what-medicare-covers/what-part-a-covers"},{"q":"Under the FCRA, the usual 7-year and 10-year reporting limits do not apply to life insurance with a face amount of at least:","choices":["$50,000","$100,000","$150,000","$250,000"],"answer":2,"topic":"Privacy and consumer reports","explain":"The exemption applies at $150,000 or more. Source: 15 U.S.C. section 1681c(b). Source: 15 U.S.C. 1681c(b) (Cornell LII).","source":"15 U.S.C. 1681c(b) (Cornell LII) https://www.law.cornell.edu/uscode/text/15/1681c"},{"q":"If an insurer takes adverse action based on a consumer report, the applicant must receive:","choices":["A new policy","Nothing","Notice naming the consumer reporting agency and the right to a free copy within 60 days","A refund of premiums only"],"answer":2,"topic":"Privacy and consumer reports","explain":"The FCRA requires that notice. Source: 15 U.S.C. section 1681m. Source: 15 U.S.C. 1681m(a) (Cornell LII).","source":"15 U.S.C. 1681m(a) (Cornell LII) https://www.law.cornell.edu/uscode/text/15/1681m"},{"q":"The GLBA Safeguards Rule requires financial institutions to:","choices":["Obtain opt-in consent for all sharing","Delete records after 30 days","Send privacy notices only","Maintain a written information security program"],"answer":3,"topic":"Privacy and consumer reports","explain":"The Safeguards Rule requires a written security program. Source: Gramm-Leach-Bliley Act, FTC Safeguards Rule. Source: 16 CFR 314.3 and 314.4 (FTC Safeguards Rule).","source":"16 CFR 314.3 and 314.4 (FTC Safeguards Rule) https://www.law.cornell.edu/cfr/text/16/314.3"},{"q":"Under the federal Do Not Call rules, telemarketing calls are generally allowed only between:","choices":["8 a.m. and 9 p.m. local time","9 a.m. and 5 p.m.","Any time","6 a.m. and 9 p.m."],"answer":0,"topic":"Privacy and consumer reports","explain":"Calls are limited to 8 a.m. to 9 p.m. in the consumer's local time. Source: 16 CFR 310.4(c). Source: 16 CFR 310.4(c) (Cornell LII).","source":"16 CFR 310.4(c) (Cornell LII) https://www.law.cornell.edu/cfr/text/16/310.4"},{"q":"The Do Not Call existing business relationship exception generally covers a consumer who completed a transaction within:","choices":["3 months","12 months","18 months","5 years"],"answer":2,"topic":"Privacy and consumer reports","explain":"Source: 16 CFR 310.2(q). The relationship covers a purchase or financial transaction within the 540 days (about 18 months) before the call, or an inquiry or application within the 90 days (about 3 months) before the call.","source":"16 CFR 310.2(q) (Cornell LII) https://www.law.cornell.edu/cfr/text/16/310.2"},{"q":"Life insurers are generally:","choices":["Required to share health data with agents","HIPAA covered entities","Not HIPAA covered entities, because they are not health plans, providers, or clearinghouses","Exempt from all privacy laws"],"answer":2,"topic":"Privacy and consumer reports","explain":"Source: 45 CFR 160.103. Covered entities are health plans (plans that provide or pay the cost of medical care), health care clearinghouses, and certain health care providers. Life insurers are not in those categories, though other privacy laws such as GLBA and state law still apply.","source":"45 CFR 160.103 (Cornell LII) https://www.law.cornell.edu/cfr/text/45/160.103"},{"q":"An 'own occupation' disability definition means the insured is disabled when they cannot:","choices":["Perform any gainful work","Work at any level of income","Perform any job at all","Perform the duties of their own occupation"],"answer":3,"topic":"Disability insurance","explain":"Own occupation looks at the insured's specific job. Source: general disability insurance terms. Source: 11 NYCRR 185.1(h) (Cornell LII), New York disability regulation.","source":"11 NYCRR 185.1(h) (Cornell LII), New York disability regulation https://www.law.cornell.edu/regulations/new-york/11-NYCRR-185.1"},{"q":"Under standard coordination of benefits rules, total benefits paid by all plans generally cannot exceed:","choices":["100% of allowable expenses","150% of allowable expenses","The plan's premium","80% of billed charges"],"answer":0,"topic":"Health insurance","explain":"COB prevents overpayment across plans. Source: NAIC model coordination of benefits provisions. Source: Model COB contract provisions (Colorado, tracks NAIC Model 120).","source":"Model COB contract provisions (Colorado, tracks NAIC Model 120) https://www.law.cornell.edu/regulations/colorado/3-CCR-702-4-6-2-A"},{"q":"Of the renewability categories listed, which gives the insured the most protection?","choices":["Cancellable","Optionally renewable","Guaranteed renewable","Nonrenewable"],"answer":2,"topic":"Health insurance","explain":"Source: 42 U.S.C. 300gg-2. Under guaranteed renewability the issuer must renew or continue the coverage at the insured's option, so the insurer cannot cancel it, unlike cancellable, optionally renewable, or nonrenewable coverage.","source":"42 U.S.C. 300gg-2 (Cornell LII) https://www.law.cornell.edu/uscode/text/42/300gg-2"},{"q":"Under a noncontributory group life plan, who pays the premiums?","choices":["No one; coverage is free for the insured","The employee pays all","The employer pays 100%","Split 50/50"],"answer":2,"topic":"Group insurance","explain":"Noncontributory plans are paid entirely by the employer. Source: general group insurance terms. Source: IRMI Glossary, noncontributory insurance.","source":"IRMI Glossary, noncontributory insurance https://www.irmi.com/term/insurance-definitions/noncontributory-insurance"},{"q":"Under a standard group conversion privilege, a terminated employee generally must convert within:","choices":["90 days","5 years","31 days","1 year"],"answer":2,"topic":"Group insurance","explain":"Source: Louisiana R.S. 22:942(10), standard provisions for group life policies. The individual policy application and first premium must be made within thirty-one days after termination.","source":"La. R.S. 22:942, Standard provisions for group life policies https://www.legis.la.gov/Legis/LawPrint.aspx?d=507795"},{"q":"In credit life insurance, the beneficiary is generally:","choices":["The creditor","The insurer","The state","The insured's family"],"answer":0,"topic":"Credit life","explain":"The creditor is the beneficiary, and the coverage is tied to the loan. Source: general credit life terms. Source: NAIC Consumer Glossary, credit life insurance.","source":"NAIC Consumer Glossary, credit life insurance https://content.naic.org/glossary-insurance-terms"},{"topic":"Practice exam: general","q":"How many continuing education hours must a Louisiana life and health producer complete before each license renewal, and how many must be on ethics?","choices":["12 hours, 1 on ethics","24 hours, 1 on ethics","12 hours, 3 on ethics","24 hours, 3 on ethics"],"answer":3,"explain":"Source: Louisiana Legislature, R.S. 22:1573. Subsection C requires life and accident and health producers to complete twenty-four hours before each renewal, with at least three hours on ethics.","source":"Louisiana Legislature, R.S. 22:1573 https://legis.la.gov/Legis/Law.aspx?d=508549"},{"topic":"Practice exam: general","q":"What is the maximum number of excess approved CE hours a Louisiana life and health producer may carry over from one renewal period to the next?","choices":["10 hours","3 hours","12 hours","24 hours"],"answer":0,"explain":"Source: Louisiana Legislature, R.S. 22:1573. Subsection G allows producers to carry over no more than ten excess hours of approved instruction into the next renewal period.","source":"Louisiana Legislature, R.S. 22:1573 https://legis.la.gov/Legis/Law.aspx?d=508549"}],"scenarios":[],"pairs":[]},"mockexam":{"title":"Mock Exam: Louisiana Life, Health & Accident (outline-weighted, original)","flashcards":[],"questions":[{"q":"A Louisiana applicant asks for a life policy to take effect six months before the application date. Under Louisiana law, the insurer may generally not issue a policy dated more than how long before the application?","choices":["Six months","One year","Thirty days","Two years"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:904 (legis.la.gov). An insurer may not knowingly issue a life policy purporting to take effect more than six months before the application if the premium is reduced below what would otherwise be payable.","source":"La. R.S. 22:904, Ante-dating of life insurance policies prohibited https://legis.la.gov/legis/Law.aspx?d=507774"},{"q":"Under Louisiana's free look rule for an individual life policy, how many days does the owner have to return the policy for a full refund?","choices":["60 days","10 days","3 days","30 days"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"Louisiana allows 10 days from receipt of the contract. Source: LDI Life Insurance Guide; R.S. 22:931 as cited by LDI. Source: La. R.S. 22:931(A)(10)(a).","source":"La. R.S. 22:931(A)(10)(a) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"Under Louisiana's free look statute, how long must the insurer keep the delivery receipt or certificate of mailing for a life policy?","choices":["Five years","Until the policy lapses","Two years","Thirty days"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"R.S. 22:931(A)(10)(b)-(c) requires delivery receipts and certificates of mailing to be kept for two years. Source: R.S. 22:931. Source: La. R.S. 22:931(A)(10)(b)-(c).","source":"La. R.S. 22:931(A)(10)(b)-(c) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"Which practice is an unfair trade practice under Louisiana insurance law (R.S. 22:1964)?","choices":["Offering a free look period","Collecting a standard premium","Using a standard application form","Misrepresenting a policy's benefits to induce a purchase"],"answer":3,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:1964(1)(a). Misrepresenting the benefits, advantages, conditions, or terms of any policy is an unfair or deceptive act or practice.","source":"La. R.S. 22:1964(1)(a) https://legis.la.gov/Legis/Law.aspx?d=509078"},{"q":"A license holder who is accused of violating insurance law is generally entitled to what before the Commissioner takes disciplinary action such as suspension?","choices":["A hearing","An immediate fine","A jury trial","Nothing; action is automatic"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:1968, 22:1969, and 22:389. The Commissioner first issues a notice of wrongful conduct (22:1968), and an aggrieved party may demand a hearing under Chapter 12 of Title 22 (22:1969(B), 22:389(B)).","source":"La. R.S. 22:1968 and 22:1969 https://legis.la.gov/legis/Law.aspx?d=509082"},{"q":"Which of these is a licensing category recognized in Louisiana's licensing rules?","choices":["Certified financial planner","Individual producer","Public notary","Registered investment adviser"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"The outline lists individual producer and business entity license types under R.S. 22:1542 and 22:1546. Source: Louisiana R.S. Title 22, Licensing. Source: La. R.S. 22:1546.","source":"La. R.S. 22:1546 https://legis.la.gov/legis/Law.aspx?d=508520"},{"q":"A producer changes their home address. What is the producer generally required to do?","choices":["Submit a new exam","Change the policy's terms","Report the change to the Department","Do nothing until renewal"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"The outline cites R.S. 22:1547(G) for reporting changes of name, address, and telephone number. Source: Louisiana R.S. Title 22. Source: La. R.S. 22:1547(G).","source":"La. R.S. 22:1547(G) https://legis.la.gov/legis/Law.aspx?d=508521"},{"q":"Under R.S. 22:1547, a producer unable to meet license renewal procedures because of military service or another extenuating circumstance may request what?","choices":["A waiver of those renewal procedures","A permanent exemption from licensing","A refund of all license fees","Automatic transfer to another state"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:1547(E). A licensed producer unable to comply with renewal procedures due to military service or other extenuating circumstance may request a waiver of those procedures.","source":"La. R.S. 22:1547 https://legis.la.gov/legis/Law.aspx?d=508521"},{"q":"How many continuing education hours must a Louisiana resident life and health producer complete in a renewal period?","choices":["24 hours","12 hours","6 hours","40 hours"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Life, accident and health producers must complete 24 hours (LAC 37:XI section 711; R.S. 22:1573). Source: Louisiana Administrative Code (copy checked on Justia; confirm the current rule on ldi.la.gov). Source: La. R.S. 22:1573(C).","source":"La. R.S. 22:1573(C) https://www.legis.la.gov/Legis/LawPrint.aspx?d=508549"},{"q":"Which federal law is listed in the outline's Louisiana insurance context as a privacy rule that financial institutions and producers must follow?","choices":["Social Security Act","Gramm-Leach-Bliley Act","Affordable Care Act","Employee Retirement Income Security Act"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"The Gramm-Leach-Bliley Act (GLBA) requires privacy notices and safeguards for nonpublic personal information. Source: GLBA, 15 U.S.C. Chapter 94. Source: Gramm-Leach-Bliley Act, 15 U.S.C. 6801.","source":"Gramm-Leach-Bliley Act, 15 U.S.C. 6801 https://www.law.cornell.edu/uscode/text/15/6801"},{"q":"Under Louisiana insurance law, what does the Commissioner's examination of books and records allow?","choices":["Reviewing only an agent's personal finances","Approving every policy form","Review of a company's records to check compliance","Setting every company's premium"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"The outline cites examination of books and records (R.S. 22:1967, 1981, 1990). Source: Louisiana R.S. Title 22. Source: La. R.S. 22:1967 and 22:1990.","source":"La. R.S. 22:1967 and 22:1990 https://legis.la.gov/legis/Law.aspx?d=509081"},{"q":"Insurance fraud is a crime in Louisiana. What is the best description?","choices":["Any late premium payment","Shopping for lower rates","Refusing to sign an application","Knowingly making false statements to obtain insurance benefits or to deceive an insurer"],"answer":3,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:1924. It criminalizes acts done with intent to injure, defraud, or deceive an insurer, including presenting statements knowing they contain false, incomplete, or fraudulent information.","source":"La. R.S. 22:1924 https://www.legis.la.gov/Legis/Law.aspx?d=509062"},{"q":"An advertisement for a life policy must not be misleading. Which statement describes the rule?","choices":["Ads must be accurate and not misrepresent coverage","Ads may exaggerate benefits if they include a disclaimer","Ads are exempt from state review","Ads may omit premium costs"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Louisiana advertising rules (Reg 37:XIII.4101-.4123, cited in the outline) require accurate advertising. Source: Louisiana Administrative Code, Title 37. Source: LAC 37:XIII.4107 (Cornell LII).","source":"LAC 37:XIII.4107 (Cornell LII) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-4107"},{"q":"What is a 'replacement' under Louisiana life insurance rules?","choices":["Changing the premium payment mode","A new policy that replaces, lapses, or surrenders an existing policy","Renewing an existing policy at the same terms","Adding a rider to an existing policy"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"Replacement rules (Reg 37:XIII.8901-.8925) apply when a new policy replaces an existing one. Source: Louisiana Administrative Code, Title 37. Source: Louisiana Administrative Code 37:XIII.8903 (Cornell LII).","source":"Louisiana Administrative Code 37:XIII.8903 (Cornell LII) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-8903"},{"q":"Which is a standard Louisiana rule for life insurance illustrations?","choices":["Illustrations are never required","Illustrations may use unlimited projected returns","Illustrations must follow the state's illustration regulation","Illustrations may guarantee future dividends"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"Illustrations are covered by Reg 37:XIII.3301-.3323, cited in the outline. Source: Louisiana Administrative Code, Title 37. Source: LAC 37:XIII.3309 (Cornell LII).","source":"LAC 37:XIII.3309 (Cornell LII) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-3309"},{"q":"The Louisiana Life and Health Insurance Guaranty Association provides what protection?","choices":["Limited backing for policyholders if an insurer becomes insolvent","Guaranteed premium refunds for all policies","Free medical care","Unlimited coverage for any loss"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:2083. Benefits are capped, for any one life, at $300,000 in life insurance death benefits, $500,000 in health benefits, and $250,000 in present value of annuity benefits.","source":"La. R.S. 22:2083 https://legis.la.gov/Legis/Law.aspx?d=509204"},{"q":"Which is the best description of a 'commissioner's general duties and powers' item on the exam?","choices":["The Commissioner works only for agents","The Commissioner enforces Title 22 and regulates the industry","The Commissioner sells policies","The Commissioner sets personal premiums"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"The Commissioner's duties are set out in R.S. 22:2 (cited in the outline). Source: Louisiana R.S. Title 22. Source: La. R.S. 22:2.","source":"La. R.S. 22:2 https://legis.la.gov/legis/Law.aspx?d=506142"},{"q":"Under the outline's privacy topic, what is consumer financial information?","choices":["Public property records","Any publicly posted news article","Premium rates filed with the state","Nonpublic personal financial information collected about a consumer"],"answer":3,"topic":"Louisiana Insurance Regulation","explain":"Louisiana privacy rules (Reg 37:XIII.9903-.9953, cited in the outline) cover nonpublic personal financial information. Source: Louisiana Administrative Code, Title 37. Source: Louisiana Administrative Code 37:XIII.9909 (Cornell LII).","source":"Louisiana Administrative Code 37:XIII.9909 (Cornell LII) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-9909"},{"q":"Which federal law requires a 60-day free-copy notice after an adverse insurance action based on a consumer report?","choices":["Fair Credit Reporting Act","Affordable Care Act","Medicare Act","ERISA"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"FCRA section 615 (15 U.S.C. 1681m) requires adverse-action notice and free-report rights. Source: 15 U.S.C. 1681m. Source: FCRA, 15 U.S.C. 1681m(a).","source":"FCRA, 15 U.S.C. 1681m(a) https://www.law.cornell.edu/uscode/text/15/1681m"},{"q":"In a life insurance replacement, what does the standard replacement notice ask the applicant to do?","choices":["Pay the old policy's premium twice","Compare the existing policy with the proposed policy","Sign a blank form","Cancel the new policy at once"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"Source: Louisiana Administrative Code 37:XIII.8923 (Notice Regarding Replacement). The notice tells the applicant to make a careful comparison of existing benefits before deciding.","source":"Louisiana Administrative Code 37:XIII.8923 (Cornell LII) https://www.law.cornell.edu/regulations/louisiana/La-Admin-Code-tit-37-SS-XIII-8923"},{"q":"Which of these is an unfair trade practice in insurance under the outline's list?","choices":["Filing a claim on time","Using a licensed agent","Rebating premiums to induce purchase","Providing a free look period"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"R.S. 22:1964(8) bars rebating. Source: Louisiana R.S. 22:1964. Source: La. R.S. 22:1964(8).","source":"La. R.S. 22:1964(8) https://legis.la.gov/legis/Law.aspx?d=509078"},{"q":"Under R.S. 22:2098, how may an insurer refer to the Louisiana life and health guaranty association in sales?","choices":["It must mention the association in every policy sale","Advertising is exempt from state rules","It must state the association's coverage cap in every ad","It may not use the association's existence to sell or induce a purchase"],"answer":3,"topic":"Louisiana Insurance Regulation","explain":"R.S. 22:2098 bars using the association to sell or induce insurance and sets notice rules. Source: R.S. 22:2098. Source: La. R.S. 22:2098.","source":"La. R.S. 22:2098 https://www.legis.la.gov/legis/Law.aspx?d=509256"},{"q":"Under R.S. 22:1964, which act is an unfair trade practice?","choices":["Making a misrepresentation of a policy's terms, benefits, or dividends","Providing a written policy summary","Answering a consumer's questions honestly","Filing a complaint with the Department"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"R.S. 22:1964 lists misrepresenting policy terms and benefits as an unfair practice. Source: R.S. 22:1964. Source: La. R.S. 22:1964(1).","source":"La. R.S. 22:1964(1) https://legis.la.gov/legis/Law.aspx?d=509078"},{"q":"Which practice does R.S. 22:1964 prohibit in connection with selling a contract of insurance?","choices":["Using a licensed agent","Knowingly offering or making a rebate or inducement not specified in the policy","Offering a free look period","Charging the standard premium"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"The statute prohibits rebating and inducements not stated in the policy. Source: R.S. 22:1964; confirm wording on legis.la.gov. Source: La. R.S. 22:1964(8) Rebates.","source":"La. R.S. 22:1964(8) Rebates https://legis.la.gov/Legis/LawPrint.aspx?d=509078"},{"q":"A Louisiana producer changes their name or address. What does R.S. 22:1547(G) require?","choices":["Pass a new exam","No report is needed","Report the change to the Department","Wait until renewal"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:1547(G). Every licensee must notify the commissioner of any change of address or legal name within thirty days of the change.","source":"La. R.S. 22:1547(G) https://www.legis.la.gov/Legis/LawPrint.aspx?d=508521"},{"q":"Under R.S. 40:1171.1, which law generally governs an insurer's dealings involving HIV testing or results in Louisiana?","choices":["The general HIV confidentiality statute alone","Federal HIPAA alone","No rule applies","Title 22 and the Insurance Commissioner's rules"],"answer":3,"topic":"Louisiana Insurance Regulation","explain":"The HIV statute says insurer dealings are governed exclusively by Title 22 and the Commissioner's rules. Source: R.S. 40:1171.1; LAC 48:I-13507. Source: La. R.S. 40:1171.1.","source":"La. R.S. 40:1171.1 https://www.legis.la.gov/Legis/LawPrint.aspx?d=964723"},{"q":"Louisiana's backdating rule for life policies generally bars an insurer from issuing a policy that takes effect how far before the application date when the premium is reduced as a result?","choices":["More than six months","More than one year","More than 30 days","More than two years"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:771 (former R.S. 22:904, redesignated eff. Jan. 1, 2009). An insurer may not knowingly issue a life policy dated more than six months before the application if the premium is reduced below what would otherwise be payable.","source":"La. R.S. 22:771 (former 22:904) https://legis.la.gov/legis/Law.aspx?d=507774"},{"q":"Under Louisiana's life policy ante-dating statute, which action is expressly NOT prohibited?","choices":["Converting an existing life policy as of its original date when the new amount of insurance does not exceed the original","Issuing a new policy dated eight months before application with a reduced premium","Issuing a new policy dated one year before application with a reduced premium","Issuing a new policy dated two years before application with a reduced premium"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:771 (former 22:904). The section does not prohibit exchange, alteration, or conversion of life policies as of the original date if the amount of insurance does not exceed the original policy.","source":"La. R.S. 22:771 (former 22:904) https://legis.la.gov/legis/Law.aspx?d=507774"},{"q":"The Louisiana free look period for individual life policies is generally how many days from receipt of the policy?","choices":["45 days","5 days","10 days","20 days in all cases"],"answer":2,"topic":"Louisiana Insurance Regulation","explain":"R.S. 22:931 provides a ten-day window to examine the policy from receipt. The rule does not apply to group life, industrial life, or service insurance (R.S. 22:931(C)). Source: R.S. 22:931. Source: La. R.S. 22:931(A)(10)(a) and (C).","source":"La. R.S. 22:931(A)(10)(a) and (C) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"Which license type is issued to a business entity rather than an individual?","choices":["Individual producer license","Temporary license","Adjuster license","Business entity license"],"answer":3,"topic":"Louisiana Insurance Regulation","explain":"The outline lists business entity licenses under R.S. 22:1542(2) and 1546(B). Source: Louisiana R.S. Title 22. Source: La. R.S. 22:1546(B).","source":"La. R.S. 22:1546(B) https://legis.la.gov/Legis/LawPrint.aspx?d=508520"},{"q":"Louisiana law may exempt a producer from continuing education if which condition applies?","choices":["Age 65 or older with at least 15 years of experience as a licensed producer, meeting the statute's other conditions","Any producer with a clean record","A producer who sells only group policies","A producer who never renews a license"],"answer":0,"topic":"Louisiana Insurance Regulation","explain":"Source: La. R.S. 22:1573(I). The exemption applies to a producer at least 65 with at least 15 years as a licensed producer who has retired or is still selling through a licensed Louisiana insurer or agency, and who attests on the commissioner's form.","source":"La. R.S. 22:1573(I) https://www.legis.la.gov/Legis/LawPrint.aspx?d=508549"},{"q":"The continuing education hours required of a Louisiana resident life and health producer in a renewal period are:","choices":["40 hours","24 hours","12 hours","6 hours"],"answer":1,"topic":"Louisiana Insurance Regulation","explain":"Life, accident and health producers complete 24 hours (LAC 37:XI section 711; R.S. 22:1573). Source: Louisiana Administrative Code; confirm on ldi.la.gov. Source: La. R.S. 22:1573(C).","source":"La. R.S. 22:1573(C) https://www.legis.la.gov/Legis/LawPrint.aspx?d=508549"},{"q":"Under the federal Do Not Call rules, telemarketing calls are generally allowed only between:","choices":["9 a.m. and 5 p.m.","Any time","8 a.m. and 9 p.m. in the consumer's local time","6 a.m. and 9 p.m."],"answer":2,"topic":"Federal Regulation","explain":"16 CFR 310.4(c) limits calling hours to 8 a.m. through 9 p.m. local time. Source: FTC Telemarketing Sales Rule. Source: 16 CFR 310.4(c) (eCFR).","source":"16 CFR 310.4(c) (eCFR) https://www.ecfr.gov/api/renderer/v1/content/enhanced/current/title-16?part=310&section=310.4"},{"q":"Under the GLBA Safeguards Rule, a financial institution must:","choices":["Send privacy notices only","Obtain opt-in consent for all sharing","Delete records after 30 days","Maintain a written information security program"],"answer":3,"topic":"Federal Regulation","explain":"The Safeguards Rule requires a written security program. Source: GLBA; FTC Safeguards Rule. Source: 16 CFR 314.3(a) FTC Safeguards Rule (Cornell LII).","source":"16 CFR 314.3(a) FTC Safeguards Rule (Cornell LII) https://www.law.cornell.edu/cfr/text/16/314.3"},{"q":"Which risk-handling method is best described as shifting the financial loss to another party?","choices":["Risk transfer","Risk avoidance","Risk retention","Risk reduction"],"answer":0,"topic":"General Insurance Concepts","explain":"Risk transfer shifts the loss, usually by buying insurance. Source: standard risk management terminology. Source: IRMI glossary: transfer of risk.","source":"IRMI glossary: transfer of risk https://www.irmi.com/term/insurance-definitions/transfer-of-risk"},{"q":"Which element is required for an insurable risk?","choices":["The loss must be catastrophic for the insurer","The loss must be definite and measurable","The loss must be certain to occur","The loss must be caused by the insured on purpose"],"answer":1,"topic":"General Insurance Concepts","explain":"Source: IRMI. Insurable losses must be measurable and definite to facilitate claim settlements, and the insured perils should be random and unpredictable to individual policyholders (accidental).","source":"IRMI https://www.irmi.com/articles/expert-commentary/rethinking-the-insurability-of-natural-catastrophes"},{"q":"A hazard that increases the chance of a loss through carelessness is called:","choices":["Physical hazard","Speculative hazard","Morale hazard","Moral hazard"],"answer":2,"topic":"General Insurance Concepts","explain":"Morale hazard is carelessness caused by insurance; moral hazard is dishonesty. Source: standard insurance terminology. Source: IRMI glossary: morale hazard.","source":"IRMI glossary: morale hazard https://www.irmi.com/term/insurance-definitions/morale-hazard"},{"q":"What is the peril in a house fire loss?","choices":["The house's wiring","The homeowner's negligence","The insurance premium","Fire"],"answer":3,"topic":"General Insurance Concepts","explain":"A peril is the cause of a loss. Source: standard insurance terminology. Source: IRMI glossary: peril.","source":"IRMI glossary: peril https://www.irmi.com/term/insurance-definitions/peril"},{"q":"Which is an example of pure risk?","choices":["Risk of death from illness","Investing in stocks","Gambling at a casino","Starting a business for profit"],"answer":0,"topic":"General Insurance Concepts","explain":"Pure risk has only loss or no loss. Source: standard risk terminology. Source: IRMI glossary: pure risk.","source":"IRMI glossary: pure risk https://www.irmi.com/term/insurance-definitions/pure-risk"},{"q":"What is the Law of Large Numbers?","choices":["Large companies never fail","Results approach predicted results as the number of exposures grows","Premiums always rise with age","Large policies cost less"],"answer":1,"topic":"General Insurance Concepts","explain":"Larger exposure groups produce more predictable results. Source: standard actuarial principles. Source: IRMI glossary: law of large numbers.","source":"IRMI glossary: law of large numbers https://www.irmi.com/term/insurance-definitions/law-of-large-numbers"},{"q":"A mutual insurer is best described as:","choices":["Owned by the state","Owned by the agents","Owned by its policyholders","Owned by shareholders"],"answer":2,"topic":"General Insurance Concepts","explain":"Mutual companies are owned by policyholders. Source: standard insurer classification. Source: IRMI glossary: mutual company.","source":"IRMI glossary: mutual company https://www.irmi.com/term/insurance-definitions/mutual-company"},{"q":"Risk retention means:","choices":["Buying an insurance policy","Eliminating the risky activity","Sharing risk through a pool of policyholders","Accepting the financial consequences of a loss, such as paying a deductible"],"answer":3,"topic":"General Insurance Concepts","explain":"Retention means the insured keeps part or all of the loss. Source: standard risk management terminology. Source: IRMI glossary: risk retention.","source":"IRMI glossary: risk retention https://www.irmi.com/term/insurance-definitions/risk-retention"},{"q":"Which is an example of a speculative risk?","choices":["Investing in the stock market","The risk of a house fire","The risk of premature death","The risk of a car theft"],"answer":0,"topic":"General Insurance Concepts","explain":"Speculative risk includes the chance of gain as well as loss and is generally uninsurable. Source: standard risk terminology. Source: IRMI glossary: speculative risk.","source":"IRMI glossary: speculative risk https://www.irmi.com/term/insurance-definitions/speculative-risk"},{"q":"Which is the best example of adverse selection?","choices":["The insurer rejects every applicant","Higher-risk applicants apply for coverage more often than average-risk applicants","The insurer charges the same rate to everyone","Lower-risk applicants buy more coverage than average applicants"],"answer":1,"topic":"General Insurance Concepts","explain":"Adverse selection is higher-risk people seeking insurance more than average. Source: standard underwriting principles. Source: IRMI glossary: adverse selection.","source":"IRMI glossary: adverse selection https://www.irmi.com/term/insurance-definitions/adverse-selection"},{"q":"The principle of indemnity means:","choices":["The insured may profit from a loss","Premiums are refunded when a claim is paid","The insured should not profit from an insured loss","The insurer pays a fixed face amount regardless of loss"],"answer":2,"topic":"General Insurance Concepts","explain":"Source: IRMI glossary (other insurance clause), which describes the principle of indemnity as stating that an insured should not profit from an insured loss.","source":"IRMI glossary: other insurance clause https://www.irmi.com/term/insurance-definitions/other-insurance-clause"},{"q":"Which is required for a valid insurance contract?","choices":["A notarized signature","A witness on each page","A government seal","Consideration"],"answer":3,"topic":"Life, Health, and Accident Insurance Basics","explain":"Core elements: offer and acceptance, consideration, competent parties, legal purpose. Source: general contract law. Source: Cornell LII Wex: consideration.","source":"Cornell LII Wex: consideration https://www.law.cornell.edu/wex/consideration"},{"q":"An applicant's signed statements on an application are generally treated as:","choices":["Representations","Warranties that must be literally true","Irrelevant","Guarantees of future health"],"answer":0,"topic":"Life, Health, and Accident Insurance Basics","explain":"Application statements are representations (substantially true). Source: general insurance contract law. Source: La. R.S. 22:860.","source":"La. R.S. 22:860 https://legis.la.gov/Legis/Law.aspx?d=507741"},{"q":"A material misrepresentation on a life application may allow the insurer to:","choices":["Require the agent to pay the claim","Void the contract, subject to state law","Pay double benefits","Refund only the premium with no review"],"answer":1,"topic":"Life, Health, and Accident Insurance Basics","explain":"A material misrepresentation can make the contract voidable. Source: general contract law; confirm Louisiana rules. Source: La. R.S. 22:860.","source":"La. R.S. 22:860 https://legis.la.gov/Legis/Law.aspx?d=507741"},{"q":"A conditional receipt is generally given when:","choices":["The initial premium is paid with the application","The policy is delivered","The policy is canceled","The claim is paid"],"answer":0,"topic":"Life, Health, and Accident Insurance Basics","explain":"Conditional coverage starts when underwriting approves, subject to conditions. Source: standard receipt practice. Source: N.Y. 11 NYCRR 52.53 (Cornell LII).","source":"N.Y. 11 NYCRR 52.53 (Cornell LII) https://www.law.cornell.edu/regulations/new-york/11-NYCRR-52.53"},{"q":"What is the free look period?","choices":["A period when claims are paid","A period of grace for premiums","A period after delivery to return the policy for a refund","A period before application"],"answer":2,"topic":"Life, Health, and Accident Insurance Basics","explain":"Free look lets the owner cancel for a refund. Source: LDI Life Insurance Guide. Source: La. R.S. 22:951.","source":"La. R.S. 22:951 https://legis.la.gov/legis/Law.aspx?d=507805"},{"q":"Under La. R.S. 22:931, the grace period for premiums after the first on a life policy is:","choices":["10 days","60 days","90 days","Thirty days, or one month at the insurer's option"],"answer":3,"topic":"Life, Health, and Accident Insurance Basics","explain":"Source: La. R.S. 22:931(A)(1). The insured gets a grace period of thirty days or, at the insurer's option, one month.","source":"La. R.S. 22:931 https://legis.la.gov/legis/Law.aspx?d=507787"},{"q":"Which is a health insurance term for the amount paid before coverage begins?","choices":["Premium","Deductible","Coinsurance","Copayment"],"answer":1,"topic":"Life, Health, and Accident Insurance Basics","explain":"A deductible is the out-of-pocket amount before coverage starts. Source: standard health insurance terminology. Source: HealthCare.gov glossary.","source":"HealthCare.gov glossary https://www.healthcare.gov/glossary/deductible/"},{"q":"Coinsurance is best described as:","choices":["The insurer's profit","A premium surcharge","A percentage the insured pays after the deductible","A flat fee per visit"],"answer":2,"topic":"Life, Health, and Accident Insurance Basics","explain":"Coinsurance is the percentage split (for example 80/20). Source: standard health insurance terminology. Source: HealthCare.gov glossary.","source":"HealthCare.gov glossary https://www.healthcare.gov/glossary/co-insurance/"},{"q":"An out-of-pocket maximum limits:","choices":["The insurer's premium","The number of doctor visits","The age of the insured","The insured's total cost-sharing in a plan year"],"answer":3,"topic":"Life, Health, and Accident Insurance Basics","explain":"The out-of-pocket maximum caps the insured's cost-sharing. Source: standard health plan terminology. Source: HealthCare.gov glossary.","source":"HealthCare.gov glossary https://www.healthcare.gov/glossary/out-of-pocket-maximum-limit/"},{"q":"Which term describes accident and health policies that pay a fixed amount per day of hospital stay?","choices":["Hospital indemnity","Major medical","Group term","Universal life"],"answer":0,"topic":"Life, Health, and Accident Insurance Basics","explain":"Hospital indemnity pays a fixed daily benefit. Source: standard health insurance terminology. Source: 14 Va. Admin. Code 5-141-120 (Cornell LII).","source":"14 Va. Admin. Code 5-141-120 (Cornell LII) https://www.law.cornell.edu/regulations/virginia/14VAC5-141-120"},{"q":"Under the doctrine of utmost good faith, what must both parties do?","choices":["Pay premiums in cash only","Disclose all material facts honestly","Negotiate the lowest price","Hide prior health history"],"answer":1,"topic":"Life, Health, and Accident Insurance Basics","explain":"Insurance contracts require full disclosure of material facts by both parties. Source: general insurance contract law. Source: IRMI glossary: uberrimae fidei.","source":"IRMI glossary: uberrimae fidei https://www.irmi.com/term/insurance-definitions/uberrimae-fidei"},{"q":"An insurer that routinely accepted late premiums may be prevented from canceling for lateness under which doctrine?","choices":["Aleatory","Unilateral","Estoppel","Adhesion"],"answer":2,"topic":"Life, Health, and Accident Insurance Basics","explain":"Estoppel stops a party from taking a position that contradicts its earlier conduct. Source: general contract law. Source: IRMI glossary: estoppel.","source":"IRMI glossary: estoppel https://www.irmi.com/term/insurance-definitions/estoppel"},{"q":"The free look period generally begins:","choices":["On the date of a claim","On delivery of the policy","On the application date","On the first premium payment"],"answer":1,"topic":"Life, Health, and Accident Insurance Basics","explain":"Free look runs from delivery. Source: LDI Life Insurance Guide; standard policy provision. Source: La. R.S. 22:931(A)(10)(a).","source":"La. R.S. 22:931(A)(10)(a) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"The Medical Information Bureau (MIB) is best described as:","choices":["An agency that makes final underwriting decisions","A government agency that sets premiums","A company that pays claims","A member database that helps detect misrepresentation by sharing coded impairment information"],"answer":3,"topic":"Life, Health, and Accident Insurance Basics","explain":"Source: MIB Group (mib.com). MIB is a member consortium of life insurers whose coded information alerts underwriters to possible errors, omissions or misrepresentations; insurers may not decide based on an MIB file without further investigation.","source":"MIB Group, Facts About MIB https://mib.com/facts_about_mib.html"},{"q":"Which policy is pure death protection for a set period with no cash value?","choices":["Term life","Whole life","Universal life","Variable life"],"answer":0,"topic":"Types of Life Insurance Policies","explain":"Term insurance has no cash value. Source: standard product definitions. Source: Alabama Department of Insurance Life Glossary.","source":"Alabama Department of Insurance Life Glossary https://aldoi.gov/Consumers/LifeGlossary.aspx"},{"q":"Variable universal life policies place cash value in:","choices":["The insurer's general account only","A government fund","A bank savings account","Separate account subaccounts chosen by the owner"],"answer":3,"topic":"Types of Life Insurance Policies","explain":"Source: NAIC Glossary of Insurance Terms. Variable universal life cash value growth depends on separate account investment results, and the policyholder selects the accounts.","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"Which product requires a securities license and a prospectus?","choices":["Variable life insurance","Fixed annuity","Credit life","Group term life"],"answer":0,"topic":"Types of Life Insurance Policies","explain":"Source: FINRA, Insurance page. Variable life is a type of security regulated by FINRA, and sellers must be FINRA-registered representatives and licensed insurance agents.","source":"FINRA: Insurance (investment products) https://www.finra.org/investors/investing/investment-products/insurance"},{"q":"Credit life insurance is generally written as:","choices":["Universal life","Decreasing term","Level term","Whole life"],"answer":1,"topic":"Types of Life Insurance Policies","explain":"Source: NAIC Statutory Issue Paper No. 59. Credit life insurance is generally in the form of decreasing term insurance, issued on debtors to cover loan balances.","source":"NAIC Statutory Issue Paper No. 59, Credit Life and Accident and Health https://content.naic.org/sites/default/files/inline-files/059_I.pdf"},{"q":"A modified endowment contract is created when:","choices":["The policy has a loan","The owner is over 65","The policy is group issued","The policy fails the 7-pay test"],"answer":3,"topic":"Types of Life Insurance Policies","explain":"Failing the 7-pay test under IRC 7702A creates a MEC. Source: IRC 7702A. Source: 26 U.S.C. 7702A.","source":"26 U.S.C. 7702A https://www.law.cornell.edu/uscode/text/26/7702A"},{"q":"Which policy's cash value is invested in subaccounts and has no guaranteed cash value?","choices":["Variable life","Whole life","Term life","Limited-pay whole life"],"answer":0,"topic":"Types of Life Insurance Policies","explain":"Variable life cash values depend on subaccount results. Source: standard product definitions. Source: NAIC Life Insurance topic page.","source":"NAIC Life Insurance topic page https://content.naic.org/insurance-topics/life-insurance"},{"q":"A limited-pay whole life policy is best described as:","choices":["A policy with no cash value","Lifetime coverage with premiums paid over a shorter period","Term coverage with a fixed end date","Lifetime coverage with premiums paid for life"],"answer":1,"topic":"Types of Life Insurance Policies","explain":"Limited-pay policies are paid up after a set number of years. Source: standard product definitions. Source: NAIC Glossary of Insurance Terms.","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"Which product has flexible premiums and an adjustable death benefit?","choices":["Ordinary whole life","Group term life","Universal life","Term life"],"answer":2,"topic":"Types of Life Insurance Policies","explain":"Universal life has flexible premiums and an adjustable death benefit. Source: standard product definitions. Source: Alabama Department of Insurance Life Glossary.","source":"Alabama Department of Insurance Life Glossary https://aldoi.gov/Consumers/LifeGlossary.aspx"},{"q":"The incontestable clause generally applies after how long?","choices":["Two years","Six months","One year","Five years"],"answer":0,"topic":"Policy Provisions, Options, and Riders","explain":"Standard incontestability is two years. Source: standard policy provision. Source: NC Department of Insurance; La. R.S. 22:931(A)(2).","source":"NC Department of Insurance; La. R.S. 22:931(A)(2) https://www.ncdoi.gov/standard-policy-provisions-and-optional-riders"},{"q":"A suicide exclusion in a life policy usually applies in the first:","choices":["Lifetime","Two years","Six months","Ten years"],"answer":1,"topic":"Policy Provisions, Options, and Riders","explain":"Standard suicide exclusion is two years. Source: standard policy provision. Source: La. R.S. 22:931(B)(1)(c).","source":"La. R.S. 22:931(B)(1)(c) https://www.legis.la.gov/Legis/LawPrint.aspx?d=507787"},{"q":"The automatic premium loan option:","choices":["Reduces the death benefit by half","Turns the policy into term","Borrows from cash value to pay an overdue premium","Forgives premiums"],"answer":2,"topic":"Policy Provisions, Options, and Riders","explain":"APL borrows from cash value. Source: standard policy provision. Source: Alabama Department of Insurance Life Glossary.","source":"Alabama Department of Insurance Life Glossary https://aldoi.gov/Consumers/LifeGlossary.aspx"},{"q":"A nonforfeiture option that keeps the original face amount for a limited time is:","choices":["Reduced paid-up","Cash surrender","Dividend accumulation","Extended term"],"answer":3,"topic":"Policy Provisions, Options, and Riders","explain":"Extended term keeps the original face amount for a limited period. Source: standard nonforfeiture provisions. Source: IRMI glossary: extended term insurance.","source":"IRMI glossary: extended term insurance https://www.irmi.com/term/insurance-definitions/extended-term-insurance"},{"q":"Which dividend option pays dividends as cash to the policyowner?","choices":["Cash payment","Paid-up additions","One-year term","Accumulation at interest"],"answer":0,"topic":"Policy Provisions, Options, and Riders","explain":"The cash option pays dividends in cash. Source: standard dividend options. Source: NC Department of Insurance, Life Insurance Options.","source":"NC Department of Insurance, Life Insurance Options https://www.ncdoi.gov/life-insurance-options"},{"q":"Paid-up additions purchased with dividends:","choices":["Are taxable each year","Increase the death benefit and cash value","Reduce the death benefit","Require evidence of insurability"],"answer":1,"topic":"Policy Provisions, Options, and Riders","explain":"Paid-up additions increase death benefit and cash value; no new underwriting. Source: standard dividend options. Source: IRMI glossary: dividend addition.","source":"IRMI glossary: dividend addition https://www.irmi.com/term/insurance-definitions/dividend-addition"},{"q":"The waiver of premium rider waives premiums:","choices":["Only for accidental death","For the owner's spouse only","During the insured's total disability","Only at age 65"],"answer":2,"topic":"Policy Provisions, Options, and Riders","explain":"Source: Alabama DOI Life Insurance Glossary. Waiver of premium keeps the policy in force under stated conditions, most often when the insured becomes disabled; the waiting-period detail was removed because it could not be sourced.","source":"Alabama DOI Life Insurance Glossary https://aldoi.gov/Consumers/LifeGlossary.aspx"},{"q":"A guaranteed insurability rider lets the insured:","choices":["Reduce coverage without penalty","Avoid premium payments","Change beneficiaries automatically","Buy more coverage on set dates without evidence of insurability"],"answer":3,"topic":"Policy Provisions, Options, and Riders","explain":"GIO riders allow future purchases without underwriting. Source: standard rider terms. Source: Alabama DOI Life Insurance Glossary.","source":"Alabama DOI Life Insurance Glossary https://aldoi.gov/Consumers/LifeGlossary.aspx"},{"q":"A spendthrift clause protects proceeds from:","choices":["Probate costs","The beneficiary's creditors","The insurer's creditors","Income taxes"],"answer":1,"topic":"Policy Provisions, Options, and Riders","explain":"Spendthrift clauses shield proceeds from the beneficiary's creditors. Source: standard beneficiary provisions. Source: Cornell LII Wex: spendthrift clause.","source":"Cornell LII Wex: spendthrift clause https://www.law.cornell.edu/wex/spendthrift_clause"},{"q":"Under a 'per stirpes' designation, a predeceased beneficiary's share goes to:","choices":["The surviving beneficiaries","The insurer","The estate only","That person's descendants"],"answer":3,"topic":"Policy Provisions, Options, and Riders","explain":"Per stirpes passes the share down the family branch. Source: standard beneficiary terminology. Source: Cornell LII Wex: per stirpes.","source":"Cornell LII Wex: per stirpes https://www.law.cornell.edu/wex/per_stirpes"},{"q":"A policy loan from a non-MEC life policy is generally:","choices":["Not taxable when taken","Taxed as ordinary income when taken","Subject to a 10% penalty","Deductible"],"answer":0,"topic":"Policy Provisions, Options, and Riders","explain":"Policy loans are generally not taxable. Source: IRC 72(e) and 7702 rules. Source: 26 U.S.C. 72(e)(4)(A), (e)(10).","source":"26 U.S.C. 72(e)(4)(A), (e)(10) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"A grace period is generally:","choices":["A conversion window","A period after the due date during which coverage continues","A period before the policy starts","A free look period"],"answer":1,"topic":"Policy Provisions, Options, and Riders","explain":"Grace periods keep coverage in force after a missed due date. Source: standard policy provision. Source: La. R.S. 22:931(A)(1).","source":"La. R.S. 22:931(A)(1) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"A reinstatement provision generally requires:","choices":["A new application only","A refund of premiums","Evidence of insurability and payment of back premiums with interest","No payment"],"answer":2,"topic":"Policy Provisions, Options, and Riders","explain":"Reinstatement typically requires evidence of insurability and back premiums with interest. Source: standard policy provision. Source: La. R.S. 22:931(A)(9).","source":"La. R.S. 22:931(A)(9) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"A misstatement of age provision generally:","choices":["Requires a new medical exam","Doubles the premium","Adjusts benefits to what the premiums would have bought at the correct age","Voids the policy"],"answer":2,"topic":"Policy Provisions, Options, and Riders","explain":"Source: La. R.S. 22:931(A)(4). If age was misstated, the amount payable is what the premium would have purchased at the correct age.","source":"La. R.S. 22:931(A)(4) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"q":"Dividends from participating life insurance policies are:","choices":["Guaranteed income","Required to be taken in cash","Always taxable","Not guaranteed"],"answer":3,"topic":"Policy Provisions, Options, and Riders","explain":"Dividends are not guaranteed and generally return excess premium. Source: standard dividend terms; IRS treatment. Source: Alabama DOI Life Insurance Glossary.","source":"Alabama DOI Life Insurance Glossary https://aldoi.gov/Consumers/LifeGlossary.aspx"},{"q":"An annuity's accumulation period is when:","choices":["Premiums are paid and funds grow tax-deferred","Payments are made to the annuitant","The annuity is surrendered","The death benefit is paid"],"answer":0,"topic":"Annuities","explain":"Accumulation is the pay-in phase with tax-deferred growth. Source: standard annuity definitions. Source: SEC: Variable Annuities.","source":"SEC: Variable Annuities https://www.sec.gov/investor/pubs/varannty.htm"},{"q":"Annuitization means:","choices":["Paying premiums monthly","Converting the accumulated value into periodic income","Surrendering the annuity for cash","Buying life insurance inside the annuity"],"answer":1,"topic":"Annuities","explain":"Annuitization converts value into income payments. Source: standard annuity definitions. Source: SEC: Variable Annuities.","source":"SEC: Variable Annuities https://www.sec.gov/investor/pubs/varannty.htm"},{"q":"A variable annuity's owner generally bears:","choices":["The insurer's credit risk","No risk","Only mortality risk","The investment risk"],"answer":3,"topic":"Annuities","explain":"Variable annuity returns depend on subaccount results. Source: standard annuity product terms. Source: SEC: Variable Annuities.","source":"SEC: Variable Annuities https://www.sec.gov/investor/pubs/varannty.htm"},{"q":"For a non-annuitized deferred annuity withdrawal, gains come out:","choices":["First, taxed as ordinary income (LIFO)","Last, after principal","Tax-free","Pro rata"],"answer":0,"topic":"Annuities","explain":"Annuity withdrawals are LIFO. Source: IRC 72(e). Source: 26 U.S.C. 72(e)(2)(B), (e)(3)(A).","source":"26 U.S.C. 72(e)(2)(B), (e)(3)(A) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"The early withdrawal penalty on the taxable part of an annuity before 59½ is generally:","choices":["None","10%","5%","20%"],"answer":1,"topic":"Annuities","explain":"The 10% additional tax applies with exceptions. Source: IRC 72(q). Source: 26 U.S.C. 72(q).","source":"26 U.S.C. 72(q) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"The exclusion ratio on an annuity payout determines:","choices":["The surrender charge","The death benefit","The portion of each payment excluded from income","The commission rate"],"answer":2,"topic":"Annuities","explain":"The exclusion ratio excludes the return of after-tax premium. Source: IRC 72(b). Source: 26 U.S.C. 72(b).","source":"26 U.S.C. 72(b) https://www.law.cornell.edu/uscode/text/26/72"},{"q":"A fixed indexed annuity's interest floor is typically:","choices":["0%","10%","Equal to the index return","Negative 5%"],"answer":0,"topic":"Annuities","explain":"Source: NAIC Buyer's Guide to Fixed Deferred Annuities. Fixed indexed annuity interest is guaranteed never to be less than zero, even if the market goes down.","source":"NAIC Buyer's Guide to Fixed Deferred Annuities https://content.naic.org/sites/default/files/publication-anb-lp-consumer-annuities-fixed.pdf"},{"q":"An immediate annuity generally:","choices":["Requires no premium","Is always a variable product","Begins payments within one payment interval after purchase","Has a multi-year accumulation period"],"answer":2,"topic":"Annuities","explain":"Immediate annuities begin payouts right after purchase. Source: standard annuity definitions. Source: NAIC Glossary of Insurance Terms.","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"A pre-existing condition exclusion in individual health policies is:","choices":["Required by law","Mandatory for all group plans","The same as a waiting period","Prohibited for most individual plans under the ACA"],"answer":3,"topic":"Individual Health and Accident Policy Provisions","explain":"The Affordable Care Act bars pre-existing condition exclusions in most plans. Source: 42 U.S.C. 300gg-3.","source":"42 U.S.C. 300gg-3 https://www.law.cornell.edu/uscode/text/42/300gg-3"},{"q":"A guaranteed renewable health policy means the insurer:","choices":["Need not renew","Must renew the policy on its anniversary","May cancel at any time","Must renew at the same premium forever"],"answer":1,"topic":"Individual Health and Accident Policy Provisions","explain":"Source: IRMI Glossary (guaranteed renewable). The provision requires the insurer to renew the policy on its anniversary; see also 45 CFR 146.152, which requires the issuer to renew or continue coverage.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/guaranteed-renewable"},{"q":"A grace period in a health policy generally gives the insured time to:","choices":["Change the policy form","Choose a provider","Pay an overdue premium without losing coverage","File a claim"],"answer":2,"topic":"Individual Health and Accident Policy Provisions","explain":"Grace periods protect coverage after a late premium. Source: standard health policy provisions. Source: La. R.S. 22:977.","source":"La. R.S. 22:977 https://legis.la.gov/Legis/Law.aspx?d=507814"},{"q":"A reinstatement provision applies:","choices":["Before any premium is due","Only to group plans","Only at policy issue","After a policy lapses for nonpayment"],"answer":3,"topic":"Individual Health and Accident Policy Provisions","explain":"Reinstatement restores a lapsed policy. Source: standard health policy provisions. Source: La. R.S. 22:975(A)(2).","source":"La. R.S. 22:975(A)(2) https://legis.la.gov/Legis/Law.aspx?d=507812"},{"q":"A free look provision in a Louisiana individual health policy allows the insured to:","choices":["Review the policy for ten days after receipt","Review the policy only before paying premium","Have no review period","Receive a premium increase"],"answer":0,"topic":"Individual Health and Accident Policy Provisions","explain":"Source: La. R.S. 22:973(7)(a). The policy must give notice that ten days are allowed from receipt of the policy to review it.","source":"La. R.S. 22:973 https://legis.la.gov/Legis/Law.aspx?d=507810"},{"q":"Coordination of benefits generally prevents:","choices":["A deductible from applying","Total payments from multiple plans exceeding allowable expenses","A single insurer from paying","Any use of a second plan"],"answer":1,"topic":"Individual Health and Accident Policy Provisions","explain":"COB limits total recovery to allowable expenses. Source: NAIC model COB provisions. Source: NAIC Glossary of Insurance Terms.","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"An exclusion for a named condition in a health policy is best described as:","choices":["A premium surcharge","A grace period","A deductible","A limitation on coverage for that condition"],"answer":3,"topic":"Individual Health and Accident Policy Provisions","explain":"An exclusion removes coverage for a named condition. Source: standard health policy terminology. Source: La. R.S. 22:975(A)(13)(b).","source":"La. R.S. 22:975(A)(13)(b) https://legis.la.gov/Legis/Law.aspx?d=507812"},{"q":"A hospital indemnity policy generally pays:","choices":["A fixed daily benefit for hospital stays","Actual costs only","Doctor fees only","Prescription drugs only"],"answer":0,"topic":"Individual Health and Accident Policy Provisions","explain":"Hospital indemnity pays a fixed daily amount. Source: standard health insurance terminology. Source: NAIC Glossary of Insurance Terms.","source":"NAIC Glossary of Insurance Terms https://content.naic.org/glossary-insurance-terms"},{"q":"An own-occupation definition of disability means the insured cannot:","choices":["Perform any gainful work","Perform the duties of their own occupation","Perform any work at all","Earn any income"],"answer":1,"topic":"Disability Income and Related Insurance","explain":"Own occupation looks at the insured's specific job. Source: standard disability terminology. Source: NAIC Consumer Insight: Simplifying the Complications of Disability Insurance.","source":"NAIC Consumer Insight: Simplifying the Complications of Disability Insurance https://content.naic.org/article/consumer-insight-simplifying-complications-disability-insurance"},{"q":"The elimination period in disability insurance is:","choices":["The premium grace period","The conversion period","The waiting period before benefits begin","The maximum benefit period"],"answer":2,"topic":"Disability Income and Related Insurance","explain":"The elimination period is the waiting time before benefits start. Source: standard disability terminology. Source: IRMI Glossary.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/elimination-period"},{"q":"A residual disability benefit pays:","choices":["The full benefit for any disability","Nothing unless the insured is totally disabled","Only after age 65","A portion of the benefit in proportion to income lost"],"answer":3,"topic":"Disability Income and Related Insurance","explain":"Residual benefits pay in proportion to income loss. Source: standard disability terminology. Source: Missouri 20 CSR 400-2.060 (Cornell LII); NAIC consumer article.","source":"Missouri 20 CSR 400-2.060 (Cornell LII); NAIC consumer article https://www.law.cornell.edu/regulations/missouri/20-CSR-400-2-060"},{"q":"A benefit period in disability insurance is:","choices":["The maximum length of time benefits may be paid","The waiting period","The premium term","The age of the insured"],"answer":0,"topic":"Disability Income and Related Insurance","explain":"The benefit period is the maximum payout period. Source: standard disability terminology. Source: NAIC Consumer Insight: Simplifying the Complications of Disability Insurance.","source":"NAIC Consumer Insight: Simplifying the Complications of Disability Insurance https://content.naic.org/article/consumer-insight-simplifying-complications-disability-insurance"},{"q":"Presumptive disability generally means:","choices":["Disability only for the first 30 days","Loss of certain listed body functions counts as total disability","Any absence from work","Partial disability only"],"answer":1,"topic":"Disability Income and Related Insurance","explain":"Presumptive disability is triggered by listed severe impairments. Source: standard disability policy terms. Source: 38 U.S.C. 1914 (Cornell LII).","source":"38 U.S.C. 1914 (Cornell LII) https://www.law.cornell.edu/uscode/text/38/1914"},{"q":"Partial disability benefits generally:","choices":["Pay nothing","Pay only after age 65","Pay a reduced amount when the insured can work part-time","Pay full benefits"],"answer":2,"topic":"Disability Income and Related Insurance","explain":"Source: IRMI Glossary (partial disability insurance). The provision pays a partial benefit, usually about 50 percent of the total disability benefit, for a limited period.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/partial-disability-insurance"},{"q":"An HMO generally requires:","choices":["No network","Only out-of-network care","No premium","Members to use network providers and a PCP for referrals"],"answer":3,"topic":"Medical Plans","explain":"Source: California Department of Insurance, Types of Health Coverage, and HealthCare.gov Glossary. An HMO usually limits coverage to network providers and the primary care doctor makes referrals to specialists.","source":"California Department of Insurance, Types of Health Coverage https://www.insurance.ca.gov/01-consumers/110-health/10-basics/types.cfm"},{"q":"A PPO generally allows:","choices":["Out-of-network care at a higher cost","Only in-network care with no exceptions","No premium","Only referrals"],"answer":0,"topic":"Medical Plans","explain":"Source: HealthCare.gov Glossary (PPO). Members pay less in network but may use out-of-network providers for an additional cost.","source":"HealthCare.gov Glossary (PPO) https://www.healthcare.gov/glossary/preferred-provider-organization-ppo/"},{"q":"Medicare Part A primarily covers:","choices":["Vision exams","Inpatient hospital care","Prescription drugs","Dental care"],"answer":1,"topic":"Medical Plans","explain":"Part A covers hospital care. Source: CMS, Medicare.gov. Source: Medicare.gov, What Part A covers.","source":"Medicare.gov, What Part A covers https://www.medicare.gov/what-medicare-covers/what-part-a-covers"},{"q":"Medicare Part D covers:","choices":["Long-term custodial care","Dental care","Outpatient prescription drugs","Inpatient hospital stays"],"answer":2,"topic":"Medical Plans","explain":"Part D is the prescription drug benefit. Source: CMS, Medicare.gov. Source: Medicare.gov, Part D.","source":"Medicare.gov, Part D https://www.medicare.gov/health-drug-plans/part-d"},{"q":"Under an exclusive provider organization (EPO) plan, care is generally:","choices":["Covered at any provider with no limits","Not covered at all outside the network","Covered without any referral process","Covered only at network providers, with emergencies usually covered"],"answer":3,"topic":"Medical Plans","explain":"Source: California Department of Insurance, Types of Health Coverage. EPO members must use network providers; the exception is an emergency or urgent care situation.","source":"California Department of Insurance, Types of Health Coverage https://www.insurance.ca.gov/01-consumers/110-health/10-basics/types.cfm"},{"q":"Medicare Part B primarily covers:","choices":["Outpatient medical services","Inpatient hospital care","Prescription drugs","Long-term nursing home care"],"answer":0,"topic":"Medical Plans","explain":"Part B covers outpatient medical services. Source: CMS, Medicare.gov. Source: Medicare.gov, Doctor and other health care provider services.","source":"Medicare.gov, Doctor and other health care provider services https://www.medicare.gov/coverage/doctor-and-other-health-care-provider-services.html"},{"q":"COBRA continuation coverage generally lets a former employee keep group coverage for up to:","choices":["Lifetime","18 months","6 months","5 years"],"answer":1,"topic":"Group Health Insurance","explain":"COBRA generally provides up to 18 months for most job losses. Source: ERISA/COBRA, DOL. Source: 29 U.S.C. 1162 (ERISA COBRA) via Cornell LII.","source":"29 U.S.C. 1162 (ERISA COBRA) via Cornell LII https://www.law.cornell.edu/uscode/text/29/1162"},{"q":"HIPAA's portability rules mainly help people:","choices":["Avoid premiums","Choose any drug","Move between group plans without losing coverage history","Get free care"],"answer":2,"topic":"Group Health Insurance","explain":"Source: 29 U.S.C. 1181 (HIPAA portability). A preexisting condition exclusion period is reduced by prior creditable coverage, so coverage history carries over between group plans. (The ACA later barred most preexisting exclusions.)","source":"29 U.S.C. 1181 (ERISA, HIPAA portability) via Cornell LII https://www.law.cornell.edu/uscode/text/29/1181"},{"q":"A noncontributory group health plan is one where:","choices":["The employee pays the full premium","The employer and employee split the cost","There is no premium","The employer pays the full premium"],"answer":3,"topic":"Group Health Insurance","explain":"Source: IRMI Glossary (noncontributory insurance). The employer pays the entire premium and the employee does not contribute.","source":"IRMI Glossary (noncontributory insurance) https://www.irmi.com/term/insurance-definitions/noncontributory-insurance"},{"q":"A group certificate of insurance is:","choices":["A summary of the employee's coverage, not the full contract","The full master contract","A premium receipt","A claim form"],"answer":0,"topic":"Group Health Insurance","explain":"The certificate summarizes coverage; the master policy is the full contract. Source: standard group insurance terminology. Source: IRMI glossary: group certificate.","source":"IRMI glossary: group certificate https://www.irmi.com/term/insurance-definitions/group-certificate"},{"q":"Medicare's initial enrollment period generally lasts how long around a person's 65th birthday?","choices":["Three years","Seven months","Two months","One year"],"answer":1,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"The initial enrollment period is seven months around age 65. Source: CMS, Medicare.gov. Source: Medicare.gov, When does Medicare coverage start.","source":"Medicare.gov, When does Medicare coverage start https://www.medicare.gov/basics/get-started-with-medicare/sign-up/when-does-medicare-coverage-start"},{"q":"Medicare Supplement (Medigap) policies are designed to:","choices":["Cover dental care only","Cover only prescription drugs","Pay costs that Original Medicare does not cover","Replace Medicare entirely"],"answer":2,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Medigap pays gaps like coinsurance and deductibles. Source: CMS, Medicare.gov. Source: CMS, Medigap.","source":"CMS, Medigap https://www.cms.gov/medicare/health-drug-plans/medigap"},{"q":"Long-term care insurance benefits are generally triggered when the insured:","choices":["Turns 65","Has a cold","Retires","Cannot perform a set number of activities of daily living, or has severe cognitive impairment"],"answer":3,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Source: 26 U.S.C. 7702B(c)(2). A tax-qualified LTC policy pays for a chronically ill person: unable to perform at least 2 of 6 activities of daily living, or needing substantial supervision because of severe cognitive impairment.","source":"26 U.S.C. 7702B via Cornell LII https://www.law.cornell.edu/uscode/text/26/7702B"},{"q":"A skilled nursing facility provides:","choices":["Daily skilled nursing or rehabilitative care","Only help with meals","Only home visits by volunteers","Only dental care"],"answer":0,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Source: 42 CFR 409.31 and Medicare.gov (Nursing home care). Skilled nursing facility care means skilled nursing or skilled rehabilitation services needed on a daily basis.","source":"42 CFR 409.31 via Cornell LII https://www.law.cornell.edu/cfr/text/42/409.31"},{"q":"Custodial care means:","choices":["Prescription drugs","Non-medical help with daily living activities","Surgery","Emergency room care"],"answer":1,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Source: Medicare.gov, Nursing home care. Long-term (custodial) care is help with activities of daily living such as bathing, dressing, or eating.","source":"Medicare.gov, Nursing home care https://www.medicare.gov/coverage/nursing-home-care"},{"q":"Respite care is:","choices":["A surgical procedure","A premium discount","Short-term care that gives family caregivers a break","Permanent nursing home care"],"answer":2,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Source: IRMI Glossary (respite care). Respite care is temporary care that gives the relative or companion who normally provides care a break.","source":"IRMI Glossary (respite care) https://irmi.com/term/insurance-definitions/respite-care"},{"q":"A Medicare Advantage plan is generally:","choices":["Original Medicare with no changes","A dental-only plan","A supplement that pays Part B only","A private plan that replaces Original Medicare"],"answer":3,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Medicare Advantage (Part C) is an alternative to Original Medicare. Source: CMS, Medicare.gov. Source: HealthCare.gov Glossary (Medicare Advantage).","source":"HealthCare.gov Glossary (Medicare Advantage) https://www.healthcare.gov/glossary/medicare-advantage-medicare-part-c/"},{"q":"The Medigap open enrollment period for a new Medicare beneficiary generally lasts:","choices":["Six months after Part B coverage begins","One year","Two years","Until age 70"],"answer":0,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Source: Medicare.gov, Medigap Open Enrollment Period. Federal law gives a 6 month Medigap Open Enrollment Period that starts the first month you have Part B and are 65 or older.","source":"Medicare.gov, Medigap Open Enrollment Period https://www.medicare.gov/supplements-other-insurance/when-can-i-buy-medigap/guaranteed-issue-rights"},{"q":"Medicare Part C is:","choices":["A Medigap supplement","Medicare Advantage, a private plan alternative to Original Medicare","Prescription drug coverage only","A dental plan"],"answer":1,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Part C is Medicare Advantage. Source: CMS, Medicare.gov.","source":"Medicare.gov https://www.medicare.gov/basics/get-started-with-medicare/get-more-coverage/your-coverage-options"},{"q":"Long-term care services that help with daily living and are provided by non-medical staff are:","choices":["Acute hospital care","Surgery","Custodial care","Skilled nursing care"],"answer":2,"topic":"Insurance for Senior Citizens and Special Needs Individuals","explain":"Custodial care is non-medical daily help. Source: standard LTC terminology. Source: 42 CFR 409.33 (Cornell LII).","source":"42 CFR 409.33 (Cornell LII) https://www.law.cornell.edu/cfr/text/42/409.33"},{"q":"Life insurance death proceeds paid in a lump sum are generally:","choices":["Taxable to the beneficiary","Subject to a 10% penalty","Deductible by the estate","Income-tax-free to the beneficiary"],"answer":3,"topic":"Federal Tax Considerations for Life and Health Insurance","explain":"Death benefits are generally excluded under IRC 101(a). Source: IRC 101(a). Source: 26 U.S.C. 101 (Cornell LII).","source":"26 U.S.C. 101 (Cornell LII) https://www.law.cornell.edu/uscode/text/26/101"},{"q":"Accelerated death benefits paid to a terminally ill insured are generally:","choices":["Income-tax-free","Taxable as ordinary income","Subject to a 10% penalty","Deductible"],"answer":0,"topic":"Federal Tax Considerations for Life and Health Insurance","explain":"Terminal-illness accelerated benefits are generally tax-free under IRC 101(g). Source: IRC 101(g). Source: 26 U.S.C. 101(g) (Cornell LII).","source":"26 U.S.C. 101(g) (Cornell LII) https://www.law.cornell.edu/uscode/text/26/101"},{"q":"Benefits received under a qualified long-term care contract are generally:","choices":["Deductible to the insured","Often excluded from income up to federal limits","Always taxable","Subject to a 10% penalty"],"answer":1,"topic":"Federal Tax Considerations for Life and Health Insurance","explain":"Qualified LTC benefits are generally excluded from income within federal limits. Source: IRC section 7702B; confirm current limits. Source: 26 U.S.C. 7702B (Cornell LII).","source":"26 U.S.C. 7702B (Cornell LII) https://www.law.cornell.edu/uscode/text/26/7702B"},{"topic":"Types of Life Insurance Policies","q":"A 20-year term policy is in force when the insured outlives the 20 years. What happens to the policy?","choices":["It converts automatically to whole life","It expires with no payout","It pays out its accumulated cash value","It pays the face amount to the owner"],"answer":1,"explain":"Source: IRMI Glossary, Term Life Insurance. Term coverage lasts only a set period; if the insured survives the term the policy expires, and a term policy has no cash value build-up.","verdict":"confirmed","source":"IRMI Glossary, Term Life Insurance https://www.irmi.com/term/insurance-definitions/term-life-insurance"},{"topic":"Types of Life Insurance Policies","q":"Which feature most clearly distinguishes whole life from term insurance?","choices":["Premiums that change each year with market returns","Coverage that ends at a fixed number of years","Death benefit payable whenever death occurs","A death benefit that varies with a separate account"],"answer":2,"explain":"Source: IRMI Glossary, Whole Life Insurance. Whole life is permanent coverage that pays the face value upon death regardless of when it occurs, unlike term, which pays only if death occurs during the term.","verdict":"corrected","source":"IRMI Glossary, Whole Life Insurance https://www.irmi.com/term/insurance-definitions/whole-life-insurance"},{"topic":"Types of Life Insurance Policies","q":"In a universal life policy, what is deducted from the accumulated account balance each period?","choices":["The surrender charge on the full face amount","The mortality cost and the cost of any rider provisions","Only the agent's commission","The dividend declared for the year"],"answer":1,"explain":"Source: IRMI Glossary, Universal Life Insurance. Universal life is unbundled: premiums earn interest in an account from which the insurer deducts the mortality cost and the cost of rider provisions.","verdict":"confirmed","source":"IRMI Glossary, Universal Life Insurance https://www.irmi.com/term/insurance-definitions/universal-life-insurance"},{"topic":"Types of Life Insurance Policies","q":"In a variable universal life policy, how is the interest earned on funds placed in the investment accounts treated?","choices":["Guaranteed at a minimum rate set by the state","Fixed for the life of the contract","Not guaranteed and may fall with market performance","Credited only after the insured reaches age 65"],"answer":2,"explain":"Source: NAIC, Life Insurance. In variable universal life the cash funds are placed in investment accounts, and the interest earned is not guaranteed and may decrease depending on market performance.","verdict":"confirmed","source":"NAIC, Life Insurance (Insurance Topics) https://content.naic.org/insurance-topics/life-insurance"},{"topic":"Policy Provisions, Options, and Riders","q":"Under Louisiana's individual life standard provisions, what is the minimum grace period for premiums after the first?","choices":["Ten days","Fifteen days","Forty-five days","Thirty days or one month"],"answer":3,"explain":"Source: La. R.S. 22:931. An individual life policy must give a grace period of thirty days or, at the insurer's option, one month for payment of any premium after the first.","verdict":"confirmed","source":"Louisiana R.S. 22:931 (Life insurance policies; standard provisions) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"topic":"Policy Provisions, Options, and Riders","q":"A Louisiana individual life policy lapsed for nonpayment. Within what period from the date of default must the policy allow reinstatement?","choices":["Three years","Six months","Ninety days","Ten years"],"answer":0,"explain":"Source: La. R.S. 22:931. The policy must provide that it will be reinstated at any time within three years from the date of default, subject to the stated conditions.","verdict":"confirmed","source":"Louisiana R.S. 22:931 (Life insurance policies; standard provisions) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"topic":"Policy Provisions, Options, and Riders","q":"After a premium default, a policyholder takes no action on nonforfeiture options. Under Louisiana's standard nonforfeiture law, what applies?","choices":["The policy terminates with no value","The policy is paid in cash within 60 days","The insurer refunds all premiums paid","The paid-up benefit stated in the policy applies"],"answer":3,"explain":"Source: La. R.S. 22:936. After default, the insurer grants the paid-up nonforfeiture benefit stipulated in the policy unless the policyholder elects another available option within 60 days of the missed due date.","verdict":"confirmed","source":"Louisiana R.S. 22:936 (Standard Nonforfeiture Law for Life Insurance) https://legis.la.gov/Legis/Law.aspx?d=507792"},{"topic":"Policy Provisions, Options, and Riders","q":"An insured dies by self-destruction 14 months after a Louisiana individual life policy was issued. Which statement fits the suicide provision?","choices":["The exclusion may apply because death occurred within two years of issue","The exclusion cannot apply after the first policy year","The exclusion applies only if the insured was sane","The exclusion applies for the first ten years"],"answer":0,"explain":"Source: La. R.S. 22:931. A policy may exclude self-destruction, sane or insane, within two years from the date of issue.","verdict":"confirmed","source":"Louisiana R.S. 22:931 (Life insurance policies; standard provisions) https://legis.la.gov/Legis/Law.aspx?d=507787"},{"topic":"Policy Provisions, Options, and Riders","q":"After the incontestable period ends, an insurer may still contest a claim for which reason?","choices":["A misstatement in the application","Nonpayment of premium","The insured's occupation","An undisclosed prior illness"],"answer":1,"explain":"Source: IRMI Glossary, Incontestable Clause. After the contestable period (usually 2 years) expires, claims cannot be contested for any reason other than nonpayment of premium.","verdict":"confirmed","source":"IRMI Glossary, Incontestable Clause https://www.irmi.com/term/insurance-definitions/incontestable-clause"},{"topic":"Annuities","q":"Which statement correctly contrasts fixed and variable annuities?","choices":["Both guarantee the rate of return","The fixed annuity return depends on subaccount performance","The variable annuity guarantees the rate of return","The fixed annuity guarantees the rate of return"],"answer":3,"explain":"Source: FINRA, Annuities. With a fixed annuity the insurer guarantees the rate of return, while a variable annuity lacks certain guarantees and is affected by market fluctuations.","verdict":"confirmed","source":"FINRA, Annuities https://www.finra.org/investors/investing/investment-products/annuities"},{"topic":"Annuities","q":"What is a surrender charge on an annuity?","choices":["A fee for withdrawing money during the surrender period","A fee charged only when the annuitant dies","A tax on annuity payments","A commission refunded at annuitization"],"answer":0,"explain":"Source: FINRA, Annuities. A surrender charge is the penalty fee owed by a contract owner who sells or withdraws money from the annuity during the surrender period.","verdict":"confirmed","source":"FINRA, Annuities https://www.finra.org/investors/investing/investment-products/annuities"},{"topic":"Annuities","q":"How is the exclusion ratio for annuity payments figured?","choices":["Expected return divided by investment in the contract","Investment in the contract divided by expected return","Monthly payment divided by the account value","Net cost divided by the number of payments"],"answer":1,"explain":"Source: IRS Publication 939. The exclusion percentage is investment in the contract divided by expected return; once the net cost has been recovered, payments are fully taxable.","verdict":"confirmed","source":"IRS Publication 939 (General Rule for Pensions and Annuities) https://www.irs.gov/publications/p939"},{"topic":"Louisiana Insurance Regulation","q":"Under the Louisiana Life and Health Insurance Guaranty Association Law, which statement about an agent's marketing is correct?","choices":["An agent may cite the association's protection to reassure a prospect about a weaker insurer","An agent may cite the association only if the insurer is a member","An agent may not use the association's existence to induce a purchase of covered insurance","An agent may cite the association freely in written advertising but not orally"],"answer":2,"explain":"Source: Louisiana Legislature, R.S. 22:2098. No person, including a member insurer or agent, may use the association's existence for sales solicitation or inducement to purchase covered insurance, in written or oral statements.","source":"Louisiana Legislature, R.S. 22:2098 https://legis.la.gov/Legis/Law.aspx?d=509256"},{"topic":"Louisiana Insurance Regulation","q":"How does Louisiana law characterize the Louisiana Insurance Guaranty Association?","choices":["A state agency funded by general fund appropriations","A private nonprofit entity that is not a state department, agency, or instrumentality","A division of the Department of Insurance","A federal corporation backed by the state treasury"],"answer":1,"explain":"Source: Louisiana Legislature, R.S. 22:2056. The association is a private nonprofit unincorporated legal entity, not a department, agency, or instrumentality of the state, and its debts are not the state's.","source":"Louisiana Legislature, R.S. 22:2056 https://legis.la.gov/Legis/Law.aspx?d=509175"},{"topic":"Life, Health, and Accident Insurance Basics","q":"Which best describes insurable interest?","choices":["A financial or legal stake in the subject of insurance","The interest rate credited to a cash value","The agent's commission on a sale","The insurer's right to cancel"],"answer":0,"explain":"Source: IRMI Glossary. Insurable interest is an interest by the insured in the value of the subject of insurance, usually resulting from property rights, contract rights, and potential legal liability.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/insurable-interest"},{"topic":"Life, Health, and Accident Insurance Basics","q":"Indemnity in insurance means:","choices":["Payment of a bonus above the actual loss","Compensation to a party for a loss or damage that has already occurred","A refund of all premiums paid","A penalty for late payment"],"answer":1,"explain":"Source: IRMI Glossary. Indemnity is compensation to a party for a loss or damage that has already occurred.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/indemnity"},{"topic":"Life, Health, and Accident Insurance Basics","q":"In a mutual insurer, who owns the company?","choices":["Outside shareholders who hold no policies","The state government","Its policyholders","The agents who sell its products"],"answer":2,"explain":"Source: IRMI Glossary. A mutual company is owned by its insureds: every owner of a mutual insurer is an insured, and every insured is an owner.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/mutual-company"},{"topic":"Life, Health, and Accident Insurance Basics","q":"Which statement describes a stock insurer?","choices":["It is owned by its policyholders","It is owned by shareholders who contributed capital","It is owned by the state guaranty fund","It has no owners"],"answer":1,"explain":"Source: IRMI Glossary. A stock company has a capital fund paid in by stockholders, and its shares are usually traded on organized stock exchanges.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/stock-company"},{"topic":"Life, Health, and Accident Insurance Basics","q":"What is a grace period in an insurance policy?","choices":["Days after the premium due date during which the premium may still be paid and coverage stays in force","A period before the policy is issued","The time an insurer has to investigate a claim","A free-look period after delivery"],"answer":0,"explain":"Source: IRMI Glossary. A grace period allows the insured a certain number of days (e.g., 30 or 31) after the premium due date to pay if the insurance is to stay in force.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/grace-period"},{"topic":"Life, Health, and Accident Insurance Basics","q":"The incontestable clause limits an insurer's ability to do what?","choices":["Raise premiums after issue","Contest claims after a stated period, usually 2 years","Cancel for nonpayment","Change the beneficiary"],"answer":1,"explain":"Source: IRMI Glossary. The clause sets a period (usually 2 years) during which the insurer may contest claims; afterward claims cannot be contested other than for nonpayment of premium.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/incontestable-clause"},{"topic":"Life, Health, and Accident Insurance Basics","q":"In a disability income policy, the elimination period is:","choices":["The period during which premiums are waived after benefits end","The maximum length of time benefits are paid","The waiting time that must pass before benefits become payable","The time allowed to file a claim"],"answer":2,"explain":"Source: IRMI Glossary. An elimination period is a waiting or probationary period that must run before benefits are payable under a disability income policy.","source":"IRMI Glossary https://www.irmi.com/term/insurance-definitions/elimination-period"},{"topic":"Individual Health and Accident Policy Provisions","q":"Under the time limit on certain defenses provision of an individual health policy, a claim for a loss commencing after how long from the date of issue cannot be denied because of a preexisting condition not excluded by name or specific description?","choices":["One year","Two years","Three years","Five years"],"answer":2,"explain":"Source: Louisiana Legislature, R.S. 22:975. Paragraph (A)(13)(b) bars reducing or denying a claim for loss commencing after three years from issue on the ground of a preexisting condition not excluded by name or specific description.","source":"Louisiana Legislature, R.S. 22:975 https://legis.la.gov/Legis/Law.aspx?d=507812"},{"topic":"Individual Health and Accident Policy Provisions","q":"Under the required notice of claim provision, written notice of claim for sickness must generally be given to the insurer within how many days after the disability begins?","choices":["10 days","20 days","30 days","60 days"],"answer":1,"explain":"Source: Louisiana Legislature, R.S. 22:975. Paragraph (A)(3) requires written notice of claim within twenty days after the accident or the start of disability from sickness (ten days for industrial policies).","source":"Louisiana Legislature, R.S. 22:975 https://legis.la.gov/Legis/Law.aspx?d=507812"}],"scenarios":[],"pairs":[]}};
